                        >
                          <GripVertical className="h-5 w-5 text-muted-foreground" />
                        </div>

                        {/* Sequence number */}
                        <div className="w-12 text-center">
                          <span className="text-sm font-medium text-muted-foreground">
                            #{index + 1}
