          <TooltipTrigger asChild>
            <Button
              variant={isAdvancedSearchOpen ? "secondary" : "outline"}
              size="sm"
              onClick={onAdvancedSearchToggle}
              className="h-9 gap-2 px-3 text-sm font-medium"
            >
              <SlidersHorizontal className="h-4 w-4" />
