              {advancedFilterCount > 0 && (
                <Badge variant="default" className="h-4 px-1 text-[10px] min-w-[16px]">
                  {advancedFilterCount}
                </Badge>
              )}
            </Button>
          </TooltipTrigger>
          <TooltipContent>Advanced Search</TooltipContent>
        </Tooltip>

        {canCreate && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="outline"
