/**
 * The right-hand panel: how a step is set up, and what it actually did.
 *
 * Putting the last run's input and output directly under the fields that
 * produced them is the one idea worth taking from a canvas-style editor. The
 * question an author has while configuring a step is almost always "did that
 * do what I meant", and answering it in the same panel removes a trip to a
 * separate run view — along with the guessing that happens on the way back.
 */

import { useMemo } from "react";
import {
  type AutomationStep,
  type AvailableValue,
  type Condition,
  LOOP_MIN_PASSES,
  type Loop,
  OPERATORS,
  operatorArity,
  STEP_FIELDS,
  STEP_GLYPHS,
  STEP_HINTS,
  STEP_LABELS,
} from "@/lib/automation/model";
import { cn } from "@/lib/utils";

/* -------------------------------------------------------------------------- */
/*  Run output                                                                 */
/* -------------------------------------------------------------------------- */

export interface StepRunResult {
  status: "ok" | "failed" | "skipped";
  durationMs?: number;
  input?: Record<string, unknown>;
  output?: Record<string, unknown>;
  /** Plain-words summary of why the step produced what it did. */
  note?: string;
  error?: string;
  /** True when the step was edited after this run, so the result is out of date. */
  stale?: boolean;
}

function ValueRows({ values }: { values: Record<string, unknown> }) {
  const entries = Object.entries(values);
  if (entries.length === 0) {
    return <div className="px-3 py-1.5 text-xs text-muted-foreground">Nothing</div>;
  }
  return (
    <>
      {entries.map(([k, v]) => (
        <div
          key={k}
          className="flex gap-3 border-t border-border/60 px-3 py-1.5 text-xs first:border-t-0"
        >
          <span className="font-mono text-[11px] text-muted-foreground">{k}</span>
          <span className="ml-auto font-semibold tabular-nums">{formatValue(v)}</span>
        </div>
      ))}
    </>
  );
}

function formatValue(v: unknown): string {
  if (typeof v === "string") return `"${v}"`;
  if (v === null || v === undefined) return "—";
  return String(v);
}

function RunOutput({
  result,
  resultName,
  onRerun,
}: {
  result: StepRunResult;
  resultName: string;
  onRerun?: () => void;
}) {
  return (
    <section className="-mx-4 mt-1 border-t border-border bg-muted/40 px-4 py-4">
      <div className="mb-3 flex items-center gap-2">
        <span
          aria-hidden="true"
          className={cn(
            "grid h-[22px] w-[22px] place-items-center rounded-md border text-[11px]",
            result.status === "ok"
              ? "border-primary/30 bg-primary/10 text-primary"
              : result.status === "failed"
                ? "border-red-200 bg-red-50 text-red-600"
                : "border-border bg-muted text-muted-foreground"
          )}
        >
          {result.status === "ok" ? "✓" : result.status === "failed" ? "!" : "–"}
        </span>
        <h4 className="text-[10.5px] font-bold uppercase tracking-[0.09em] text-muted-foreground">
          What this step did
        </h4>
        <span className="ml-auto text-[11px] text-muted-foreground">
          last test run
          {typeof result.durationMs === "number" ? ` · ${result.durationMs} ms` : ""}
        </span>
      </div>

      {result.status === "failed" && result.error ? (
        <p className="mb-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {result.error}
        </p>
      ) : null}

      {result.input ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Went in
          </div>
          <ValueRows values={result.input} />
        </div>
      ) : null}

      {result.note ? (
        <p className="mb-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-800">
          {result.note}
        </p>
      ) : null}

      {result.output ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="flex border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Came out
            {resultName ? <span className="ml-auto text-primary">as {resultName}</span> : null}
          </div>
          <ValueRows values={result.output} />
        </div>
      ) : null}

      {onRerun ? (
        <button
          type="button"
          onClick={onRerun}
          className="w-full rounded-lg border border-border bg-card py-2 text-xs font-semibold hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          Run this step again
        </button>
      ) : null}

      {result.stale ? (
        <p className="mt-2 flex gap-1.5 text-[11.5px] leading-snug text-amber-700">
          <span aria-hidden="true">⚠</span>
          <span>You changed this step since that run. Re-run to see what it does now.</span>
        </p>
      ) : null}
    </section>
  );
}

/* -------------------------------------------------------------------------- */
/*  Field primitives                                                           */
/* -------------------------------------------------------------------------- */

function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: React.ReactNode;
  children: React.ReactNode;
}) {
  // A real <label> wrapping the control, not a styled <span> beside it: without
  // it the selects announce as "combobox" with no name at all, which is the
  // difference between a usable panel and an unusable one on a screen reader.
  return (
    <label className="mb-3.5 block">
      <span className="mb-1.5 block text-[11px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">
        {label}
      </span>
      {children}
      {hint ? (
        <p className="mt-1.5 text-[11.5px] leading-snug text-muted-foreground">{hint}</p>
      ) : null}
    </label>
  );
}

const inputClass =
  "w-full rounded-lg border border-input bg-card px-3 py-2 text-sm focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

export function Ref({ children }: { children: React.ReactNode }) {
  return (
    <code className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[11px] text-primary">
      {children}
    </code>
  );
}

/* -------------------------------------------------------------------------- */
/*  Step inspector                                                             */
/* -------------------------------------------------------------------------- */

interface StepInspectorProps {
  step: AutomationStep;
  index: number;
  available: AvailableValue[];
  ruleTables: { id: string; name: string; rowCount: number; outputs: string[] }[];
  entities: string[];
  fieldsFor: (entity: string) => string[];
  run?: StepRunResult;
  onChange: (next: AutomationStep) => void;
  onRerun?: () => void;
  onOpenRuleTable?: (name: string) => void;
}

export function StepInspector({
  step,
  index,
  available,
  ruleTables,
  entities,
  fieldsFor,
  run,
  onChange,
  onRerun,
  onOpenRuleTable,
}: StepInspectorProps) {
  const setProp = (key: string, value: string) =>
    onChange({ ...step, props: { ...step.props, [key]: value } });

  const table = useMemo(
    () => ruleTables.find((t) => t.name === step.props.ruleTable),
    [ruleTables, step.props.ruleTable]
  );

  const fields = STEP_FIELDS[step.type] ?? [];

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-primary/30 bg-primary/10 text-sm text-primary"
        >
          {STEP_GLYPHS[step.type]}
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-primary">
            Step {index + 1} · Then do this
          </span>
          <h3 className="text-[15px] font-bold">{STEP_LABELS[step.type]}</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">{STEP_HINTS[step.type]}</p>

        {/* One list per step, not per field: every input that offers references
            points at this id, and emitting it only under some fields left the
            others with an autocomplete that quietly did nothing. */}
        <datalist id={`vals-${step.id}`}>
          {available.map((v) => (
            <option key={v.path} value={`{{${v.path}}}`} />
          ))}
        </datalist>

        {fields.includes("ruleTable") ? (
          <Field
            label="Rule table"
            hint={
              table ? (
                <>
                  {table.rowCount} rows · decides{" "}
                  {table.outputs.map((o, i) => (
                    <span key={o}>
                      {i > 0 ? " and " : ""}
                      <Ref>{o}</Ref>
                    </span>
                  ))}
                  .{" "}
                  {onOpenRuleTable ? (
                    <button
                      type="button"
                      onClick={() => onOpenRuleTable(table.name)}
                      className="font-semibold text-primary hover:underline"
                    >
                      Open table →
                    </button>
                  ) : null}
                </>
              ) : (
                "Pick the table this step should ask."
              )
            }
          >
            <select
              className={inputClass}
              value={step.props.ruleTable ?? ""}
              onChange={(e) => setProp("ruleTable", e.target.value)}
            >
              <option value="">Choose a rule table…</option>
              {ruleTables.map((t) => (
                <option key={t.id} value={t.name}>
                  {t.name}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("entity") ? (
          <Field label="Record type">
            <select
              className={inputClass}
              value={step.props.entity ?? ""}
              onChange={(e) => setProp("entity", e.target.value)}
            >
              <option value="">Choose a record type…</option>
              {entities.map((e) => (
                <option key={e} value={e}>
                  {e}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("values") ? (
          <Field
            label="Columns to set"
            hint={
              <>
                One <code className="font-mono text-[11px]">column: value</code> per line. A value
                can be a reference to an earlier step, like <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.values ?? ""}
              onChange={(e) => setProp("values", e.target.value)}
              placeholder={"status: open\nraised_by: {{order.id}}"}
            />
          </Field>
        ) : null}

        {fields.includes("target") ? (
          <Field
            label="Which record"
            hint={
              <>
                The record to delete, usually a reference from an earlier step —{" "}
                <Ref>{"{{invoiceId}}"}</Ref>.
              </>
            }
          >
            <input
              className={inputClass}
              value={step.props.target ?? ""}
              onChange={(e) => setProp("target", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("field") ? (
          <Field label="Field to write">
            <select
              className={inputClass}
              value={step.props.field ?? ""}
              onChange={(e) => setProp("field", e.target.value)}
            >
              <option value="">Choose a field…</option>
              {fieldsFor(step.props.entity ?? "").map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("value") ? (
          <Field
            label="New value"
            hint={
              <>
                A fixed value, or a reference to an earlier step like{" "}
                <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <input
              className={inputClass}
              value={step.props.value ?? ""}
              onChange={(e) => setProp("value", e.target.value)}
              list={`vals-${step.id}`}
              placeholder="high"
            />
          </Field>
        ) : null}

        {fields.includes("operation") ? (
          <Field label="Operation">
            <select
              className={inputClass}
              value={step.props.operation ?? "set"}
              onChange={(e) => setProp("operation", e.target.value)}
            >
              {["set", "copy", "add", "subtract", "multiply", "divide"].map((op) => (
                <option key={op} value={op}>
                  {op}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("left") ? (
          <Field label="Value to work from">
            <input
              className={inputClass}
              value={step.props.left ?? ""}
              onChange={(e) => setProp("left", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("right") ? (
          <Field label="And this value" hint="Leave empty when the operation only needs one value.">
            <input
              className={inputClass}
              value={step.props.right ?? ""}
              onChange={(e) => setProp("right", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("method") ? (
          <Field label="Method">
            <select
              className={inputClass}
              value={step.props.method ?? "POST"}
              onChange={(e) => setProp("method", e.target.value)}
            >
              {["POST", "PUT", "PATCH", "GET", "DELETE"].map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("url") ? (
          <Field label="URL">
            <input
              className={inputClass}
              value={step.props.url ?? ""}
              onChange={(e) => setProp("url", e.target.value)}
              placeholder="https://example.com/hooks/orders"
            />
          </Field>
        ) : null}

        {fields.includes("body") ? (
          <Field
            label="Body"
            hint={
              <>
                JSON. References like <Ref>{"{{order.id}}"}</Ref> are filled in before sending.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.body ?? ""}
              onChange={(e) => setProp("body", e.target.value)}
            />
          </Field>
        ) : null}

        <Field
          label="Save the answer as"
          hint={
            step.resultName ? (
              <>
                Later steps can use <Ref>{`{{${step.resultName}}}`}</Ref>.
              </>
            ) : (
              "Leave empty if no later step needs this step's result."
            )
          }
        >
          <input
            className={inputClass}
            value={step.resultName}
            onChange={(e) => onChange({ ...step, resultName: e.target.value })}
            placeholder="tier"
          />
        </Field>

        {run ? <RunOutput result={run} resultName={step.resultName} onRerun={onRerun} /> : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Condition inspector                                                        */
/* -------------------------------------------------------------------------- */

export function ConditionInspector({
  condition,
  available,
  onChange,
}: {
  condition: Condition;
  available: AvailableValue[];
  onChange: (next: Condition) => void;
}) {
  const needsValue = operatorArity(condition.operator) === 1;

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-blue-200 bg-blue-50 text-sm text-blue-600"
        >
          ◇
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-blue-600">
            Only continue if
          </span>
          <h3 className="text-[15px] font-bold">A check</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          Every check must pass. To run on either of two cases, build two automations — each one
          then reports its own run history.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={condition.field}
            onChange={(e) => onChange({ ...condition, field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Test">
          <select
            className={inputClass}
            value={condition.operator}
            onChange={(e) => onChange({ ...condition, operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={condition.value}
              onChange={(e) => onChange({ ...condition, value: e.target.value })}
              placeholder="1000"
            />
          </Field>
        ) : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Loop inspector                                                             */
/* -------------------------------------------------------------------------- */

/**
 * The panel for a repeat.
 *
 * It edits one thing — the check that ends the loop — so most of the panel is
 * spent explaining the consequences instead. A repeat is the only construct in
 * the builder that can hang a request, and the place to say so is where someone
 * is deciding what to check, not in help they would have to go looking for.
 */
export function LoopInspector({
  loop,
  stepCount,
  available,
  onChange,
}: {
  loop: Loop;
  stepCount: number;
  available: AvailableValue[];
  onChange: (next: Loop) => void;
}) {
  const needsValue = operatorArity(loop.condition.operator) === 1;
  const set = (patch: Partial<Condition>) =>
    onChange({ ...loop, condition: { ...loop.condition, ...patch } });

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-teal-200 bg-teal-50 text-sm text-teal-700"
        >
          ↻
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-teal-700">
            Keep repeating
          </span>
          <h3 className="text-[15px] font-bold">A repeat</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          The {stepCount === 1 ? "step" : `${stepCount} steps`} inside run over and over while this
          check passes. It is re-checked before every pass, so something inside the repeat has to
          change what it looks at — otherwise it never stops.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={loop.condition.field}
            onChange={(e) => set({ field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Keep going while">
          <select
            className={inputClass}
            value={loop.condition.operator}
            onChange={(e) => set({ operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={loop.condition.value}
              onChange={(e) => set({ value: e.target.value })}
              placeholder="5"
            />
          </Field>
        ) : null}

        <Field
          label="Give up after (required)"
          hint="How many passes is obviously too many for this loop? There is no default — only you know what this work should cost."
        >
          <input
            className={inputClass}
            inputMode="numeric"
            value={loop.maxPasses}
            onChange={(e) => onChange({ ...loop, maxPasses: e.target.value })}
            placeholder="e.g. 10"
            aria-invalid={!loop.maxPasses.trim() || Number(loop.maxPasses) < LOOP_MIN_PASSES}
          />
        </Field>

        <div className="mb-4 rounded-lg border border-teal-200 bg-teal-50/60 p-3">
          <p className="text-[11.5px] font-semibold text-teal-800">
            Inside the repeat you can use {`{{${loop.id}.iteration}}`}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-teal-800/80">
            The pass number, counting from 1. Handy for writing an attempt count, or for building a
            value that changes each time round.
          </p>
        </div>

        <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50/60 p-3">
          <p className="text-[11.5px] font-semibold text-amber-900">
            If the check never fails, the run is stopped at{" "}
            {loop.maxPasses.trim() ? `${loop.maxPasses} passes` : "the limit you set"}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-amber-900/80">
            An automation runs inside the save that triggered it, so a repeat that cannot end holds
            the record open. Hitting the limit marks the whole run failed rather than letting it
            look like it finished.
          </p>
        </div>
      </div>
    </div>
  );
}

/**
 * One rung of the ladder.
 *
 * Every part of an automation is the same shape on screen — a coloured glyph, a
 * kicker naming which of the three parts it is, and the clause in plain words.
 * Keeping trigger, check and step identical in form is what lets someone read
 * the whole automation top to bottom without learning three card layouts.
 */

import { cn } from "@/lib/utils";

/**
 * `action` rather than `then` because an object keyed `then` is a thenable, and
 * `await`ing or dynamically importing anything holding it behaves oddly. The
 * label the author reads is still "Then do this".
 */
export type LadderKind = "when" | "if" | "action" | "loop";

const KIND_STYLES: Record<LadderKind, { icon: string; kicker: string; label: string }> = {
  when: {
    icon: "bg-amber-50 text-amber-700 border-amber-200",
    kicker: "text-amber-700",
    label: "When this happens",
  },
  if: {
    icon: "bg-blue-50 text-blue-600 border-blue-200",
    kicker: "text-blue-600",
    label: "Only continue if",
  },
  action: {
    icon: "bg-primary/10 text-primary border-primary/30",
    kicker: "text-primary",
    label: "Then do this",
  },
  // Teal rather than another shade of the accent: a repeat is control flow, not
  // a fourth kind of action, and it should not read as one at a glance.
  loop: {
    icon: "bg-teal-50 text-teal-700 border-teal-200",
    kicker: "text-teal-700",
    label: "Keep repeating",
  },
};

interface LadderCardProps {
  kind: LadderKind;
  glyph: string;
  /** The clause, already worded. Rendered as-is so the model owns the wording. */
  title: React.ReactNode;
  /** Shown after the kicker, e.g. "· step 2". */
  ordinal?: string;
  selected?: boolean;
  problem?: string;
  onSelect?: () => void;
  onRemove?: () => void;
}

export function LadderCard({
  kind,
  glyph,
  title,
  ordinal,
  selected = false,
  problem,
  onSelect,
  onRemove,
}: LadderCardProps) {
  const style = KIND_STYLES[kind];

  return (
    <div
      className={cn(
        "w-full rounded-xl border bg-card px-4 py-3 text-left shadow-sm transition-colors",
        selected
          ? "border-primary ring-[3px] ring-primary/10"
          : "border-border hover:border-primary/40",
        problem && !selected && "border-amber-300"
      )}
    >
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={onSelect}
          aria-current={selected ? "true" : undefined}
          className="flex flex-1 items-center gap-3 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 rounded-md"
        >
          <span
            aria-hidden="true"
            className={cn(
              "grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border text-sm",
              style.icon
            )}
          >
            {glyph}
          </span>
          <span className="min-w-0">
            <span
              className={cn("block text-[10px] font-bold uppercase tracking-[0.1em]", style.kicker)}
            >
              {style.label}
              {ordinal ? <span className="text-muted-foreground"> {ordinal}</span> : null}
            </span>
            <span className="mt-0.5 block text-sm">{title}</span>
          </span>
        </button>

        {onRemove ? (
          <button
            type="button"
            onClick={onRemove}
            aria-label="Remove this"
            className="shrink-0 rounded-md px-2 py-1 text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            ✕
          </button>
        ) : null}
      </div>

      {problem ? <p className="mt-2 pl-[42px] text-xs text-amber-700">{problem}</p> : null}
    </div>
  );
}

/**
 * A token inside a card's clause.
 *
 * `value` tokens are the parts the author chose — a literal, a name they gave a
 * result — and carry the accent so the editable bits of the sentence stand out
 * from the fixed words around them.
 */
export function Token({ children, value = false }: { children: React.ReactNode; value?: boolean }) {
  return (
    <span
      className={cn(
        "mx-0.5 inline-block rounded-md border px-1.5 py-0.5 font-semibold",
        value
          ? "border-primary/30 bg-primary/5 text-primary"
          : "border-border bg-muted text-foreground"
      )}
    >
      {children}
    </span>
  );
}

/**
 * The bracket drawn around the steps a loop repeats.
 *
 * A repeat is the one place the ladder stops being a flat list, so it needs to
 * look like containment rather than another rung: the steps inside are indented
 * behind a rail, and the rail carries the count of what it holds. Without the
 * frame the only clue that three steps repeat would be a word on a card above
 * them, which reads as a sequence, not a cycle.
 */
export function LoopFrame({
  children,
  stepCount,
  problem,
}: {
  children: React.ReactNode;
  stepCount: number;
  problem?: boolean;
}) {
  return (
    <div
      className={cn(
        "relative rounded-xl border-l-[3px] bg-teal-50/30 py-2 pl-4 pr-1",
        problem ? "border-l-amber-400" : "border-l-teal-300"
      )}
    >
      {children}
      <p className="mt-2 pl-1 text-[11px] text-teal-700">
        ↻ {stepCount === 1 ? "This step repeats" : `These ${stepCount} steps repeat`} until the
        check above fails
      </p>
    </div>
  );
}

/**
 * The connector between two cards, with the add button on it.
 *
 * The `+` lives on the rung rather than in a toolbar because that is where the
 * thing being added will end up — you point at the gap you want filled.
 */
export function LadderRung({ onAdd, active = false }: { onAdd: () => void; active?: boolean }) {
  return (
    <div className="relative h-6 w-0.5 bg-border" aria-hidden={false}>
      <button
        type="button"
        onClick={onAdd}
        aria-label="Add a condition or an action here"
        className={cn(
          "absolute left-1/2 top-1/2 grid h-[22px] w-[22px] -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border text-xs leading-none transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
          active
            ? "border-primary bg-primary text-primary-foreground"
            : "border-border bg-card text-muted-foreground hover:border-primary hover:text-primary"
        )}
      >
        +
      </button>
    </div>
  );
}

/**
 * The help screen for the builder.
 *
 * Written to be read by someone who has the builder open beside it, so every
 * section names what they can see rather than describing an abstraction. The
 * examples use the entities of whatever app this is running in — a generated
 * app's help says "Patient" and "Appointment", not "Order" and "Invoice" —
 * because a help page whose examples do not exist in your app is a help page
 * you have to translate before you can use.
 */

import { useState } from "react";
import {
  OPERATORS,
  STEP_GLYPHS,
  STEP_HINTS,
  STEP_LABELS,
  STEP_TYPES,
  TRIGGER_EVENTS,
  TRIGGER_HINTS,
  TRIGGER_LABELS,
} from "@/lib/automation/model";
import { cn } from "@/lib/utils";

export interface HelpExample {
  /** An entity in this app, used through the examples. */
  entity: string;
  /** A numeric field on it, e.g. "total". */
  numericField: string;
  /** A second entity a step could create, e.g. "Invoice". */
  relatedEntity: string;
}

const DEFAULT_EXAMPLE: HelpExample = {
  entity: "Order",
  numericField: "total",
  relatedEntity: "Invoice",
};

type SectionId =
  | "how"
  | "first"
  | "triggers"
  | "checks"
  | "steps"
  | "repeats"
  | "naming"
  | "references"
  | "tables"
  | "testing"
  | "failures";

const SECTIONS: { group: string; items: { id: SectionId; label: string }[] }[] = [
  {
    group: "Start here",
    items: [
      { id: "how", label: "How an automation runs" },
      { id: "first", label: "Build your first one" },
      { id: "triggers", label: "Picking a trigger" },
      { id: "checks", label: "Adding checks" },
      { id: "steps", label: "Adding steps" },
      { id: "repeats", label: "Repeating steps" },
    ],
  },
  {
    group: "Working with values",
    items: [
      { id: "naming", label: "Naming a step's result" },
      { id: "references", label: "Using earlier values" },
      { id: "tables", label: "Rule tables" },
    ],
  },
  {
    group: "Confidence",
    items: [
      { id: "testing", label: "Test runs" },
      { id: "failures", label: "Reading a failure" },
    ],
  },
];

export function AutomationHelp({
  example = DEFAULT_EXAMPLE,
  initialSection = "how",
  onClose,
}: {
  example?: HelpExample;
  initialSection?: SectionId;
  onClose?: () => void;
}) {
  const [section, setSection] = useState<SectionId>(initialSection);

  return (
    <div className="flex h-full min-h-0 flex-1">
      <nav
        aria-label="Help topics"
        className="w-[236px] shrink-0 overflow-y-auto border-r border-border bg-card py-4"
      >
        {SECTIONS.map((group) => (
          <div key={group.group}>
            <h2 className="px-[18px] pb-2 pt-3 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground first:pt-0">
              {group.group}
            </h2>
            {group.items.map((item) => (
              <button
                key={item.id}
                type="button"
                onClick={() => setSection(item.id)}
                aria-current={section === item.id ? "page" : undefined}
                className={cn(
                  "mx-2 block w-[calc(100%-1rem)] rounded-lg px-2.5 py-1.5 text-left text-[13px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
                  section === item.id
                    ? "bg-primary/10 font-semibold text-primary"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground"
                )}
              >
                {item.label}
              </button>
            ))}
          </div>
        ))}
      </nav>

      <div className="flex-1 overflow-y-auto bg-muted/30 px-8 py-7">
        {onClose ? (
          <button
            type="button"
            onClick={onClose}
            className="float-right rounded-md px-2 py-1 text-sm text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            ✕ Close
          </button>
        ) : null}
        <Section id={section} example={example} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */

function Section({ id, example }: { id: SectionId; example: HelpExample }) {
  switch (id) {
    case "how":
      return <HowItRuns example={example} />;
    case "first":
      return <FirstAutomation example={example} />;
    case "triggers":
      return <Triggers />;
    case "checks":
      return <Checks example={example} />;
    case "steps":
      return <Steps />;
    case "repeats":
      return <Repeats example={example} />;
    case "naming":
      return <Naming example={example} />;
    case "references":
      return <References example={example} />;
    case "tables":
      return <Tables />;
    case "testing":
      return <Testing />;
    case "failures":
      return <Failures />;
    default:
      return null;
  }
}

function H1({ children }: { children: React.ReactNode }) {
  return <h1 className="mb-2 text-[25px] font-bold tracking-tight">{children}</h1>;
}

function Lede({ children }: { children: React.ReactNode }) {
  return (
    <p className="mb-6 max-w-[66ch] text-[14.5px] leading-relaxed text-muted-foreground">
      {children}
    </p>
  );
}

function H2({ children }: { children: React.ReactNode }) {
  return <h2 className="mb-3 mt-7 text-[13px] font-bold first:mt-0">{children}</h2>;
}

function P({ children }: { children: React.ReactNode }) {
  return <p className="mb-3 max-w-[66ch] text-[14px] leading-relaxed">{children}</p>;
