/**
 * Give the administrator's assistant this application's model.
 *
 * The application ships with the `.eml.mmd` it was generated from, and the
 * backend embeds it at startup. This hook is the other end: a CopilotKit
 * action the model calls when it needs to know what the application actually
 * declares — which entities exist, what a rule decides, what a process does on
 * delete — rather than answering from what it remembers about ERDs in general.
 *
 * A search rather than a preloaded prompt for two reasons. The model is far
 * too large to send with every message, and making the lookup visible means an
 * administrator can see what the assistant consulted before acting on advice
 * about their production data.
 *
 */

import { useCopilotAction, useCopilotReadable } from '@copilotkit/react-core'
import { useCallback, useEffect, useState } from 'react'
import { apiClient } from '../lib/api-client'

interface RetrievedChunk {
  kind: string
  name: string
  text: string
  score: number
}

interface SearchResponse {
  chunks: RetrievedChunk[]
  ready?: boolean
}

export function useModelAssistant() {
  const [ready, setReady] = useState<boolean | null>(null)

  // Embedding happens in the background at startup, so the assistant needs to
  // know whether the model is searchable yet — otherwise an empty result early
  // in the application's life reads as "this application declares nothing".
  useEffect(() => {
    let cancelled = false
    apiClient
      .get<{ ready: boolean }>('/model-context/status')
      .then((response) => {
        if (!cancelled) setReady(Boolean(response?.ready))
      })
      .catch(() => {
        if (!cancelled) setReady(false)
      })
    return () => {
      cancelled = true
    }
  }, [])

  useCopilotReadable({
    description:
      "Whether this application's model has been indexed and can be searched with the " +
      'searchModel action.',
    value: { modelSearchable: ready },
    available: ready === null ? 'disabled' : 'enabled',
  })

  const search = useCallback(async ({ question }: { question: string }) => {
    try {
      const response = await apiClient.post<SearchResponse>('/model-context/search', {
        question,
        topK: 8,
      })

      if (!response?.chunks?.length) {
        return response?.ready === false
          ? "This application's model has not finished indexing yet. Say so rather than guessing."
          : 'Nothing in this application\'s model matches that. Say so rather than inventing an answer.'
      }

      return response.chunks
        .map((chunk) => `--- ${chunk.kind}: ${chunk.name} ---\n${chunk.text}`)
        .join('\n\n')
    } catch (error) {
      // Returned rather than thrown: the assistant can report that it could not
      // look something up and carry on, where a throw ends the turn.
      const message = error instanceof Error ? error.message : 'unknown error'
      return `The model search failed (${message}). Do not guess at the answer.`
    }
  }, [])

  useCopilotAction({
    name: 'searchModel',
    description:
      "Search this application's data model — its entities and their fields, the business " +
      'rules that run on them, and the multi-step processes that create, update and delete ' +
      'records. Use it before answering any question about how this application behaves, and ' +
      'before proposing a change to an entity, a rule or a workflow.',
    parameters: [
      {
        name: 'question',
        type: 'string',
        description:
          "What you need to know, in plain language — for example 'which processes write to " +
          "CAPA' or 'what happens when a stability test is deleted'.",
        required: true,
      },
    ],
    handler: search,
  })
}

import { useQuery } from "@tanstack/react-query";
import { useCallback, useMemo, useState } from "react";
import { apiClient, type PaginatedResponse } from "@/lib/api-client";

interface UseRecordNavigationOptions {
  endpoint: string;
  params?: Record<string, unknown>;
  limit?: number;
  enabled?: boolean;
}

interface RecordNavigationResult<T = Record<string, unknown>> {
  records: T[];
  totalCount: number;
  currentIndex: number;
  currentRecord: T | null;
  isLoading: boolean;
  error: Error | null;
  page: number;
  totalPages: number;
  setCurrentIndex: (index: number) => void;
  goFirst: () => void;
  goPrev: () => void;
  goNext: () => void;
  goLast: () => void;
  goToPage: (page: number) => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  refetch: () => void;
}

export function useRecordNavigation<T = Record<string, unknown>>({
  endpoint,
  params,
  limit = 100,
  enabled = true,
}: UseRecordNavigationOptions): RecordNavigationResult<T> {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [page, setPage] = useState(1);

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["ad-records", endpoint, params, page, limit],
    queryFn: () =>
      apiClient.get<PaginatedResponse<T>>(endpoint, {
        ...params,
        page,
        limit,
      }),
    enabled,
  });

  const records = useMemo(() => data?.data || [], [data]);
  const totalCount = data?.meta?.total || 0;
  const totalPages = data?.meta?.totalPages || 1;

  const currentRecord = records[currentIndex] || null;

  const goFirst = useCallback(() => {
    if (page > 1) {
      setPage(1);
      setCurrentIndex(0);
    } else {
      setCurrentIndex(0);
    }
  }, [page]);

  const goPrev = useCallback(() => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    } else if (page > 1) {
      setPage(page - 1);
      setCurrentIndex(limit - 1);
    }
  }, [currentIndex, page, limit]);

  const goNext = useCallback(() => {
    if (currentIndex < records.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else if (page < totalPages) {
      setPage(page + 1);
      setCurrentIndex(0);
    }
  }, [currentIndex, records.length, page, totalPages]);

  const goLast = useCallback(() => {
    if (page < totalPages) {
      setPage(totalPages);
      setCurrentIndex(0);
    } else {
      setCurrentIndex(records.length - 1);
    }
  }, [page, totalPages, records.length]);

  const goToPage = useCallback((newPage: number) => {
    setPage(newPage);
    setCurrentIndex(0);
  }, []);

  const globalIndex = (page - 1) * limit + currentIndex;
  const canGoPrev = globalIndex > 0;
  const canGoNext = globalIndex < totalCount - 1;

  return {
    records,
    totalCount,
    currentIndex,
    currentRecord,
    isLoading,
    error: error as Error | null,
    page,
    totalPages,
    setCurrentIndex,
    goFirst,
    goPrev,
    goNext,
    goLast,
    goToPage,
    canGoPrev,
    canGoNext,
    refetch,
  };
}

/**
 * TanStack Query Hooks for Entity CRUD Operations
 *
 */

import {
  useQuery,
  useMutation,
  useQueryClient,
  type UseQueryOptions,
} from '@tanstack/react-query';
import { apiClient, type PaginatedResponse, type ApiError } from '@/lib/api-client';
import { toast } from 'sonner';
import { translate } from '@/lib/translations';

// ============================================================================
// Types
// ============================================================================

export interface EntityRecord {
  [key: string]: unknown;
  version: number;
  created_at: string;
  updated_at: string;
}

export interface EntityListParams {
  page?: number;
  limit?: number;
  orderBy?: string;
  orderDir?: 'asc' | 'desc';
  search?: string;
  [key: string]: unknown;
}

export interface FieldMetadata {
  sys_field_id: string;
  name: string;
  column_name: string;
  sys_reference_id: number;
  is_mandatory: boolean;
  is_updateable?: boolean;
  field_length?: number;
  default_value?: string;
  seq_no: number;
  seq_no_grid: number;
  is_displayed: boolean;
  is_displayed_grid: boolean;
  is_read_only: boolean;
  col_span?: number;
  row_span?: number;
  field_group_id?: string;
  group_name?: string;
  group_columns?: number;
  group_description?: string;
  group_layout_type?: string | null;
  color?: string;
  background_color?: string;
  font_weight?: string;
  font_style?: string;
  text_align?: string;
  reference_name?: string; // Human-readable type name returned by the API (e.g. "String", "Integer", "Date")
  ref_table_name?: string; // Referenced table name for TABLE reference types (sys_reference_id = 18)
  ref_label_fields?: string[]; // Identifier columns of the referenced table for display
  ref_endpoint?: string;        // Custom API endpoint for table references (e.g. '/sys/references')
  ref_id_field?: string;        // Field to use as option value (default: 'id')
  ref_label_field?: string;     // Field to use as option label (default: 'name')
  ref_filter_param?: string;    // Query param name to append to ref_endpoint for filtering (e.g. 'tableId')
  ref_filter_source?: string;   // Key in parentContext whose value is used as the filter (e.g. 'sys_table_id')
  options?: { value: string; label: string }[]; // Static options list for inline enums
  tab_name?: string; // Tab name for i18n field labels
  help?: string; // Contextual help text shown via ? icon
}

export interface TableMetadata {
  sys_table_id: string;
  table_name: string;
  name: string;
  description?: string;
  icon?: string;
  is_active: boolean;
}

// ============================================================================
// Query Keys
// ============================================================================

export const entityKeys = {
  all: ['entities'] as const,
  lists: () => [...entityKeys.all, 'list'] as const,
  list: (entity: string, params?: EntityListParams) =>
    [...entityKeys.lists(), entity, params] as const,
  details: () => [...entityKeys.all, 'detail'] as const,
  detail: (entity: string, id: string) =>
    [...entityKeys.details(), entity, id] as const,
  metadata: (entity: string) =>
    [...entityKeys.all, 'metadata', entity] as const,
  table: (entity: string) =>
    [...entityKeys.all, 'table', entity] as const,
  fields: (entity: string, type: 'form' | 'grid') =>
    [...entityKeys.all, 'fields', entity, type] as const,
};

// ============================================================================
// List Hook
// ============================================================================

export function useEntities<T extends EntityRecord = EntityRecord>(
  entity: string,
  params?: EntityListParams,
  options?: Omit<
    UseQueryOptions<PaginatedResponse<T>, ApiError>,
    'queryKey' | 'queryFn'
  >
) {
  return useQuery<PaginatedResponse<T>, ApiError>({
    queryKey: entityKeys.list(entity, params),
    queryFn: () => apiClient.get<PaginatedResponse<T>>(`/bus/${entity}`, params),
    ...options,
  });
}

// ============================================================================
// Detail Hook
// ============================================================================

export function useEntity<T extends EntityRecord = EntityRecord>(
  entity: string,
  id: string,
  options?: Omit<UseQueryOptions<T, ApiError>, 'queryKey' | 'queryFn'>
) {
  return useQuery<T, ApiError>({
    queryKey: entityKeys.detail(entity, id),
    queryFn: () => apiClient.get<T>(`/bus/${entity}/${id}`),
    enabled: !!id,
    ...options,
  });
}

// ============================================================================
// Metadata Hooks
// ============================================================================

export function useEntityMetadata(entity: string, enabled = true) {
  return useQuery({
    queryKey: entityKeys.metadata(entity),
    queryFn: async () => {
      return apiClient.get<{ table: any; columns: any[]; window: any }>(`/bus/${entity}/meta`);
    },
    staleTime: 30 * 60 * 1000, // 30 minutes - metadata rarely changes
    enabled,
  });
}

/**
