    queryFn: async () => {
      const response = await apiClient.get<PaginatedResponse<ColumnMetadata>>(
        `/sys/columns?table_id=${tableId}`
      );
      return response.data;
    },
    enabled: !!tableId,
    staleTime: 5 * 60 * 1000,
  });
}

