              </div>
              <div>
                <dt className="text-xs text-gray-400 mb-0.5">Created</dt>
                <dd className="text-gray-700">{new Date(wf.created_at).toLocaleDateString()}</dd>
              </div>
              <div>
                <dt className="text-xs text-gray-400 mb-0.5">Last updated</dt>
                <dd className="text-gray-700">{new Date(wf.updated_at).toLocaleDateString()}</dd>
              </div>
            </dl>
          </div>

          {/* Quick navigation: linked rules */}
          {linkedRules.length > 0 && (
            <div className="bg-white border border-gray-200 rounded-lg p-4">
              <h3 className="text-xs font-semibold uppercase tracking-widest text-gray-500 mb-3 flex items-center gap-1.5">
                <Shield className="h-3.5 w-3.5 text-amber-500" />
                Linked Rules
              </h3>
              <div className="space-y-1.5">
                {linkedRules.map((rule) => (
                  <Link
                    key={rule.id}
                    to="/admin/rules/$id/edit"
                    params={{ id: rule.id }}
                    className="flex items-center justify-between text-xs p-2 rounded hover:bg-amber-50 transition-colors group"
                  >
                    <span className="text-gray-700 group-hover:text-amber-800 font-medium truncate max-w-[130px]">
                      {rule.ruleName}
                    </span>
                    <ExternalLink className="h-3 w-3 text-gray-400 group-hover:text-amber-500 ml-1 shrink-0" />
                  </Link>
                ))}
              </div>
              <button
                onClick={handleAddRule}
                className="mt-2 w-full flex items-center justify-center gap-1 text-xs text-amber-600 hover:text-amber-800
                           border border-dashed border-amber-200 hover:border-amber-400 rounded py-1.5 transition-colors"
              >
                <Plus className="h-3 w-3" />
                New rule
              </button>
            </div>
          )}

          {/* Recent runs */}
          <div className="bg-white border border-gray-200 rounded-lg p-4">
            <h3 className="text-xs font-semibold uppercase tracking-widest text-gray-500 mb-3">Recent Runs</h3>
            {recentRuns.length === 0 ? (
              <p className="text-sm text-gray-400">No runs recorded yet.</p>
            ) : (
              <div className="space-y-2">
                {recentRuns.slice(0, 5).map((run: any) => (
                  <div key={run.id} className="flex items-center justify-between text-xs">
                    <div className="flex items-center gap-1.5">
                      {run.status === 'success'
                        ? <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" />
                        : <AlertCircle className="h-3.5 w-3.5 text-red-400" />}
                      <span className="font-mono text-gray-500">{run.entity_id?.slice(0, 8)}…</span>
                    </div>
                    <span className="text-gray-400">{new Date(run.created_at).toLocaleDateString()}</span>
                  </div>
                ))}
              </div>
            )}
            <Link
              to="/admin/workflows"
              className="text-teal-600 hover:underline text-xs mt-3 inline-block"
            >
              View all runs →
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { ChevronRight } from "lucide-react";
import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "../../../components/ui/alert-dialog";
import { Badge } from "../../../components/ui/badge";
import { Button } from "../../../components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "../../../components/ui/card";
import { WindowHelpDialog } from "../../../components/admin/window-help-dialog";
import { apiClient } from "../../../lib/api-client";

export const Route = createFileRoute("/admin/workflow-definitions/")({
  component: WorkflowDefinitionsList,
});

interface WfDef {
  id: string;
  name: string;
  entity_name: string;
  operation: string;
  trigger_type?: string;
  source?: string;
  is_active: boolean;
  description?: string;
  created_at: string;
}

function WorkflowDefinitionsList() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [filterEntity, setFilterEntity] = useState("");

  const { data: defs = [], isLoading } = useQuery<WfDef[]>({
    queryKey: ["workflow-definitions"],
    queryFn: () => apiClient.get<any>("/workflow-definitions").then((r: any) => Array.isArray(r) ? r : (r?.items ?? r?.data ?? [])),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => apiClient.delete(`/workflow-definitions/${id}`),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["workflow-definitions"] }),
  });

  const filtered = filterEntity
    ? defs.filter((d) => d.entity_name.toLowerCase().includes(filterEntity.toLowerCase()))
    : defs;

  const stats = {
    total: defs.length,
    active: defs.filter((d) => d.is_active).length,
    entities: Array.from(new Set(defs.map((d) => d.entity_name))).length,
  };

  return (
    <div className="max-w-6xl mx-auto p-6 space-y-6">
      {/* Breadcrumb */}
      <nav aria-label="breadcrumb" className="flex items-center gap-1 text-sm text-gray-500">
        <Link to="/dashboard" className="hover:text-gray-700 hover:underline">
          Dashboard
        </Link>
        <ChevronRight className="h-3.5 w-3.5" />
        <span className="text-gray-900 font-medium">Workflow Designer</span>
      </nav>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-bold text-gray-900">Workflows</h1>
            <WindowHelpDialog windowName="Workflow Designer" entityLabel="Workflow Designer" />
          </div>
          <p className="text-sm text-gray-500 mt-1">
            Everything that runs automatically on your records. Built in the automation builder.
          </p>
        </div>
        <Button onClick={() => navigate({ to: "/admin/automations" })}>+ New Workflow</Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-4">
            <div className="text-2xl font-bold">{stats.total}</div>
            <div className="text-xs text-gray-500">Total workflows</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="text-2xl font-bold text-green-600">{stats.active}</div>
            <div className="text-xs text-gray-500">Active</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="text-2xl font-bold">{stats.entities}</div>
            <div className="text-xs text-gray-500">Entities covered</div>
          </CardContent>
        </Card>
      </div>

      {/* Filter */}
      <div className="flex gap-2">
        <input
          className="border rounded px-3 py-1.5 text-sm w-64"
          placeholder="Filter by entity..."
          value={filterEntity}
          onChange={(e) => setFilterEntity(e.target.value)}
        />
      </div>

      {/* Table */}
      {isLoading ? (
        <div className="text-center py-12 text-gray-400">Loading…</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-12 text-gray-400">
          No workflows yet.{" "}
          <Link to="/admin/automations" className="text-teal-600 underline">
            Create one
          </Link>
        </div>
      ) : (
        <Card>
          <CardContent className="p-0">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Name</th>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Entity</th>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Operation</th>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Runs when</th>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Status</th>
                  <th className="text-left px-4 py-3 font-medium text-gray-600">Created</th>
                  <th className="px-4 py-3" />
                </tr>
              </thead>
              <tbody className="divide-y">
                {filtered.map((d) => (
                  <tr key={d.id} className="hover:bg-gray-50">
                    <td className="px-4 py-3 font-medium">
                      <Link
                        to="/admin/workflow-definitions/$id/edit"
                        params={{ id: d.id }}
                        className="text-teal-700 hover:underline"
                      >
                        {d.name}
                      </Link>
                      {d.source === "model" && (
                        <Badge
                          variant="outline"
                          className="ml-2 text-[10px] border-indigo-200 text-indigo-700"
                          title="Declared by a %%workflow section in the model. Edit the model and regenerate."
                        >
                          From the model
                        </Badge>
                      )}
                      {d.description && (
                        <div className="text-xs text-gray-400 mt-0.5">{d.description}</div>
                      )}
                    </td>
                    <td className="px-4 py-3 font-mono text-xs text-gray-600">{d.entity_name}</td>
                    <td className="px-4 py-3">
                      <Badge variant="outline" className="text-xs">
                        {d.operation}
                      </Badge>
                    </td>
                    <td className="px-4 py-3">
                      <Badge variant="outline" className="text-xs">
                        {d.trigger_type === "rule" ? "When a rule triggers it" : "Every write"}
                      </Badge>
                    </td>
                    <td className="px-4 py-3">
                      <Badge
                        className={
                          d.is_active
                            ? "bg-green-100 text-green-700 border-green-200"
                            : "bg-gray-100 text-gray-500"
                        }
                      >
                        {d.is_active ? "Active" : "Inactive"}
                      </Badge>
                    </td>
                    <td className="px-4 py-3 text-xs text-gray-500">
                      {new Date(d.created_at).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex gap-2 justify-end">
                        {/* Opens this row. It used to send every workflow to
                            the builder's own rail at /admin/automations, which
                            lists nothing a model declared — so View on a model
                            workflow landed on a page reading "None yet", and
                            the detail screen that does show the trigger, the
                            rule gates and each step was reachable only by
                            typing its URL. */}
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            navigate({
                              to: "/admin/workflow-definitions/$id/edit",
                              params: { id: d.id },
                            })
                          }
                        >
                          {d.source === "model" ? "View" : "Edit"}
                        </Button>
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="text-red-500 hover:text-red-700"
                              disabled={d.source === "model"}
                              title={
                                d.source === "model"
                                  ? "Declared in the model — remove the %%workflow section and regenerate"
                                  : undefined
                              }
                            >
                              Delete
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent>
                            <AlertDialogHeader>
                              <AlertDialogTitle>Delete workflow?</AlertDialogTitle>
                              <AlertDialogDescription>
                                "{d.name}" will be permanently removed.
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter>
                              <AlertDialogCancel>Cancel</AlertDialogCancel>
                              <AlertDialogAction
                                className="bg-red-600 hover:bg-red-700"
                                onClick={() => deleteMutation.mutate(d.id)}
                              >
                                Delete
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * Application Dictionary — Entity Categories
 *
 * Maintains the categories the dashboard groups business entities by, and lets
 * an administrator move entities between them.
 *
 */

import { createFileRoute } from '@tanstack/react-router';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect, useMemo, useState } from 'react';
import {
  AlertCircle,
  Check,
  Loader2,
  Pencil,
  Plus,
  Star,
  Tags,
  Trash2,
  X,
} from 'lucide-react';
import { ADSidebar } from '@/components/admin/ad-sidebar';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { apiClient } from '@/lib/api-client';
import { Icon } from '@/components/ui/icon';

export const Route = createFileRoute('/admin/categories')({
  component: CategoriesPage,
});

interface Category {
  sys_category_id: string;
  name: string;
  code: string;
  description: string | null;
  icon: string | null;
  color: string | null;
  seq_no: number;
  is_default: boolean;
  is_active: boolean;
}

interface TableRow {
  sys_table_id: string;
  table_name: string;
  name: string;
  description?: string | null;
  sys_category_id?: string | null;
}

interface CategoryForm {
  name: string;
  code: string;
  description: string;
  icon: string;
  color: string;
  seq_no: number;
  is_default: boolean;
  is_active: boolean;
}

const EMPTY_FORM: CategoryForm = {
  name: '',
  code: '',
  description: '',
  icon: '',
  color: '',
  seq_no: 0,
  is_default: false,
  is_active: true,
};

/**
 * Inline style for the colour preview swatch.
 *
 * Built in a helper rather than written as an inline object literal because a
 * doubled brace in JSX would be read as a template expression when this file is
 * generated.
 */
function swatch(color: string): React.CSSProperties {
  return { backgroundColor: color };
}

function slugify(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 50);
}

function CategoriesPage() {
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState<Category | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<CategoryForm>(EMPTY_FORM);
  const [formError, setFormError] = useState<string | null>(null);

  const categoriesQuery = useQuery({
    queryKey: ['admin', 'categories'],
    queryFn: () =>
      apiClient.get<{ data: Category[] }>('/sys/categories', { includeInactive: 'true' }),
  });

  const tablesQuery = useQuery({
    queryKey: ['admin', 'categories', 'tables'],
    queryFn: () => apiClient.get<{ data: TableRow[] }>('/sys/tables', { limit: 500 }),
  });

  const categories = useMemo(
    () =>
      [...(categoriesQuery.data?.data ?? [])].sort((a, b) => a.name.localeCompare(b.name)),
    [categoriesQuery.data],
  );

  const businessTables = useMemo(
    () =>
      (tablesQuery.data?.data ?? [])
        .filter((t) => t.table_name?.startsWith('bus_'))
        .sort((a, b) => a.name.localeCompare(b.name)),
    [tablesQuery.data],
  );

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ['admin', 'categories'] });
    queryClient.invalidateQueries({ queryKey: ['dashboard', 'categories'] });
  };

  const saveMutation = useMutation({
    mutationFn: async (payload: CategoryForm & { id?: string }) => {
      const body = {
        name: payload.name.trim(),
        code: payload.code.trim() || slugify(payload.name),
        description: payload.description.trim() || null,
        icon: payload.icon.trim() || null,
        color: payload.color.trim() || null,
        seq_no: Number(payload.seq_no) || 0,
        is_default: payload.is_default,
        is_active: payload.is_active,
      };
      return payload.id
        ? apiClient.put(`/sys/categories/${payload.id}`, body)
        : apiClient.post('/sys/categories', body);
    },
    onSuccess: () => {
      invalidate();
      closeForm();
    },
    onError: (error: any) => {
      setFormError(error?.message ?? 'Could not save the category');
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => apiClient.delete(`/sys/categories/${id}`),
    onSuccess: invalidate,
  });

  const assignMutation = useMutation({
    mutationFn: ({ tableId, categoryId }: { tableId: string; categoryId: string }) =>
      categoryId
        ? apiClient.post(`/sys/categories/${categoryId}/entities`, { tableIds: [tableId] })
        : apiClient.post('/sys/categories/unassign', { tableIds: [tableId] }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin', 'categories', 'tables'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard', 'categories'] });
    },
  });

  // Keep the code field in step with the name until the user edits it directly.
  const [codeTouched, setCodeTouched] = useState(false);
  useEffect(() => {
    if (!codeTouched && !editing) {
      setForm((prev) => ({ ...prev, code: slugify(prev.name) }));
    }
  }, [form.name, codeTouched, editing]);

  function openCreate() {
    setEditing(null);
    setForm(EMPTY_FORM);
    setCodeTouched(false);
    setFormError(null);
    setShowForm(true);
  }

  function openEdit(category: Category) {
    setEditing(category);
    setForm({
      name: category.name,
      code: category.code,
      description: category.description ?? '',
      icon: category.icon ?? '',
      color: category.color ?? '',
      seq_no: category.seq_no,
      is_default: category.is_default,
      is_active: category.is_active,
    });
    setCodeTouched(true);
    setFormError(null);
    setShowForm(true);
  }

  function closeForm() {
    setShowForm(false);
    setEditing(null);
    setForm(EMPTY_FORM);
    setFormError(null);
  }

  function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!form.name.trim()) {
      setFormError('Name is required');
      return;
    }
    saveMutation.mutate({ ...form, id: editing?.sys_category_id });
  }

  const isLoading = categoriesQuery.isLoading || tablesQuery.isLoading;

  return (
    <ADSidebar>
      <div className="p-6 space-y-6" data-testid="admin-categories">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <Tags className="w-6 h-6 text-primary" />
            <div>
              <h1 className="text-2xl font-semibold">Entity Categories</h1>
              <p className="text-sm text-muted-foreground mt-1">
                Group business entities into sections. The dashboard renders one block per
                category, ordered by name.
              </p>
            </div>
          </div>
          <Button onClick={openCreate} data-testid="new-category">
            <Plus className="w-4 h-4 mr-2" />
            New Category
          </Button>
        </div>

        {/* ---- Category form ------------------------------------------- */}
        {showForm && (
          <Card data-testid="category-form">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{editing ? `Edit “${editing.name}”` : 'New Category'}</CardTitle>
              <Button variant="ghost" size="sm" onClick={closeForm} aria-label="Close">
                <X className="w-4 h-4" />
              </Button>
            </CardHeader>
            <CardContent>
              <form onSubmit={submit} className="grid gap-4 md:grid-cols-2">
                <label className="flex flex-col gap-1.5">
                  <span className="text-sm font-medium">
                    Name <span className="text-destructive">*</span>
                  </span>
                  <input
                    name="name"
                    required
                    value={form.name}
                    onChange={(e) => setForm({ ...form, name: e.target.value })}
                    className="swiss-input h-9 px-3 text-sm"
                    placeholder="Compound Management"
                  />
                  <span className="text-xs text-muted-foreground">
                    Shown as the group heading on the dashboard, and its sort key.
                  </span>
                </label>

                <label className="flex flex-col gap-1.5">
                  <span className="text-sm font-medium">Code</span>
                  <input
                    name="code"
                    value={form.code}
                    onChange={(e) => {
                      setCodeTouched(true);
                      setForm({ ...form, code: e.target.value });
                    }}
                    className="swiss-input h-9 px-3 text-sm font-mono"
                    placeholder="compound-management"
                  />
                  <span className="text-xs text-muted-foreground">
                    Stable identifier. Derived from the name when left blank.
                  </span>
                </label>

                <label className="flex flex-col gap-1.5 md:col-span-2">
                  <span className="text-sm font-medium">Description</span>
                  <textarea
                    name="description"
                    rows={2}
                    value={form.description}
                    onChange={(e) => setForm({ ...form, description: e.target.value })}
                    className="swiss-input px-3 py-2 text-sm"
                    placeholder="Registration and structural data for compounds"
                  />
                </label>

                <label className="flex flex-col gap-1.5">
                  <span className="text-sm font-medium">Icon</span>
                  <input
                    name="icon"
                    value={form.icon}
                    onChange={(e) => setForm({ ...form, icon: e.target.value })}
                    className="swiss-input h-9 px-3 text-sm"
                    placeholder="FlaskConical"
                  />
                  <span className="text-xs text-muted-foreground">
                    Any lucide-react icon name.
                  </span>
                </label>

                <label className="flex flex-col gap-1.5">
                  <span className="text-sm font-medium">Colour</span>
                  <div className="flex items-center gap-2">
                    <input
                      name="color"
                      value={form.color}
                      onChange={(e) => setForm({ ...form, color: e.target.value })}
                      className="swiss-input h-9 px-3 text-sm flex-1 font-mono"
                      placeholder="#6366f1"
                    />
                    {form.color && (
                      <span
                        className="w-9 h-9 rounded-md border border-border flex-shrink-0"
                        style={swatch(form.color)}
                        aria-hidden
                      />
                    )}
                  </div>
                </label>

                <label className="flex flex-col gap-1.5">
                  <span className="text-sm font-medium">Sequence</span>
                  <input
                    name="seq_no"
                    type="number"
                    value={form.seq_no}
                    onChange={(e) => setForm({ ...form, seq_no: Number(e.target.value) })}
                    className="swiss-input h-9 px-3 text-sm"
                  />
                  <span className="text-xs text-muted-foreground">
                    Ordering hint for admin listings.
                  </span>
                </label>

                <div className="flex flex-col gap-2 justify-center">
                  <label className="flex items-center gap-2 text-sm">
                    <input
                      type="checkbox"
                      checked={form.is_default}
                      onChange={(e) => setForm({ ...form, is_default: e.target.checked })}
                    />
                    Default category for uncategorised entities
                  </label>
                  <label className="flex items-center gap-2 text-sm">
                    <input
                      type="checkbox"
                      checked={form.is_active}
                      onChange={(e) => setForm({ ...form, is_active: e.target.checked })}
                    />
                    Active
                  </label>
                </div>

                {formError && (
                  <p className="md:col-span-2 text-sm text-destructive flex items-center gap-2">
                    <AlertCircle className="w-4 h-4" />
                    {formError}
                  </p>
                )}

                <div className="md:col-span-2 flex gap-2">
                  <Button type="submit" disabled={saveMutation.isPending}>
                    {saveMutation.isPending ? (
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    ) : (
                      <Check className="w-4 h-4 mr-2" />
                    )}
                    {editing ? 'Save changes' : 'Create category'}
                  </Button>
                  <Button type="button" variant="outline" onClick={closeForm}>
                    Cancel
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        )}

        {/* ---- Category list ------------------------------------------- */}
        {isLoading ? (
          <div className="flex items-center gap-2 text-muted-foreground p-8">
            <Loader2 className="w-4 h-4 animate-spin" />
            Loading categories…
          </div>
        ) : (
          <Card>
            <CardHeader>
              <CardTitle>Categories ({categories.length})</CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <table className="w-full text-sm" data-testid="categories-table">
                <thead className="border-b border-border">
                  <tr className="text-left text-muted-foreground">
                    <th className="px-4 py-2 font-medium">Name</th>
                    <th className="px-4 py-2 font-medium">Code</th>
                    <th className="px-4 py-2 font-medium">Description</th>
                    <th className="px-4 py-2 font-medium">Entities</th>
                    <th className="px-4 py-2 font-medium w-24">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {categories.map((category) => {
                    const count = businessTables.filter(
                      (t) => t.sys_category_id === category.sys_category_id,
                    ).length;
                    return (
                      <tr
                        key={category.sys_category_id}
                        className="border-b border-border last:border-0"
                        data-testid={`category-row-${category.code}`}
                      >
                        <td className="px-4 py-2.5">
                          <div className="flex items-center gap-2">
                            {category.icon && (
                              <Icon name={category.icon} size={16} className="text-primary" />
                            )}
                            <span className="font-medium">{category.name}</span>
                            {category.is_default && (
                              <Star className="w-3.5 h-3.5 text-amber-500" aria-label="Default" />
                            )}
                            {!category.is_active && (
                              <span className="text-xs text-muted-foreground">(inactive)</span>
                            )}
                          </div>
                        </td>
                        <td className="px-4 py-2.5 font-mono text-xs text-muted-foreground">
                          {category.code}
                        </td>
                        <td className="px-4 py-2.5 text-muted-foreground max-w-md truncate">
                          {category.description ?? '—'}
                        </td>
                        <td className="px-4 py-2.5 tabular-nums">{count}</td>
                        <td className="px-4 py-2.5">
                          <div className="flex gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => openEdit(category)}
                              aria-label={`Edit ${category.name}`}
                            >
                              <Pencil className="w-3.5 h-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => deleteMutation.mutate(category.sys_category_id)}
                              aria-label={`Delete ${category.name}`}
                            >
                              <Trash2 className="w-3.5 h-3.5 text-destructive" />
                            </Button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                  {categories.length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-4 py-8 text-center text-muted-foreground">
                        No categories yet — create one to group your entities.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </CardContent>
          </Card>
        )}

        {/* ---- Entity assignment --------------------------------------- */}
        {!isLoading && (
          <Card>
            <CardHeader>
              <CardTitle>Entity Assignment ({businessTables.length})</CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <table className="w-full text-sm" data-testid="assignment-table">
                <thead className="border-b border-border">
                  <tr className="text-left text-muted-foreground">
                    <th className="px-4 py-2 font-medium">Entity</th>
                    <th className="px-4 py-2 font-medium">Table</th>
                    <th className="px-4 py-2 font-medium w-72">Category</th>
                  </tr>
                </thead>
                <tbody>
                  {businessTables.map((table) => (
                    <tr
                      key={table.sys_table_id}
                      className="border-b border-border last:border-0"
                      data-testid={`assign-row-${table.table_name}`}
                    >
                      <td className="px-4 py-2.5 font-medium">{table.name}</td>
                      <td className="px-4 py-2.5 font-mono text-xs text-muted-foreground">
                        {table.table_name}
                      </td>
                      <td className="px-4 py-2.5">
                        <select
                          className="swiss-input h-8 px-2 text-sm w-full"
                          value={table.sys_category_id ?? ''}
                          onChange={(e) =>
                            assignMutation.mutate({
                              tableId: table.sys_table_id,
                              categoryId: e.target.value,
                            })
                          }
                          aria-label={`Category for ${table.name}`}
                        >
                          <option value="">— Uncategorized —</option>
                          {categories
                            .filter((c) => c.is_active)
                            .map((c) => (
                              <option key={c.sys_category_id} value={c.sys_category_id}>
                                {c.name}
                              </option>
                            ))}
                        </select>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </CardContent>
          </Card>
        )}
      </div>
    </ADSidebar>
  );
}

