          <Home className="h-3.5 w-3.5" />
          <span>Dashboard</span>
        </Link>
        <span className="text-muted-foreground">/</span>
        <Link to="/admin" className="text-muted-foreground hover:text-primary transition-colors">
          Admin
        </Link>
