/**
 * Better Auth, on the front end's own origin.
 *
 * Same forwarding as the sibling /api/$ route — the reasoning is in
 * src/lib/api-proxy.ts — with one addition: when the API cannot be reached, a
 * session lookup answers "nobody is signed in" rather than an error. The login
 * page asks for the session before it renders, and an application that shows a
 * blank screen because the API is still starting is worse than one that shows
 * the login form.
 *
 * Better Auth checks the browser's Origin against its own trustedOrigins list
 * and rejects anything else, so the header is passed through untouched. On a
 * host other than localhost that means naming it: CORS_ORIGIN=http://your-host:{{config.frontendPort}}.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { createAPIFileRoute } from '@tanstack/start/api'
// Relative rather than the `@/` alias — see the note in ../$.ts.
import { apiUnavailable, proxyToBackend } from '../../../lib/api-proxy'

/** No session, as a successful answer. What the login page needs to render. */
function noSession(): Response {
  return new Response(JSON.stringify({ user: null, session: null }), {
    status: 200,
    headers: { 'content-type': 'application/json' },
  })
}

const route = createAPIFileRoute('/api/auth/$')({
  GET: async ({ request, params }: { request: Request; params: Record<string, string> }) => {
    const path = params['_splat'] ?? ''
    try {
      return await proxyToBackend(request, `auth/${path}`)
    } catch {
      return noSession()
    }
  },
  POST: async ({ request, params }: { request: Request; params: Record<string, string> }) => {
    const path = params['_splat'] ?? ''
    try {
      return await proxyToBackend(request, `auth/${path}`)
    } catch (error) {
      return apiUnavailable(error, 'POST', `auth/${path}`)
    }
  },
})

// Both names, on purpose — see the note in ../$.ts.
export const APIRoute = route
export const Route = route

/**
 * Everything under /api, served from the front end's own origin and forwarded
 * to the NestJS API. The reasoning lives in src/lib/api-proxy.ts.
 *
 * Two things are not forwarded. /api/auth/* has its own file, matched before
 * this one because the router tries routes with more path segments first. And
 * the assistant is answered here — see the note on it below.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { createAPIFileRoute } from '@tanstack/start/api'
// Relative rather than the `@/` alias: this module is bundled by the API
// router, which is configured separately from the client and the SSR server,
// and a path that does not depend on an alias being wired there cannot break.
import { apiUnavailable, proxyToBackend } from '../../lib/api-proxy'
import { handleCopilotRequest, isCopilotPath } from '../../lib/copilot-runtime'

function handler(method: string) {
  return async ({ request, params }: { request: Request; params: Record<string, string> }) => {
    const path = params['_splat'] ?? ''

    // The assistant is served here rather than forwarded. It is answered from
    // this route and not from a /api/copilotkit/$ file of its own because the
    // client posts to /api/copilotkit exactly, and a splat route requires
    // something after the slash — so such a file can never match the one
    // address the client actually uses.
    if (isCopilotPath(path)) return handleCopilotRequest(request)

    try {
      return await proxyToBackend(request, path)
    } catch (error) {
      return apiUnavailable(error, method, path)
    }
  }
}

const route = createAPIFileRoute('/api/$')({
  GET: handler('GET'),
  HEAD: handler('HEAD'),
  POST: handler('POST'),
  PUT: handler('PUT'),
  PATCH: handler('PATCH'),
  DELETE: handler('DELETE'),
  OPTIONS: handler('OPTIONS'),
})

// Both names, on purpose. The router registers a route file by its `APIRoute`
// export and ignores anything else, so a file that exports only `Route` is
// silently absent — and an absent API route answers with the HTML of a missing
// page, not a 404 anyone would recognise as a routing problem.
export const APIRoute = route
