        {{name}}: {{#if (eq type "string")}}'Test {{displayName}} 2'{{else if (eq type "integer")}}2{{else if (eq type "decimal")}}20.99{{else if (eq type "boolean")}}false{{else if (eq type "datetime")}}'2024-01-16T10:00:00Z'{{else if (eq type "date")}}'2024-01-16'{{else if (eq type "text")}}'Test text content 2'{{else if (eq type "json")}}{}{{else}}'test2'{{/if}},
