      id: 'test-id-1',
      {{#each attributes}}
      {{#unless (eq name "id")}}
      {{name}}: {{#if (eq type "string")}}'Test {{displayName}}'{{else if (eq type "integer")}}1{{else if (eq type "decimal")}}10.99{{else if (eq type "boolean")}}true{{else if (eq type "datetime")}}'2024-01-15T10:00:00Z'{{else if (eq type "date")}}'2024-01-15'{{else if (eq type "text")}}'Test text content'{{else if (eq type "json")}}{}{{else}}'test'{{/if}},
      {{/unless}}
      {{/each}}
    },
  },
  {{/each}}
};

/**
 * Create mock fetch function
 */
export function createMockFetch(responses: Record<string, unknown>) {
  return vi.fn((input: RequestInfo | URL, options?: RequestInit) => {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    const path = url.replace(/^https?:\/\/[^/]+/, '');

    // Find matching response
    for (const [pattern, response] of Object.entries(responses)) {
      if (path.includes(pattern)) {
        return Promise.resolve({
          ok: true,
          status: 200,
          json: () => Promise.resolve(response),
          text: () => Promise.resolve(JSON.stringify(response)),
          headers: new Headers({ 'content-type': 'application/json' }),
        } as Response);
      }
    }

    // Default 404 response
    return Promise.resolve({
      ok: false,
      status: 404,
      json: () => Promise.resolve({ message: 'Not found' }),
      text: () => Promise.resolve('{"message": "Not found"}'),
      headers: new Headers({ 'content-type': 'application/json' }),
    } as Response);
  }) as unknown as typeof fetch;
}

/**
 * Wait for async operations
 */
export async function waitFor(callback: () => boolean | void, timeout = 5000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    try {
      const result = callback();
      if (result !== false) return;
    } catch {
      // Continue waiting
    }
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  throw new Error('Timeout waiting for condition');
}

