/**
 * Business Entity Controller
 *
 * Dynamic controller for all bus_ prefixed tables.
 * CRUD operations are driven by the Application Dictionary metadata.
 *
 * Generated: {{now}}
 */

import {
  Controller,
  Get,
  Post,
  Put,
  Patch,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  HttpCode,
  HttpStatus,
  ParseUUIDPipe,
  Logger,
  UseGuards,
  Req,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiParam } from '@nestjs/swagger';
import { BusService } from './bus.service';
import { SessionAuthGuard } from '../auth/guards/session-auth.guard';
import { EntityAccessGuard } from '../auth/guards/entity-access.guard';

@ApiTags('bus')
@ApiBearerAuth()
// Order matters: SessionAuthGuard puts the caller's roles on the request, and
// EntityAccessGuard reads them. Reversed, every %%rbac rule would see a request
// with no roles and refuse a caller who holds the right one.
@UseGuards(SessionAuthGuard, EntityAccessGuard)
@Controller('bus')
export class BusController {
  private readonly logger = new Logger(BusController.name);

  constructor(private readonly busService: BusService) {
    this.logger.log('BusController initialized');
  }

  /**
   * List all records for a business entity
   * GET /bus/:entity
   */
  @Get(':entity')
  @ApiOperation({ summary: 'List all records for a business entity' })
  @ApiParam({ name: 'entity', description: 'Entity name (e.g., customer, order)' })
  @ApiResponse({ status: 200, description: 'Returns paginated list of records' })
  async findAll(
    @Param('entity') entity: string,
    @Query('page') page?: number,
    @Query('limit') limit?: number,
    @Query('orderBy') orderBy?: string,
    @Query('orderDir') orderDir?: 'asc' | 'desc',
    @Query('search') search?: string,
    @Query() query?: Record<string, any>,
  ) {
    const methodName = 'findAll';
    this.logger.debug(`[${methodName}] Request - entity: ${entity}, page: ${page}, limit: ${limit}, orderBy: ${orderBy}, orderDir: ${orderDir}, search: ${search}`);

    // Extract filters from query params (exclude pagination params)
    const { page: _p, limit: _l, orderBy: _ob, orderDir: _od, search: _s, ...rawFilters } = query || {};

    // Parse filter parameters with format: filter.fieldName=operator:value
    const parsedFilters = this.parseFilters(rawFilters);

    if (Object.keys(parsedFilters).length > 0) {
      this.logger.debug(`[${methodName}] Filters: ${JSON.stringify(parsedFilters)}`);
    }

    let searchFields: string[] | undefined;
    if (search) {
      const meta = await this.busService.getEntityMetadata(entity);
      const TEXT_REFS = new Set([10, 14, 24, 30, 31]);
      searchFields = meta.columns
        .filter(c => TEXT_REFS.has(c.sys_reference_id) && c.is_displayed_grid)
        .map(c => c.column_name);
    }

    const result = await this.busService.findAll(entity, { page, limit, orderBy, orderDir, search, searchFields }, parsedFilters);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, returned ${result.data.length} records (total: ${result.meta.total})`);
    return result;
  }

  /**
   * Parse filter parameters from query string
   * Supports format: filter.fieldName=operator:value
   * Operators: contains, equals, startsWith, endsWith, gt, gte, lt, lte
   */
  private parseFilters(rawFilters: Record<string, any>): Record<string, any> {
    const parsed: Record<string, any> = {};

    for (const [key, value] of Object.entries(rawFilters)) {
      // Check if this is a filter parameter (starts with 'filter.')
      if (key.startsWith('filter.')) {
        const fieldName = key.substring(7); // Remove 'filter.' prefix

        // Parse operator:value format
        if (typeof value === 'string' && value.includes(':')) {
          const [operator, searchValue] = value.split(':', 2);

          switch (operator) {
            case 'contains':
              parsed[fieldName] = `%${searchValue}%`;
              break;
            case 'startsWith':
              parsed[fieldName] = `${searchValue}%`;
              break;
            case 'endsWith':
              parsed[fieldName] = `%${searchValue}`;
              break;
            case 'equals':
            case 'eq':
              parsed[fieldName] = searchValue;
              break;
            case 'gt':
              parsed[fieldName] = { operator: '>', value: searchValue };
              break;
            case 'gte':
              parsed[fieldName] = { operator: '>=', value: searchValue };
              break;
            case 'lt':
              parsed[fieldName] = { operator: '<', value: searchValue };
              break;
            case 'lte':
              parsed[fieldName] = { operator: '<=', value: searchValue };
              break;
            default:
              // Unknown operator, treat as exact match
              parsed[fieldName] = value;
          }

          this.logger.debug(`[parseFilters] Parsed filter: ${fieldName} with operator ${operator}`);
        } else {
          // No operator specified, use as-is
          parsed[fieldName] = value;
        }
      } else if (!key.startsWith('page') && !key.startsWith('limit') && !key.startsWith('orderBy') && !key.startsWith('orderDir')) {
        // Non-filter query params, pass through as-is
        parsed[key] = value;
      }
    }

    return parsed;
  }

  /**
   * Get dictionary metadata for an entity
   * Useful for clients to understand field configuration
   * GET /bus/:entity/meta
   */
  @Get(':entity/meta')
  @ApiOperation({ summary: 'Get dictionary metadata for an entity' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiResponse({ status: 200, description: 'Returns entity metadata from Application Dictionary' })
  async getMetadata(@Param('entity') entity: string) {
    const methodName = 'getMetadata';
    this.logger.debug(`[${methodName}] Request - entity: ${entity}`);

    const result = await this.busService.getEntityMetadata(entity);

    this.logger.debug(`[${methodName}] Success - entity: ${entity}, returned ${result.columns.length} columns`);
    return result;
  }

  /**
   * Get fields configuration for forms (ordered by seq_no)
   * GET /bus/:entity/fields/form
   */
  @Get(':entity/fields/form')
  @ApiOperation({ summary: 'Get fields for form display (ordered by seq_no)' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  async getFormFields(@Param('entity') entity: string) {
    const methodName = 'getFormFields';
    this.logger.debug(`[${methodName}] Request - entity: ${entity}`);

    const result = await this.busService.getFormFields(entity);

    this.logger.debug(`[${methodName}] Success - entity: ${entity}, returned ${result.length} form fields`);
    return result;
  }

  /**
   * Get fields configuration for grid/table (ordered by seq_no_grid)
   * GET /bus/:entity/fields/grid
   */
  @Get(':entity/fields/grid')
  @ApiOperation({ summary: 'Get fields for grid display (ordered by seq_no_grid)' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  async getGridFields(@Param('entity') entity: string) {
    const methodName = 'getGridFields';
    this.logger.debug(`[${methodName}] Request - entity: ${entity}`);

    const result = await this.busService.getGridFields(entity);

    this.logger.debug(`[${methodName}] Success - entity: ${entity}, returned ${result.length} grid fields`);
    return result;
  }

  /**
   * Get a single record by ID
   * GET /bus/:entity/:id
   */
  @Get(':entity/:id')
  @ApiOperation({ summary: 'Get a single record by ID' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiParam({ name: 'id', description: 'Record UUID' })
  @ApiResponse({ status: 200, description: 'Returns the record' })
  @ApiResponse({ status: 404, description: 'Record not found' })
  async findOne(
    @Param('entity') entity: string,
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    const methodName = 'findOne';
    this.logger.debug(`[${methodName}] Request - entity: ${entity}, id: ${id}`);

    const result = await this.busService.findById(entity, id);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, id: ${id}`);
    return result;
  }

  /**
   * Create a new record
   * POST /bus/:entity
   */
  @Post(':entity')
  @ApiOperation({ summary: 'Create a new record' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiResponse({ status: 201, description: 'Record created successfully' })
  @ApiResponse({ status: 400, description: 'Validation error' })
  async create(
    @Param('entity') entity: string,
    @Body() data: Record<string, any>,
  ) {
    const methodName = 'create';
    this.logger.log(`[${methodName}] Request - entity: ${entity}`);
    this.logger.debug(`[${methodName}] Request body: ${JSON.stringify(data)}`);

    // Validate data against dictionary metadata
    await this.busService.validateData(entity, data, 'create');
    const result = await this.busService.create(entity, data);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, created id: ${result.id}`);
    return result;
  }

  /**
   * Update an existing record (full replace)
   * PUT /bus/:entity/:id
   */
  @Put(':entity/:id')
  @ApiOperation({ summary: 'Update a record (full replace)' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiParam({ name: 'id', description: 'Record UUID' })
  @ApiResponse({ status: 200, description: 'Record updated successfully' })
  @ApiResponse({ status: 404, description: 'Record not found' })
  @ApiResponse({ status: 409, description: 'Conflict - record was modified' })
  async update(
    @Param('entity') entity: string,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() data: Record<string, any>,
    @Headers('if-match') ifMatch?: string,
    @Req() req?: any,
  ) {
    const methodName = 'update';
    // Extract version from If-Match header
    const version = ifMatch
      ? parseInt(ifMatch.replace(/"/g, '').replace('v', ''), 10)
      : undefined;

    this.logger.log(`[${methodName}] Request - entity: ${entity}, id: ${id}, expectedVersion: ${version}`);
    this.logger.debug(`[${methodName}] Request body: ${JSON.stringify(data)}`);

    // Capture before-value for audit trail
    if (req) {
      try { req.__auditBefore = await this.busService.findById(entity, id); } catch { /* not found is ok */ }
    }

    // Validate data against dictionary metadata
    await this.busService.validateData(entity, data, 'update');
    const result = await this.busService.update(entity, id, data, version);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, id: ${id}, new version: ${result.version}`);
    return result;
  }

  /**
   * Partially update a record
   * PATCH /bus/:entity/:id
   */
  @Post(':entity/:id/promote')
  @ApiOperation({ summary: 'Retry the draft → final promotion for a record' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiParam({ name: 'id', description: 'Record UUID' })
  @ApiResponse({ status: 200, description: 'Promotion re-run; check doc_status and promotion.message' })
  @ApiResponse({ status: 404, description: 'Record not found' })
  async retryPromotion(
    @Param('entity') entity: string,
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.busService.retryPromotion(entity, id);
  }

  @Patch(':entity/:id')
  @ApiOperation({ summary: 'Partially update a record' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiParam({ name: 'id', description: 'Record UUID' })
  @ApiResponse({ status: 200, description: 'Record updated successfully' })
  @ApiResponse({ status: 404, description: 'Record not found' })
  @ApiResponse({ status: 409, description: 'Conflict - record was modified' })
  async patch(
    @Param('entity') entity: string,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() data: Record<string, any>,
    @Headers('if-match') ifMatch?: string,
    @Req() req?: any,
  ) {
    const methodName = 'patch';
    const version = ifMatch
      ? parseInt(ifMatch.replace(/"/g, '').replace('v', ''), 10)
      : undefined;

    this.logger.log(`[${methodName}] Request - entity: ${entity}, id: ${id}, expectedVersion: ${version}`);
    this.logger.debug(`[${methodName}] Request body: ${JSON.stringify(data)}`);

    // Capture before-value for audit trail
    if (req) {
      try { req.__auditBefore = await this.busService.findById(entity, id); } catch { /* not found is ok */ }
    }

    // Validate partial data against dictionary metadata
    await this.busService.validateData(entity, data, 'patch');
    const result = await this.busService.update(entity, id, data, version);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, id: ${id}, new version: ${result.version}`);
    return result;
  }

  /**
   * Bootstrap Application Dictionary for a business entity
   * Creates sys_window, sys_tab, and sys_field records from sys_column records.
   * Idempotent — safe to call multiple times; only creates what is missing.
   * POST /bus/:entity/setup-dictionary
   */
  @Post(':entity/setup-dictionary')
  @ApiOperation({ summary: 'Bootstrap Application Dictionary for an entity (idempotent)' })
  @ApiParam({ name: 'entity', description: 'Entity name (e.g., lead, project)' })
  @ApiResponse({ status: 201, description: 'Dictionary records created or already existed' })
  @ApiResponse({ status: 404, description: 'No sys_table record found — register the table first' })
  async setupDictionary(@Param('entity') entity: string) {
    const methodName = 'setupDictionary';
    this.logger.log(`[${methodName}] Request - entity: ${entity}`);
    const result = await this.busService.setupEntityDictionary(entity);
    this.logger.log(`[${methodName}] Success - entity: ${entity}, created: ${result.created.length} records`);
    return result;
  }

  /**
   * Delete a record. The row is removed, and the record's delete workflows run
   * first in the same transaction — so a workflow that clears its children is
   * what makes the deletion safe, and a cascade that fails leaves the record
   * intact.
   *
   * DELETE /bus/:entity/:id
   */
  @Delete(':entity/:id')
  @ApiOperation({ summary: 'Delete a record' })
  @ApiParam({ name: 'entity', description: 'Entity name' })
  @ApiParam({ name: 'id', description: 'Record UUID' })
  @ApiResponse({ status: 200, description: 'Record deleted, with the workflows that ran' })
  @ApiResponse({ status: 404, description: 'Record not found' })
  async delete(
    @Param('entity') entity: string,
    @Param('id', ParseUUIDPipe) id: string,
    @Req() req?: any,
  ) {
    const methodName = 'delete';
    this.logger.log(`[${methodName}] Request - entity: ${entity}, id: ${id}`);

    // Capture before-value for audit trail
    if (req) {
      try { req.__auditBefore = await this.busService.findById(entity, id); } catch { /* not found is ok */ }
    }

    // The promotion result is returned rather than swallowed: a delete runs the
    // record's workflows, and a caller that cannot see whether the cascade ran
    // has no way to tell a completed delete from one that rolled back.
    const promotion = await this.busService.remove(entity, id);

    this.logger.log(`[${methodName}] Success - entity: ${entity}, id: ${id}`);
    return { deleted: promotion.promoted, promotion };
  }

}

/**
 * Business Entity Service
 *
 * Dynamic service for all bus_ prefixed tables.
 * Validates data against Application Dictionary metadata.
 *
 * Generated: {{now}}
 */

import { Injectable, NotFoundException, BadRequestException, ConflictException, Inject, Logger } from '@nestjs/common';
import type { Kysely } from 'kysely';
import { randomUUID } from 'crypto';
import { KYSELY_CONNECTION } from '../../database/database.constants';
import { DatabaseService } from '../../database/database.service';
import type { PaginationOptions, PaginatedResult } from '../../database/database.service';
import { executeBeforeCreateHooks, executeAfterCreateHooks, executeBeforeUpdateHooks, executeAfterUpdateHooks, executeBeforeDeleteHooks, executeAfterDeleteHooks, executeBeforeReadHooks, executeAfterReadHooks, executeBeforeListHooks, executeAfterListHooks, executeCustomValidateHooks } from '../hooks/hooks';
import { RulesService } from '../rules/rules.service';
import { PromotionDispatcher } from './promotion-dispatcher.service';
import type { PromotionResult } from './entity-promotion.service';
import { WorkflowService } from '../workflow/workflow.service';

export interface FieldMetadata {
  sys_field_id: string;
  name: string;
  column_name: string;
  sys_reference_id: number;
  is_mandatory: boolean;
  is_updateable: boolean;
  field_length?: number;
  default_value?: string;
  seq_no: number;
  seq_no_grid: number;
  is_displayed: boolean;
  is_displayed_grid: boolean;
  is_read_only: boolean;
  /** Contextual help from the dictionary, surfaced by the ? icon beside the field label. */
  help?: string;
  ref_table_name?: string;
  ref_label_fields?: string[];
}

export interface EntityMetadata {
  table: {
    sys_table_id: string;
    table_name: string;
    name: string;
    description?: string;
  };
  columns: FieldMetadata[];
  window?: {
    sys_window_id: string;
    name: string;
  };
}

@Injectable()
export class BusService {
  private readonly logger = new Logger(BusService.name);
  private metadataCache: Map<string, EntityMetadata> = new Map();
  private readonly identifierFieldsCache = new Map<string, string[]>();
  private static readonly AUTO_MANAGED_COLUMNS = new Set(['id', 'created_at', 'updated_at', 'deleted_at', 'version']);

  constructor(
    @Inject(KYSELY_CONNECTION) private readonly kysely: Kysely<any>,
    private readonly db: DatabaseService,
    private readonly rulesService: RulesService,
    private readonly workflowService: WorkflowService,
    private readonly promotionDispatcher: PromotionDispatcher,
  ) {
    this.logger.log('BusService initialized');
  }

  /**
   * Enforce business rules (GoRules JDM) for the given operation.
   * Rule violations ('prevent' actions) reject the operation with a 400.
   * Infrastructure failures (rules table missing, engine errors) fail open
   * with a warning so business rules can never take CRUD fully offline.
   */
  private async enforceBusinessRules(
    tableName: string,
    data: Record<string, any>,
    action: 'create' | 'update' | 'delete',
  ): Promise<void> {
    let result: { valid: boolean; errors: string[]; warnings: string[] };
    try {
      result = await this.rulesService.validate(tableName, data, action);
    } catch (error: any) {
      this.logger.warn(`Business rule evaluation unavailable for ${tableName}:${action}: ${error?.message ?? error}`);
      return;
    }

    for (const warning of result.warnings) {
      this.logger.warn(`Business rule warning for ${tableName}:${action}: ${warning}`);
    }

    if (!result.valid) {
      throw new BadRequestException({ message: 'Business rule validation failed', errors: result.errors });
    }
  }

  private singularize(word: string): string {
    if (word.endsWith('ies')) return word.slice(0, -3) + 'y';
    if (word.endsWith('ses') || word.endsWith('xes') || word.endsWith('zes') ||
        word.endsWith('ches') || word.endsWith('shes')) return word.slice(0, -2);
    if (word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1);
    return word;
  }

  private getTableName(entity: string): string {
    const normalized = entity.toLowerCase().replace(/-/g, '_');
    if (normalized.startsWith('bus_')) return normalized;
    const singular = this.singularize(normalized);
    return `bus_${singular}`;
  }

  async findAll(
    entity: string,
    options: PaginationOptions = {},
    filters: Record<string, any> = {},
  ): Promise<PaginatedResult<any>> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const processedOptions = await executeBeforeListHooks(entity, { options, filters });
    const result = await this.db.findAll(tableName, processedOptions.options, processedOptions.filters);
    await executeAfterListHooks(entity, result.data);

    this.logger.log(`findAll: entity=${entity}, returned ${result.data.length} records`);
    return result;
  }

  async findById(entity: string, id: string): Promise<any> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const processedId = await executeBeforeReadHooks(entity, { id });
    const result = await this.db.findByIdOrFail(tableName, processedId.id || id);
    await executeAfterReadHooks(entity, result);

    return result;
  }

  async create(entity: string, data: Record<string, any>): Promise<any> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const metadata = await this.getEntityMetadata(entity);
    const dataWithDefaults = { ...data };

    for (const column of metadata.columns) {
      if (column.default_value && dataWithDefaults[column.column_name] === undefined) {
        dataWithDefaults[column.column_name] = this.parseDefaultValue(column.default_value, column.sys_reference_id);
      }
    }

    let processedData = await executeBeforeCreateHooks(entity, dataWithDefaults);
    if (!processedData.id) {
      processedData = { ...processedData, id: randomUUID() };
    }
    // Strip entity-specific PK field (e.g. compound_id) — the table uses 'id'
    const entityPkField = tableName.replace(/^bus_/, '') + '_id';
    if (entityPkField in processedData) {
      const { [entityPkField]: _pk, ...rest } = processedData;
      processedData = rest;
    }

    await executeCustomValidateHooks(entity, processedData);
    await this.enforceBusinessRules(tableName, processedData, 'create');

    let result: any;
    try {
      result = await this.db.transaction(async (trx) => {
        const now = new Date();
        const rows = await trx
          .insertInto(tableName as any)
          .values({ ...processedData, created_at: now, updated_at: now, deleted_at: null } as any)
          .returningAll()
          .execute();
        return rows[0];
      });
    } catch (error: any) {
      const msg: string = error?.message ?? '';
      if (
        error?.code === 'SQLITE_CONSTRAINT' ||
        error?.code === '23505' ||
        msg.includes('UNIQUE constraint failed') ||
        msg.includes('duplicate key value')
      ) {
        throw new ConflictException('A record with the same unique field value already exists');
      }
      throw error;
    }

    await executeAfterCreateHooks(entity, result);

    // The row is committed as a draft. Promotion runs the associated rules and
    // workflows and decides whether it becomes final — see EntityPromotionService.
    const promotion = await this.promotionDispatcher.dispatch(tableName, result.id, 'create', result);

    this.logger.log(`create: entity=${entity}, id=${result?.id}, doc_status=${promotion.docStatus}`);
    return this.withPromotion(tableName, result.id, result, promotion);
  }

  /**
   * Re-read the row so the caller sees the post-promotion doc_status and message
   * rather than the draft snapshot taken at insert time, and attach the promotion
   * outcome so the UI can explain a failure without a second request.
   */
  private async withPromotion(
    tableName: string,
    id: string,
    fallback: any,
    promotion: PromotionResult,
  ): Promise<any> {
    let row = fallback;
    try {
      const fresh = await this.db.findById<Record<string, any>>(tableName, id);
      if (fresh) row = fresh;
    } catch (err: any) {
      this.logger.warn(`Could not re-read ${tableName}:${id} after promotion: ${err?.message}`);
    }
    return { ...row, promotion };
  }

  async update(
    entity: string,
    id: string,
    data: Record<string, any>,
    expectedVersion?: number,
  ): Promise<any> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const processedData = await executeBeforeUpdateHooks(entity, data);

    // Validate business rules against the record as it would look after the
    // update, so rules over fields absent from a partial payload still hold.
    const current = await this.db.findById<Record<string, any>>(tableName, id);
    if (current) {
      const merged = { ...current, ...processedData };
      await executeCustomValidateHooks(entity, merged);
      await this.enforceBusinessRules(tableName, merged, 'update');
    }

    const result = await this.db.transaction(async (trx) => {
      const existing = await trx
        .selectFrom(tableName as any)
        .selectAll()
        .where('id' as any, '=', id)
        .where('deleted_at' as any, 'is', null)
        .executeTakeFirst();

      if (!existing) return null;

      if (expectedVersion !== undefined && (existing as any).version !== expectedVersion) {
        throw new ConflictException('Record was modified by another user. Please reload and try again.');
      }

      const rows = await trx
        .updateTable(tableName as any)
        .set({ ...processedData, updated_at: new Date(), version: ((existing as any).version || 0) + 1 } as any)
        .where('id' as any, '=', id)
        .returningAll()
        .execute();
      return rows[0] ?? null;
    });

    if (!result) {
      throw new NotFoundException(`Record not found in ${tableName} with id: ${id}`);
    }

    await executeAfterUpdateHooks(entity, result);

    const promotion = await this.promotionDispatcher.dispatch(tableName, id, 'update', result);

    this.logger.log(`update: entity=${entity}, id=${id}, doc_status=${promotion.docStatus}`);
    return this.withPromotion(tableName, id, result, promotion);
  }

  /**
   * Re-run promotion for a record the user has since fixed. Same pipeline, same
   * outcomes — this is the "retry" half of the draft-with-an-error contract.
   */
  async retryPromotion(entity: string, id: string): Promise<any> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const current = await this.db.findById<Record<string, any>>(tableName, id);
    if (!current) {
      throw new NotFoundException(`Record not found in ${tableName} with id: ${id}`);
    }

    const promotion = await this.promotionDispatcher.dispatch(tableName, id, 'update', current);
    return this.withPromotion(tableName, id, current, promotion);
  }

  /**
   * Delete a record. The row goes, and it goes through the workflow pipeline.
   *
   * This used to stamp `deleted_at` and then fire the delete workflows and rule
   * actions afterwards, unawaited. Three things were wrong with that. The row
   * survived, so "deleted" records kept their foreign keys and every query had
   * to remember to filter them out. The workflows ran after the write rather
   * than before it, so a workflow meant to clear a record's children raced the
   * deletion of their parent. And because the calls were fire-and-forget, a
   * cascade that failed was logged and swallowed: the parent was already marked
   * deleted and the children were still there, with nothing to say so.
   *
   * Now the delete is one all-or-nothing transaction, the same one create and
   * update go through: matched rule actions run, then the delete workflows —
   * which is where children are cleared — and the row is removed last. Anything
   * that throws rolls the whole thing back and the record is still there.
   */
  async remove(entity: string, id: string): Promise<PromotionResult> {
    const tableName = this.getTableName(entity);
    await this.verifyEntity(entity);

    const canDelete = await executeBeforeDeleteHooks(entity, id);
    if (!canDelete) {
      throw new BadRequestException(`Cannot delete ${entity}: still referenced`);
    }

    const current = await this.db.findById<Record<string, any>>(tableName, id);
    if (!current) {
      throw new NotFoundException(`Record not found in ${tableName} with id: ${id}`);
    }

    await this.enforceBusinessRules(tableName, current, 'delete');

    const promotion = await this.promotionDispatcher.dispatch(tableName, id, 'delete', current);
    await executeAfterDeleteHooks(entity, promotion.promoted);

    return promotion;
  }

  private async verifyEntity(entity: string): Promise<void> {
    const tableName = this.getTableName(entity);
    const normalized = entity.toLowerCase().replace(/-/g, '_');
    const bareEntity = normalized.startsWith('bus_') ? normalized.slice(4) : normalized;

    let tableRecord = await this.kysely
      .selectFrom('sys_table')
      .selectAll()
      .where('table_name', '=', tableName)
      .where('is_active', '=', true)
      .executeTakeFirst();

    if (!tableRecord) {
      // Also accept user-created tables stored without bus_ prefix
      tableRecord = await this.kysely
        .selectFrom('sys_table')
        .selectAll()
        .where('table_name', '=', bareEntity)
        .where('is_active', '=', true)
        .executeTakeFirst();
    }

    if (!tableRecord) {
      throw new NotFoundException(`Entity '${entity}' not found in Application Dictionary`);
    }
  }

  async getEntityMetadata(entity: string): Promise<EntityMetadata> {
    const tableName = this.getTableName(entity);

    if (this.metadataCache.has(tableName)) {
      return this.metadataCache.get(tableName)!;
    }

    const normalizedEntity = entity.toLowerCase().replace(/-/g, '_');
    const bareEntity = normalizedEntity.startsWith('bus_') ? normalizedEntity.slice(4) : normalizedEntity;
    let table = await this.kysely
      .selectFrom('sys_table')
      .selectAll()
      .where('table_name', '=', tableName)
      .where('is_active', '=', true)
      .executeTakeFirst();
    if (!table) {
      table = await this.kysely
        .selectFrom('sys_table')
        .selectAll()
        .where('table_name', '=', bareEntity)
        .where('is_active', '=', true)
        .executeTakeFirst();
    }

    if (!table) {
      throw new NotFoundException(`Entity '${entity}' not found`);
    }

    const window = table.sys_window_id
      ? await this.kysely
          .selectFrom('sys_window')
          .selectAll()
          .where('sys_window_id', '=', table.sys_window_id)
          .executeTakeFirst()
      : undefined;

    const columns = await this.kysely
      .selectFrom('sys_column')
      .innerJoin('sys_tab', 'sys_tab.sys_table_id', 'sys_column.sys_table_id')
      .leftJoin('sys_field', (join) =>
        join
          .onRef('sys_field.sys_column_id', '=', 'sys_column.sys_column_id')
          .onRef('sys_field.sys_tab_id', '=', 'sys_tab.sys_tab_id'),
      )
      .leftJoin('sys_field_group', 'sys_field_group.sys_field_group_id', 'sys_field.sys_field_group_id')
      .select([
        'sys_column.sys_column_id',
        'sys_column.column_name',
        'sys_column.name',
        'sys_column.sys_reference_id',
        'sys_column.is_mandatory',
        'sys_column.is_updateable',
        'sys_column.field_length',
        'sys_column.default_value',
        'sys_column.seq_no',
        'sys_field.sys_field_id',
        'sys_field.seq_no as field_seq_no',
        'sys_field.seq_no_grid',
        'sys_field.is_displayed',
        'sys_field.is_displayed_grid',
        'sys_field.is_read_only as field_is_read_only',
        'sys_field.name as field_name',
        'sys_field.help as field_help',
        'sys_field.sys_field_group_id',
        'sys_field_group.name as group_name',
        'sys_field_group.columns as group_columns',
        'sys_field_group.description as group_description',
      ])
      .where('sys_column.sys_table_id', '=', table.sys_table_id)
      .where('sys_column.is_active', '=', true)
      .orderBy('sys_column.seq_no', 'asc')
      .execute();

    // Pre-resolve identifier fields for all referenced tables in this entity
    const refTableNames = [...new Set(
      columns
        .map((col: any) => this.resolveRefTableName(col.column_name, col.sys_reference_id))
        .filter(Boolean) as string[]
    )];
    const refLabelFieldsMap: Record<string, string[]> = {};
    await Promise.all(refTableNames.map(async (t) => {
      refLabelFieldsMap[t] = await this.resolveRefLabelFields(t);
    }));

    const metadata: EntityMetadata = {
      table: {
        sys_table_id: table.sys_table_id,
        table_name: table.table_name,
        name: table.name,
        description: table.description,
      },
      columns: columns.map((col: any) => {
        const refTableName = this.resolveRefTableName(col.column_name, col.sys_reference_id);
        return {
          sys_field_id: col.sys_field_id,
          name: col.field_name || col.name,
          column_name: col.column_name,
          sys_reference_id: col.sys_reference_id,
          is_mandatory: col.is_mandatory,
          is_updateable: col.is_updateable,
          field_length: col.field_length,
          default_value: col.default_value,
          ref_table_name: refTableName,
          ref_label_fields: refTableName ? (refLabelFieldsMap[refTableName] ?? []) : undefined,
          seq_no: col.field_seq_no || col.seq_no || 0,
          seq_no_grid: col.seq_no_grid || 0,
          is_displayed: col.is_displayed !== false,
          is_displayed_grid: col.is_displayed_grid !== false,
          is_read_only: col.field_is_read_only || false,
          help: col.field_help || undefined,
          field_group_id: col.sys_field_group_id || null,
          group_name: col.group_name || null,
          group_columns: col.group_columns || null,
          group_description: col.group_description || null,
        };
      }),
      window: window
        ? { sys_window_id: window.sys_window_id, name: window.name }
        : undefined,
    };

    this.metadataCache.set(tableName, metadata);
    return metadata;
  }

  async getFormFields(entity: string): Promise<FieldMetadata[]> {
    const metadata = await this.getEntityMetadata(entity);
    return metadata.columns.filter((col) => col.is_displayed).sort((a, b) => a.seq_no - b.seq_no);
  }

  async getGridFields(entity: string): Promise<FieldMetadata[]> {
    const metadata = await this.getEntityMetadata(entity);
    return metadata.columns.filter((col) => col.is_displayed_grid).sort((a, b) => a.seq_no_grid - b.seq_no_grid);
  }

  async validateData(entity: string, data: Record<string, any>, mode: 'create' | 'update' | 'patch'): Promise<void> {
    const metadata = await this.getEntityMetadata(entity);
    const errors: string[] = [];

    for (const column of metadata.columns) {
      // Skip auto-managed system columns in create mode
      if (mode === 'create' && BusService.AUTO_MANAGED_COLUMNS.has(column.column_name)) continue;
      const value = data[column.column_name];

      if (mode !== 'patch' && column.is_mandatory && !column.default_value) {
        if (value === undefined || value === null || value === '') {
          errors.push(`Field '${column.name}' (${column.column_name}) is required`);
        }
      }

      if (value && column.field_length && typeof value === 'string') {
        if (value.length > column.field_length) {
          errors.push(`Field '${column.name}' exceeds maximum length of ${column.field_length}`);
        }
      }

      if ((mode === 'update' || mode === 'patch') && !column.is_updateable) {
        // In patch mode: skip non-updateable fields silently (they are stripped before writing)
        // In update mode: only error on non-key non-updateable fields
        if (mode === 'patch') continue;
        if (value !== undefined && column.column_name !== 'id') {
          errors.push(`Field '${column.name}' is not updateable`);
        }
      }

      if (value !== undefined && value !== null) {
        const typeError = this.validateType(value, column.sys_reference_id, column.name);
        if (typeError) errors.push(typeError);
      }
    }

    if (errors.length > 0) {
      throw new BadRequestException({ message: 'Validation failed', errors });
    }
  }

  private validateType(value: any, referenceId: number, fieldName: string): string | null {
    switch (referenceId) {
      case 10: case 14: case 24: case 30: case 31:
        if (typeof value !== 'string') return `Field '${fieldName}' must be a string`;
        break;
      case 11:
        // Accept numeric strings — PostgreSQL integer columns may serialize as strings in JSON
        if (typeof value === 'string' && /^-?\d+$/.test(value.trim())) break;
        if (typeof value !== 'number' || !Number.isInteger(value)) return `Field '${fieldName}' must be an integer`;
        break;
      case 12:
        // Accept numeric strings — PostgreSQL NUMERIC/DECIMAL columns serialize as strings in JSON
        if (typeof value === 'string' && !isNaN(parseFloat(value.trim())) && isFinite(Number(value.trim()))) break;
        if (typeof value !== 'number') return `Field '${fieldName}' must be a number`;
        break;
      case 20:
        if (typeof value !== 'boolean') return `Field '${fieldName}' must be a boolean`;
        break;
      case 15: case 16:
        if (!(value instanceof Date) && isNaN(Date.parse(value))) return `Field '${fieldName}' must be a valid date`;
        break;
      case 13: case 18: case 19:
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
        if (typeof value !== 'string' || !uuidRegex.test(value)) return `Field '${fieldName}' must be a valid UUID`;
        break;
      case 28:
        if (typeof value !== 'object') return `Field '${fieldName}' must be a JSON object`;
        break;
    }
    return null;
  }

  private parseDefaultValue(defaultValue: string, referenceId: number): any {
    switch (referenceId) {
      case 11: return parseInt(defaultValue, 10);
      case 12: return parseFloat(defaultValue);
      case 20: return defaultValue.toLowerCase() === 'true' || defaultValue === 'Y';
      case 28: try { return JSON.parse(defaultValue); } catch { return {}; }
      default: return defaultValue;
    }
  }

  /**
   * FK columns naming a person by the role they played rather than by entity.
   * The `_by` / `_by_id` suffixes are handled by rule in resolveRefTableName;
   * this map covers the role names that carry no suffix at all. Kept in sync
   * with `foreignKeys.personRoleColumns` in language/erdwithai-language.json.
   */
  private static readonly COLUMN_TABLE_ALIASES: Record<string, string> = {
    owner_id: 'bus_user',
    author_id: 'bus_user',
    manager_id: 'bus_user',
    assigned_to: 'bus_user',
    pi_id: 'bus_user',
    lab_manager_id: 'bus_user',
    remediation_owner: 'bus_user',
    remediation_owner_id: 'bus_user',
    user_id: 'bus_user',
    created_by_user: 'bus_user',
  };

  private async resolveRefLabelFields(refTableName: string): Promise<string[]> {
    if (this.identifierFieldsCache.has(refTableName)) {
      return this.identifierFieldsCache.get(refTableName)!;
    }
    try {
      const sysTable = await this.kysely
        .selectFrom('sys_table')
        .select('sys_table_id')
        .where('table_name', '=', refTableName)
        .executeTakeFirst();
      if (!sysTable) return [];
      const cols = await this.kysely
        .selectFrom('sys_column')
        .select(['column_name', 'seq_no'])
        .where('sys_table_id', '=', sysTable.sys_table_id)
        .where('is_identifier', '=', true)
        .orderBy('seq_no', 'asc')
        .execute();
      const fields = cols.map((c: any) => c.column_name);
      this.identifierFieldsCache.set(refTableName, fields);
      return fields;
    } catch {
      return [];
    }
  }

  private resolveRefTableName(columnName: string, sysReferenceId: number): string | undefined {
    if (sysReferenceId !== 18 && sysReferenceId !== 19) return undefined;
    if (BusService.COLUMN_TABLE_ALIASES[columnName]) {
      return BusService.COLUMN_TABLE_ALIASES[columnName];
    }
    // A _by column names a person: reported_by_id, approved_by_id, performed_by
    // all point at a user. Both spellings are matched — _by_id is the form the
    // EML fixer produces, _by is what an unfixed model still carries. Deriving
    // bus_reported_by from the name would look up a table that does not exist,
    // so the column would fall back to rendering its raw id.
    if (columnName.endsWith('_by_id') || columnName.endsWith('_by')) return 'bus_user';
    if (!columnName.endsWith('_id') || columnName === 'id') return undefined;
    const baseName = columnName.slice(0, -3);
    return `bus_${baseName}`;
  }

  clearMetadataCache(): void {
    this.metadataCache.clear();
  }

  /**
   * Auto-creates sys_window, sys_tab, and sys_field records from existing
   * sys_column records for a given entity. This allows a newly registered
   * table/column (added via the admin Tables UI) to immediately appear in the
   * dynamic form renderer without requiring a code-gen cycle.
   *
   * Schema relationships:
   *   sys_table.sys_window_id → sys_window (FK on sys_table side)
   *   sys_tab.sys_window_id + sys_tab.sys_table_id → links tab to window+table
   *   sys_field.sys_tab_id + sys_field.sys_column_id → links field to tab+column
   *
   * Idempotent — safe to call multiple times.
   */
  async setupEntityDictionary(entity: string): Promise<{ created: string[] }> {
    const tableName = this.getTableName(entity);
    const methodName = 'setupEntityDictionary';
    this.logger.log(`[${methodName}] Setting up dictionary for entity: ${entity} (table: ${tableName})`);

    const created: string[] = [];
    const systemUser = 'system';

    // 1. Find the sys_table record — try both bus_entity and entity (user-created tables store plain name)
    const normalizedEntity = entity.toLowerCase().replace(/-/g, '_');
    const bareEntity = normalizedEntity.startsWith('bus_') ? normalizedEntity.slice(4) : normalizedEntity;
    let sysTable = await this.kysely
      .selectFrom('sys_table')
      .selectAll()
      .where('table_name', '=', tableName)
      .executeTakeFirst();
    if (!sysTable) {
      sysTable = await this.kysely
        .selectFrom('sys_table')
        .selectAll()
        .where('table_name', '=', bareEntity)
        .executeTakeFirst();
    }

    if (!sysTable) {
      throw new NotFoundException(`No sys_table record found for table '${tableName}'. Register the table first via the admin Tables UI.`);
    }

    const sysTableId = sysTable.sys_table_id;
    const entityLabel = sysTable.name || entity.charAt(0).toUpperCase() + entity.slice(1);

    // 2. Ensure sys_window exists (sys_table.sys_window_id is the FK)
    let windowId: string;
    if (sysTable.sys_window_id) {
      windowId = sysTable.sys_window_id;
      this.logger.log(`[${methodName}] sys_window already exists: ${windowId}`);
    } else {
      windowId = randomUUID();
      await this.kysely.insertInto('sys_window').values({
        sys_window_id: windowId,
        name: entityLabel,
        description: `${entityLabel} management window`,
        window_type: 'M',
        entity_type: 'U',
        is_active: true,
        created_by: systemUser,
        updated_by: systemUser,
      } as any).execute();

      // Link window to table via sys_table.sys_window_id
      await this.kysely.updateTable('sys_table')
        .set({ sys_window_id: windowId } as any)
        .where('sys_table_id', '=', sysTableId)
        .execute();

      created.push(`sys_window: ${windowId}`);
      this.logger.log(`[${methodName}] Created sys_window ${windowId} for ${tableName}`);
    }

    // 3. Ensure sys_tab exists
    const existingTab = await this.kysely
      .selectFrom('sys_tab')
      .select(['sys_tab_id'])
      .where('sys_window_id', '=', windowId)
      .where('sys_table_id', '=', sysTableId)
      .executeTakeFirst();

    let tabId: string;
    if (!existingTab) {
      tabId = randomUUID();
      await this.kysely.insertInto('sys_tab').values({
        sys_tab_id: tabId,
        sys_window_id: windowId,
        sys_table_id: sysTableId,
        name: entityLabel,
        description: `${entityLabel} details tab`,
        seq_no: 10,
        entity_type: 'U',
        is_active: true,
        created_by: systemUser,
        updated_by: systemUser,
      } as any).execute();
      created.push(`sys_tab: ${tabId}`);
      this.logger.log(`[${methodName}] Created sys_tab ${tabId} for ${tableName}`);
    } else {
      tabId = existingTab.sys_tab_id;
      this.logger.log(`[${methodName}] sys_tab already exists: ${tabId}`);
    }

    // 4. Get all sys_column records for this table
    const columns = await this.kysely
      .selectFrom('sys_column')
      .selectAll()
      .where('sys_table_id', '=', sysTableId)
      .orderBy('seq_no', 'asc')
      .execute();

    this.logger.log(`[${methodName}] Found ${columns.length} columns for ${tableName}`);

    // 5. For each column, ensure a sys_field record exists
    const SKIP_COLUMNS = new Set(['id', 'created_at', 'updated_at', 'deleted_at', 'version', 'is_active']);
    let seqNo = 10;
    let seqNoGrid = 10;

    for (const col of columns) {
      if (SKIP_COLUMNS.has(col.column_name)) continue;

      const existingField = await this.kysely
        .selectFrom('sys_field')
        .select(['sys_field_id'])
        .where('sys_tab_id', '=', tabId)
        .where('sys_column_id', '=', col.sys_column_id)
        .executeTakeFirst();

      if (!existingField) {
        const fieldId = randomUUID();
        await this.kysely.insertInto('sys_field').values({
          sys_field_id: fieldId,
          sys_tab_id: tabId,
          sys_column_id: col.sys_column_id,
          name: col.name || col.column_name,
          seq_no: seqNo,
          seq_no_grid: seqNoGrid,
          is_displayed: true,
          is_displayed_grid: seqNoGrid <= 50, // show first 5 columns in grid
          is_read_only: false,
          entity_type: 'U',
          is_active: true,
          created_by: systemUser,
          updated_by: systemUser,
        } as any).execute();
        created.push(`sys_field: ${col.column_name}`);
        this.logger.log(`[${methodName}] Created sys_field for column ${col.column_name}`);
        seqNo += 10;
        seqNoGrid += 10;
      } else {
        this.logger.debug(`[${methodName}] sys_field already exists for column ${col.column_name}`);
      }
    }

    // 6. Invalidate metadata cache so next request picks up new fields
    this.metadataCache.delete(entity);
    this.metadataCache.delete(tableName);

    this.logger.log(`[${methodName}] Complete. Created: ${created.join(', ') || 'nothing (all already existed)'}`);
    return { created };
  }
}

/**
 * Entity Promotion Service — Draft → Final
 *
 * Every business entity is saved in `draft`. Promotion is the step that runs the
 * rules and workflows associated with that record and, only if all of them
 * succeed, marks it `final`.
 *
 * The contract:
 *   - nothing associated  → promoted to `final` immediately, no transaction needed
 *   - everything succeeds → side effects committed and the row marked `final`, atomically
 *   - anything fails      → every side effect rolled back, the row stays `draft`, and
 *                           `doc_status_message` explains what failed and why so the
 *                           user can fix it and retry
 *
 * The rollback boundary is deliberate. The entity row itself is committed by the
 * caller before promotion runs, so a failure never loses the user's data — it
 * leaves them a saved draft plus an explanation. Only the *derived* work (cascade
 * writes, workflow mutations, the status flip) is transactional.
 */

import { Injectable, Logger, Inject, forwardRef } from '@nestjs/common';
import { sql, type Kysely } from 'kysely';
import { InjectDatabase } from '../../database/database.service.decorator';
import { RulesService } from '../rules/rules.service';
import type { MatchedAction } from '../rules/rules.service';
import { WorkflowService } from '../workflow/workflow.service';

/**
 * `draft` and `final` are stored on the row. `deleted` never is — the row is
 * gone by the time it is reported, and it exists here so a caller can tell a
 * successful delete from a successful save.
 */
export type DocStatus = 'draft' | 'final' | 'deleted';

export interface PromotionResult {
  entityName: string;
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  /** Where the record ended up. */
  docStatus: DocStatus;
  promoted: boolean;
  /** Human-readable summary — surfaced to the user verbatim when promotion fails. */
  message: string;
  /** What the pipeline found to run. Empty on both sides means the fast path was taken. */
  ranRules: string[];
  ranWorkflows: string[];
  /** Populated only on failure: the step that broke and the underlying error. */
  failedStep?: string;
  error?: string;
  durationMs: number;
}

@Injectable()
export class EntityPromotionService {
  private readonly logger = new Logger(EntityPromotionService.name);

  constructor(
    @InjectDatabase() private readonly db: Kysely<any>,
    @Inject(forwardRef(() => RulesService)) private readonly rulesService: RulesService,
    @Inject(forwardRef(() => WorkflowService)) private readonly workflowService: WorkflowService,
  ) {}

  /**
   * Run the promotion pipeline for one record.
   *
   * Never throws: a failure is a result the caller shows the user, not an
   * exception that loses the saved draft.
   */
  async promote(
    entityName: string,
    entityId: string,
    operation: 'create' | 'update' | 'delete',
    entityData: Record<string, unknown>,
  ): Promise<PromotionResult> {
    const startedAt = Date.now();
    const tableName = this.resolveTable(entityName);

    const base = {
      entityName: tableName,
      entityId,
      operation,
      ranRules: [] as string[],
      ranWorkflows: [] as string[],
    };

    // ── 1. What is associated with this record? ──────────────────────────────
    let actions: MatchedAction[] = [];
    let workflowNames: string[] = [];
    try {
      [actions, workflowNames] = await Promise.all([
        this.rulesService.collectActionableActions(tableName, entityData, operation),
        this.findWorkflowNames(tableName, operation),
      ]);
    } catch (err: any) {
      return this.fail(base, startedAt, 'discovering associated rules and workflows', err, entityData);
    }

    const ruleNames = [...new Set(actions.map((a) => a.ruleName))];

    // A workflow a matched rule triggers runs too, so name it alongside the
    // automatic ones rather than leaving the report short by exactly the
    // workflow the write was interesting enough to set off.
    workflowNames = [...new Set([...workflowNames, ...this.workflowNamesFromActions(actions)])];

    // A delete ends by removing the row rather than by stamping a status on it,
    // and the removal belongs in the same transaction as the workflows that run
    // first — those are what clear the record's children, so a cascade that
    // fails must leave the parent standing rather than orphan what it could not
    // reach.
    const isDelete = operation === 'delete';
    const finalise = async (db: Kysely<any>) => {
      if (isDelete) {
        await db.deleteFrom(tableName as any).where('id' as any, '=', entityId).execute();
      } else {
        await this.setDocStatus(db, tableName, entityId, 'final', null);
      }
    };
    const finaliseStep = isDelete ? 'deleting the record' : 'marking the record final';
    const finalisedMessage = isDelete ? 'Deleted' : 'Finalised';

    // ── 2. Nothing associated → finalise directly ────────────────────────────
    if (actions.length === 0 && workflowNames.length === 0) {
      try {
        await finalise(this.db);
      } catch (err: any) {
        return this.fail(base, startedAt, finaliseStep, err, entityData);
      }
      this.logger.log(
        `${isDelete ? 'Deleted' : 'Promoted'} ${tableName}:${entityId} (no associated rules or workflows)`,
      );
      return {
        ...base,
        docStatus: isDelete ? 'deleted' : 'final',
        promoted: true,
        message: isDelete
          ? 'No business rules or workflows are associated with this record, so it was deleted directly.'
          : 'No business rules or workflows are associated with this record, so it was finalised automatically.',
        durationMs: Date.now() - startedAt,
      };
    }

    // ── 3. Something associated → all-or-nothing ─────────────────────────────
    let failedStep = 'running the associated business rules';
    try {
      await this.db.transaction().execute(async (trx) => {
        if (actions.length > 0) {
          await this.rulesService.executeMatchedActions(tableName, entityId, entityData, operation, {
            db: trx,
            throwOnError: true,
          });
        }

        if (workflowNames.length > 0) {
          failedStep = 'running the associated workflows';
          await this.workflowService.runLocalWorkflows(tableName, entityId, operation, entityData, {}, {
            db: trx,
            throwOnError: true,
          });
        }

        failedStep = finaliseStep;
        await finalise(trx);
      });
    } catch (err: any) {
      return this.fail({ ...base, ranRules: ruleNames, ranWorkflows: workflowNames }, startedAt, failedStep, err, entityData);
    }

    const summary = [
      ruleNames.length ? `${ruleNames.length} rule action(s)` : null,
      workflowNames.length ? `${workflowNames.length} workflow(s)` : null,
    ]
      .filter(Boolean)
      .join(' and ');

    this.logger.log(
      `${isDelete ? 'Deleted' : 'Promoted to final'} ${tableName}:${entityId} after ${summary}`,
    );
    return {
      ...base,
      ranRules: ruleNames,
      ranWorkflows: workflowNames,
      docStatus: isDelete ? 'deleted' : 'final',
      promoted: true,
      message: `${finalisedMessage} after successfully running ${summary}.`,
      durationMs: Date.now() - startedAt,
    };
  }

  /**
   * The job runner itself failed, so the pipeline never ran. Treated exactly like
   * a pipeline failure from the user's point of view — the record stays draft with
   * an explanation — because the outcome is the same: not finalised, retry needed.
   */
  async recordDispatchFailure(
    entityName: string,
    entityId: string,
    operation: 'create' | 'update' | 'delete',
    error: string,
  ): Promise<PromotionResult> {
    return this.fail(
      {
        entityName: this.resolveTable(entityName),
        entityId,
        operation,
        ranRules: [],
        ranWorkflows: [],
      },
      Date.now(),
      'handing the promotion to the background job runner (Trigger.dev)',
      new Error(error),
      {},
    );
  }

  /**
   * Record the failure on the row itself so the user sees it next time they open
   * the record, not only in the response to the save that failed.
   *
   * This write is deliberately outside the rolled-back transaction.
   */
  private async fail(
    base: Pick<PromotionResult, 'entityName' | 'entityId' | 'operation' | 'ranRules' | 'ranWorkflows'>,
    startedAt: number,
    failedStep: string,
    err: any,
    entityData: Record<string, unknown>,
  ): Promise<PromotionResult> {
    const error = err?.message ?? String(err);
    const message = this.buildFailureMessage(base, failedStep, error);

    this.logger.error(`Promotion failed for ${base.entityName}:${base.entityId} — ${failedStep}: ${error}`);

    try {
      // A delete that rolled back leaves the record exactly as it was, status
      // included: it was never a draft, and demoting it would corrupt a
      // finalised record because someone tried to remove it.
      if (base.operation !== 'delete') {
        await this.setDocStatus(this.db, base.entityName, base.entityId, 'draft', message);
      }
    } catch (statusErr: any) {
      // The record keeps its existing draft status; the response still carries the detail.
      this.logger.error(
        `Could not record the failure on ${base.entityName}:${base.entityId}: ${statusErr?.message ?? statusErr}`,
      );
    }

    return {
      ...base,
      // A delete that failed left the row untouched, so report the status it
      // still has rather than claiming it was demoted to a draft.
      docStatus: base.operation === 'delete' ? 'final' : 'draft',
      promoted: false,
      message,
      failedStep,
      error,
      durationMs: Date.now() - startedAt,
    };
  }

  /**
   * The text the user actually reads. It has to answer three questions without
   * making them go digging in server logs: what stage broke, what the underlying
   * error was, and what happened to their data.
   */
  private buildFailureMessage(
    base: Pick<PromotionResult, 'entityName' | 'entityId' | 'operation' | 'ranRules' | 'ranWorkflows'>,
    failedStep: string,
    error: string,
  ): string {
    // A failed delete did not save a draft — nothing was saved at all. Saying
    // otherwise sends the reader looking for a draft that does not exist.
    const parts = [
      base.operation === 'delete'
        ? 'This record could not be deleted and is unchanged.'
        : 'This record could not be finalised and has been kept as a draft.',
    ];
    parts.push(`Failed while ${failedStep}: ${error}`);

    if (base.ranRules.length > 0) {
      parts.push(`Rules involved: ${base.ranRules.join(', ')}.`);
    }
    if (base.ranWorkflows.length > 0) {
      parts.push(`Workflows involved: ${base.ranWorkflows.join(', ')}.`);
    }

    parts.push(
      'No partial changes were kept — every change the rules and workflows made was rolled back. ' +
        'Fix the cause and retry, or correct the record and save again.',
    );
    return parts.join(' ');
  }

  /** Active workflow definitions for this entity + operation, by name. */
  /**
   * The workflows that will actually run for this write.
   *
   * Only `automatic` definitions, because that is the same filter
   * `runLocalWorkflows` applies. Without it this counted rule-triggered
   * workflows too and the result claimed them as run: creating a non-critical
   * deviation reported "successfully running 2 workflow(s)" when the escalation
   * had correctly declined to fire.
   *
   * A rule-triggered workflow that does fire is added by the caller from the
   * matched rule actions, so the report names what happened either way.
   */
  private async findWorkflowNames(
    tableName: string,
    operation: 'create' | 'update' | 'delete',
  ): Promise<string[]> {
    const normalized = tableName.toLowerCase().replace(/^bus_/, '');
    const candidates = [normalized, `bus_${normalized}`];

    const rows = await this.db
      .selectFrom('sys_workflow_definitions')
      .select(['name'])
      .where((eb: any) =>
        eb.or(candidates.map((c) => eb(sql<string>`lower(entity_name)`, '=', c))),
      )
      .where((eb: any) =>
        eb.or([eb('operation', '=', operation.toUpperCase()), eb('operation', '=', 'ALL')]),
      )
      .where('is_active', '=', true)
      .where('trigger_type', '=', 'automatic')
      .execute();

    return rows.map((r: any) => r.name as string);
  }

  /** Workflow names named by the `trigger-workflow` actions that matched. */
  private workflowNamesFromActions(actions: MatchedAction[]): string[] {
    return actions
      .filter((action) => action.type === 'trigger-workflow')
      .map((action) => String((action.config as any)?.workflowName ?? '').trim())
      .filter(Boolean);
  }

  private async setDocStatus(
    db: Kysely<any>,
    tableName: string,
    entityId: string,
    status: DocStatus,
    message: string | null,
  ): Promise<void> {
    await db
      .updateTable(tableName as any)
      .set({ doc_status: status, doc_status_message: message } as any)
      .where('id' as any, '=', entityId)
      .execute();
  }

  private resolveTable(entity: string): string {
    const normalized = entity.toLowerCase().replace(/-/g, '_');
    return normalized.startsWith('bus_') ? normalized : `bus_${normalized}`;
  }
}

