 */

export type HookLifecycle =
  | 'beforeCreate'
  | 'afterCreate'
  | 'beforeUpdate'
  | 'afterUpdate'
  | 'beforeDelete'
  | 'afterDelete'
  | 'beforeQuery'
  | 'afterQuery'
  | 'beforeRead'
  | 'afterRead'
  | 'beforeList'
  | 'afterList';

export interface HookContext<T = any> {
  entity: string;
  lifecycle: HookLifecycle;
  data: T;
  user?: any;
  metadata?: Record<string, any>;
}

export interface Hook<T = any> {
  name: string;
  lifecycle: HookLifecycle;
  priority: number;
  execute: (context: HookContext<T>) => Promise<void | T>;
}

/**
 * Hook Executor
 *
 * Executes registered hooks for entity lifecycle events.
 * Generated: {{now}}
 */

import { HookContext, HookLifecycle } from './hook.types';
import { globalHookRegistry } from './hook-registry';

export class HookExecutor {
  async execute<T>(
    entityName: string,
    lifecycle: HookLifecycle,
    data: T,
    metadata?: Record<string, any>
  ): Promise<T> {
    const hooks = globalHookRegistry.getHooks(entityName, lifecycle);

    let result = data;
    const context: HookContext<T> = {
      entity: entityName,
      lifecycle,
      data: result,
      metadata
    };

    for (const hook of hooks) {
      const hookResult = await hook.execute(context);
      if (hookResult !== undefined) {
        result = hookResult;
        context.data = result;
      }
    }

    return result;
  }
}

export const globalHookExecutor = new HookExecutor();

/**
 * Hook Registry
 *
 * Manages registration and retrieval of hooks for entity lifecycle events.
 * Generated: {{now}}
 */

import { Hook, HookLifecycle } from './hook.types';

export class HookRegistry {
  private hooks: Map<string, Hook[]> = new Map();

  register(entityName: string, hook: Hook): void {
    const key = `${entityName}:${hook.lifecycle}`;
    if (!this.hooks.has(key)) {
      this.hooks.set(key, []);
    }
    const hooks = this.hooks.get(key)!;
    hooks.push(hook);
    hooks.sort((a, b) => a.priority - b.priority);
  }

  getHooks(entityName: string, lifecycle: HookLifecycle): Hook[] {
    const key = `${entityName}:${lifecycle}`;
    return this.hooks.get(key) || [];
  }

  clear(entityName?: string): void {
    if (entityName) {
      const keysToDelete = Array.from(this.hooks.keys()).filter(key =>
        key.startsWith(`${entityName}:`)
      );
      keysToDelete.forEach(key => this.hooks.delete(key));
    } else {
      this.hooks.clear();
    }
  }
}

export const globalHookRegistry = new HookRegistry();

