  async findColumnById(id: string) {
    const column = await this.db.kysely.selectFrom('sys_column').selectAll()
      .where('sys_column_id', '=', id).executeTakeFirst();
    if (!column) throw new NotFoundException(`Column with ID ${id} not found`);
