  /** BPMN diagrams carry XML; automations carry mermaid. Exactly one is required. */
  bpmnXml?: string;
  /** Mermaid with `%%` directives, as the automation builder writes it. */
  mermaid?: string;
  /** "bpmn" or "automation". Defaults to bpmn, which is what every older row is. */
  kind?: "bpmn" | "automation";
  description?: string;
  isActive?: boolean;
  /**
   * How the definition is reached.
   *   automatic  run on every write matching entityName + operation
   *   rule       run only when a rule's trigger-workflow action names it
   * Defaults to automatic, which is what an unmarked definition has always done.
   */
  triggerType?: "automatic" | "rule";
};

/**
 * Content fields a model-owned definition will not accept through the API.
 *
 * `isActive` is deliberately absent: switching a workflow off is an operational
 * decision an admin should be able to take without editing the model. The next
 * generation turns it back on, which is the honest outcome — the model says it
 * should be running.
 */
const MODEL_OWNED_FIELDS = [
  "name",
  "entityName",
  "operation",
  "bpmnXml",
  "description",
  "triggerType",
] as const;

@Injectable()
export class WorkflowDefinitionsService {
  constructor(@InjectDatabase() private readonly db: Kysely<any>) {}

  /**
   * A page of definitions, newest first.
   *
   * Paged rather than unbounded: an app that has been running a while
   * accumulates definitions faster than anyone deletes them, and a list
   * endpoint that returns all of them eventually times out the page that
   * depends on it. 200 is the default because it fills the longest rail the
   * builder draws without a second request.
   */
  async findAll(filters?: {
    entityName?: string;
    operation?: string;
    isActive?: boolean;
    kind?: string;
    limit?: number;
    offset?: number;
  }) {
    const limit = Math.min(Math.max(filters?.limit ?? 200, 1), 200);
    const offset = Math.max(filters?.offset ?? 0, 0);

    const where = <T extends { where: any }>(q: T): T => {
      let query: any = q;
      if (filters?.entityName) query = query.where("entity_name", "=", filters.entityName);
      if (filters?.operation) query = query.where("operation", "=", filters.operation);
      if (filters?.isActive !== undefined) query = query.where("is_active", "=", filters.isActive);
      if (filters?.kind) query = query.where("kind", "=", filters.kind);
      return query as T;
    };

    const items = await where(this.db.selectFrom("sys_workflow_definitions").selectAll())
      .orderBy("created_at", "desc")
      .limit(limit)
      .offset(offset)
      .execute();

    const counted = await where(
      this.db
        .selectFrom("sys_workflow_definitions")
        .select((eb: any) => eb.fn.countAll().as("total"))
    ).executeTakeFirst();

    const total = Number((counted as { total?: number | string })?.total ?? items.length);
    return { items, total, limit, offset, hasMore: offset + items.length < total };
  }

  async findOne(id: string) {
    const def = await this.db
      .selectFrom("sys_workflow_definitions")
      .selectAll()
      .where("id", "=", id)
      .executeTakeFirst();
    if (!def) throw new NotFoundException(`Workflow definition ${id} not found`);
    return def;
  }

  async findActiveForEntity(entityName: string, operation: string) {
    // Match definitions stored under either the singular base name (e.g. 'account')
    // or the full bus_ table name (e.g. 'bus_account').
    const candidates = Array.from(new Set([entityName, `bus_${entityName}`])).map((n) =>
      n.toLowerCase()
    );
    return this.db
      .selectFrom("sys_workflow_definitions")
      .selectAll()
      .where((eb) => eb.or(candidates.map((c) => eb(sql<string>`lower(entity_name)`, "=", c))))
      .where((eb) =>
        eb.or([eb("operation", "=", operation.toUpperCase()), eb("operation", "=", "ALL")])
      )
      .where("is_active", "=", true)
      .orderBy("created_at", "asc")
      .execute();
  }

  async create(dto: WorkflowDefinitionDto, userId?: string) {
    // A definition is either a BPMN diagram or a mermaid automation. Demanding
    // BPMN of both is what stopped the automation builder saving anything.
    const kind = dto.kind ?? (dto.mermaid?.trim() ? "automation" : "bpmn");

    if (kind === "automation") {
      if (!dto.mermaid?.trim()) throw new BadRequestException("mermaid is required");
      if (!/^\s*(flowchart|graph)\b/m.test(dto.mermaid)) {
        throw new BadRequestException("An automation must be a mermaid flowchart");
      }
    } else {
      if (!dto.bpmnXml?.trim()) throw new BadRequestException("bpmnXml is required");
      if (!dto.bpmnXml.includes("<bpmn:")) throw new BadRequestException("Invalid BPMN XML");
    }

    const [result] = await this.db
      .insertInto("sys_workflow_definitions")
      .values({
        name: dto.name,
        entity_name: dto.entityName,
        operation: dto.operation ?? "ALL",
        bpmn_xml: dto.bpmnXml ?? null,
        mermaid_code: dto.mermaid ?? null,
        kind,
        description: dto.description ?? null,
        trigger_type: dto.triggerType ?? "automatic",
        // Anything created through the API was built in the app, so the model
        // seed leaves it alone.
        source: "designer",
        is_active: dto.isActive ?? true,
        created_by: userId ?? null,
      } as any)
      .returningAll()
      .execute();
    return result;
  }

  async update(id: string, dto: Partial<WorkflowDefinitionDto>) {
    const existing = await this.findOne(id);

    // A definition declared by a %%workflow section belongs to the model. The
    // next generation rewrites it, so accepting an edit here would look like it
    // worked and then quietly vanish.
    if ((existing as any).source === "model") {
      const attempted = MODEL_OWNED_FIELDS.filter((field) => dto[field] !== undefined);
      if (attempted.length > 0) {
        throw new BadRequestException(
          `"${(existing as any).name}" is declared in the model — edit the %%workflow section and regenerate. ` +
            `Rejected: ${attempted.join(", ")}.`,
        );
      }
    }

    const updates: Record<string, unknown> = { updated_at: new Date() };
    if (dto.name !== undefined) updates.name = dto.name;
    if (dto.entityName !== undefined) updates.entity_name = dto.entityName;
    if (dto.operation !== undefined) updates.operation = dto.operation;
    if (dto.bpmnXml !== undefined) updates.bpmn_xml = dto.bpmnXml;
    if (dto.description !== undefined) updates.description = dto.description;
    if (dto.isActive !== undefined) updates.is_active = dto.isActive;
    if (dto.triggerType !== undefined) updates.trigger_type = dto.triggerType;

    const [result] = await this.db
      .updateTable("sys_workflow_definitions")
      .set(updates as any)
      .where("id", "=", id)
      .returningAll()
      .execute();
    return result;
  }

  async remove(id: string) {
    const existing = await this.findOne(id);
    if ((existing as any).source === "model") {
      throw new BadRequestException(
        `"${(existing as any).name}" is declared in the model — remove the %%workflow section and regenerate. ` +
          "Deactivate it instead if you need it off now.",
      );
    }
    await this.db.deleteFrom("sys_workflow_definitions").where("id", "=", id).execute();
    return { deleted: true };
  }
}

import { Module } from "@nestjs/common";
import { DatabaseModule } from "../../database/database.module";
import { WorkflowDefinitionsController } from "./workflow-definitions.controller";
import { WorkflowDefinitionsService } from "./workflow-definitions.service";

@Module({
  imports: [DatabaseModule],
  controllers: [WorkflowDefinitionsController],
  providers: [WorkflowDefinitionsService],
  exports: [WorkflowDefinitionsService],
})
export class WorkflowDefinitionsModule {}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Put,
  Query,
  UseGuards,
} from "@nestjs/common";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { RolesGuard } from "../auth/guards/roles.guard";
import { WorkflowDefinitionsService } from "./workflow-definitions.service";
import type { WorkflowDefinitionDto } from "./workflow-definitions.service";

/**
 * Workflow definitions decide what runs on every write, so they are guarded the
 * same way business rules are. This controller shipped with no guards at all:
 * `GET /api/workflow-definitions` returned every definition to anyone who
 * asked, and PUT/POST/DELETE let them be rewritten without signing in.
 */
@UseGuards(SessionAuthGuard, RolesGuard)
@Controller("workflow-definitions")
export class WorkflowDefinitionsController {
  constructor(private readonly service: WorkflowDefinitionsService) {}

  /**
   * A page of definitions. Defaults to 200, which is also the ceiling — a list
   * endpoint that can be asked for everything eventually is, and then times out.
   */
  @Get()
  findAll(
    @Query('entityName') entityName?: string,
    @Query('operation') operation?: string,
    @Query('isActive') isActive?: string,
    @Query('kind') kind?: string,
    @Query('limit') limit?: string,
    @Query('offset') offset?: string
  ) {
    return this.service.findAll({
      entityName,
      operation,
      isActive: isActive !== undefined ? isActive === "true" : undefined,
      kind,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
  }

  @Get(':id')
  findOne(@Param('id') id: string) {
    return this.service.findOne(id);
  }

  @Post()
  create(@Body() dto: WorkflowDefinitionDto) {
    return this.service.create(dto);
  }

  @Put(":id")
  update(@Param('id') id: string, @Body() dto: Partial<WorkflowDefinitionDto>) {
    return this.service.update(id, dto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.OK)
  remove(@Param('id') id: string) {
    return this.service.remove(id);
  }
}

import { z } from 'zod';

/**
 * JDM content arrives either as a JSON string (older callers, and anything that
 * serialises before posting) or as the object the rule table editor holds in
 * state. Accepting only the string meant a table built in the editor was
 * rejected at the door with "Validation failed" and no way to tell why.
 */
const JdmContent = z.union([z.string(), z.record(z.unknown())]);

export const CreateRuleSchema = z.object({
  entityName: z.string().min(1),
  ruleName: z.string().min(1),
  operation: z.enum(['CREATE', 'READ', 'UPDATE', 'DELETE', 'ALL']),
  jdmContent: JdmContent,
});

export type CreateRuleDto = z.infer<typeof CreateRuleSchema>;

export const UpdateRuleSchema = z.object({
  jdmContent: JdmContent.optional(),
  isActive: z.boolean().optional(),
});

export type UpdateRuleDto = z.infer<typeof UpdateRuleSchema>;

export const ValidateJdmSchema = z.object({
  jdmContent: JdmContent,
});

export type ValidateJdmDto = z.infer<typeof ValidateJdmSchema>;

export const DryRunSchema = z.object({
  ruleId: z.string(),
  testData: z.record(z.unknown()),
});

export type DryRunDto = z.infer<typeof DryRunSchema>;

export const EvaluateRulesSchema = z.object({
  entityName: z.string(),
  operation: z.enum(['CREATE', 'READ', 'UPDATE', 'DELETE']),
  data: z.record(z.unknown()),
});

export type EvaluateRulesDto = z.infer<typeof EvaluateRulesSchema>;

/**
 * Rules Service - Database-Persistent Business Rules
 *
 * Provides CRUD operations for managing business rules in the database.
 * Integrates with GoRules Zen Engine for rule evaluation.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Injectable, Logger, NotFoundException, BadRequestException, Inject, forwardRef } from '@nestjs/common';
import type { Kysely } from 'kysely';
import { InjectDatabase } from '../../database/database.service.decorator';
import { RulesEngine } from './rules-engine.service';
import type { RuleEvaluationResult } from './rules-engine.service';
import { readFileSync } from 'fs';
import { WorkflowService } from '../workflow/workflow.service';
import { join } from 'path';

export interface CreateRuleDto {
  entityName: string;
  ruleName: string;
  operation: 'CREATE' | 'READ' | 'UPDATE' | 'DELETE' | 'ALL';
  jdmContent: string | Record<string, unknown>;
}

export interface UpdateRuleDto {
  jdmContent?: string | Record<string, unknown>;
  isActive?: boolean;
}

/** Rule action types that write to the database — the ones a promotion must run atomically. */
export const SIDE_EFFECTING_ACTIONS = [
  'cascade-update',
  'cascade-delete',
  'cascade-create',
  'transform',
  'trigger-workflow',
] as const;

export interface RuleActionOptions {
  /** Run every write on this connection. Pass a transaction to make the batch atomic. */
  db?: Kysely<any>;
  /** Throw on the first failing action instead of logging it and carrying on. */
  throwOnError?: boolean;
}

export interface MatchedAction {
  ruleName: string;
  type: string;
  config: Record<string, unknown>;
}

export interface Rule {
  id: string;
  entityName: string;
  ruleName: string;
  operation: string;
  jdmContent: string | Record<string, unknown>;
  version: number;
  isActive: boolean;
  createdBy: string;
  updatedBy?: string;
  createdAt: Date;
  updatedAt: Date;
}

@Injectable()
export class RulesService {
  private readonly logger = new Logger(RulesService.name);

  constructor(
    private readonly rulesEngine: RulesEngine,
    @InjectDatabase() private readonly db: Kysely<any>,
    @Inject(forwardRef(() => WorkflowService)) private readonly workflowService: WorkflowService,
  ) {}

  /**
   * Get all rules with optional filtering
   */
  /**
   * A page of rules, capped at 200.
   *
   * Rules accumulate — one per entity per operation, plus every table an
   * automation looks up — so the list endpoint has to be bounded or the admin
   * page that reads it eventually stops loading.
   */
  async findAll(filters?: {
    entityName?: string;
    operation?: string;
    isActive?: boolean;
    limit?: number;
    offset?: number;
  }): Promise<Rule[]> {
    let query = this.db.selectFrom('sys_rule_definitions').selectAll();

    if (filters?.entityName) {
      query = query.where('entity_name', '=', filters.entityName);
    }

    if (filters?.operation) {
      query = query.where('operation', '=', filters.operation.toUpperCase());
    }

    if (filters?.isActive !== undefined) {
      query = query.where('is_active', '=', filters.isActive);
    }

    const limit = Math.min(Math.max(filters?.limit ?? 200, 1), 200);
    const offset = Math.max(filters?.offset ?? 0, 0);

    const rules = await query
      .orderBy('entity_name', 'asc')
      .orderBy('operation', 'asc')
      .orderBy('rule_name', 'asc')
      .limit(limit)
      .offset(offset)
      .execute();

    return rules.map((rule) => this.mapDbRuleToRule(rule));
  }

  /**
   * Get rule by ID
   */
  async findById(id: string): Promise<Rule> {
    const rule = await this.db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('id', '=', id)
      .executeTakeFirst();

    if (!rule) {
      throw new NotFoundException(`Rule with ID ${id} not found`);
    }

    return this.mapDbRuleToRule(rule);
  }

  /**
   * Create a new rule
   */
  async create(dto: CreateRuleDto, userId: string): Promise<Rule> {
    const existing = await this.db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('entity_name', '=', dto.entityName)
      .where('operation', '=', dto.operation)
      .where('rule_name', '=', dto.ruleName)
      .executeTakeFirst();

    if (existing) {
      throw new BadRequestException(
        `Rule ${dto.ruleName} already exists for ${dto.entityName}:${dto.operation}`
      );
    }

    const validation = await this.validateJDM(dto.jdmContent);
    if (!validation.valid) {
      throw new BadRequestException({ message: 'Invalid JDM content', errors: validation.errors });
    }

    const rule = await this.db
      .insertInto('sys_rule_definitions')
      .values({
        entity_name: dto.entityName,
        rule_name: dto.ruleName,
        operation: dto.operation.toUpperCase(),
        jdm_content: this.serializeJdm(dto.jdmContent),
        version: 1,
        is_active: true,
        created_by: userId,
        created_at: new Date(),
        updated_at: new Date(),
      } as any)
      .returningAll()
      .executeTakeFirst();

    this.logger.log(`Created rule ${rule.rule_name} for ${rule.entity_name}:${rule.operation}`);

    return this.mapDbRuleToRule(rule);
  }

  /**
   * Update an existing rule
   */
  async update(id: string, dto: UpdateRuleDto, userId: string): Promise<Rule> {
    const rule = await this.findById(id);

    if (dto.jdmContent) {
      const validation = await this.validateJDM(dto.jdmContent);
      if (!validation.valid) {
        throw new BadRequestException({ message: 'Invalid JDM content', errors: validation.errors });
      }
    }

    const updateData: Record<string, unknown> = {
      updated_at: new Date(),
      updated_by: userId,
    };

    if (dto.jdmContent) {
      updateData.jdm_content = dto.jdmContent;
      updateData.version = rule.version + 1;
    }

    if (dto.isActive !== undefined) {
      updateData.is_active = dto.isActive;
    }

    const updated = await this.db
      .updateTable('sys_rule_definitions')
      .set(updateData)
      .where('id', '=', id)
      .returningAll()
      .executeTakeFirst();

    this.logger.log(`Updated rule ${updated.rule_name} (version ${updated.version})`);

    return this.mapDbRuleToRule(updated);
  }

  /**
   * Delete a rule (soft delete by setting is_active = false)
   */
  async delete(id: string): Promise<void> {
    const rule = await this.findById(id);

    await this.db
      .updateTable('sys_rule_definitions')
      .set({
        is_active: false,
        updated_at: new Date(),
      })
      .where('id', '=', id)
      .execute();

    this.logger.log(`Deactivated rule ${rule.ruleName}`);
  }

  /**
   * Get rule history (all versions of a rule)
   */
  async getHistory(ruleId: string): Promise<Rule[]> {
    return [await this.findById(ruleId)];
  }


  /**
   * Store JDM as text, whichever way it arrived.
   *
   * The column is text and the engine parses it, so an object from the rule
   * table editor and a string from an older caller have to converge here —
   * otherwise the same rule reads back differently depending on who wrote it.
   */
  private serializeJdm(content: string | Record<string, unknown>): string {
    return typeof content === 'string' ? content : JSON.stringify(content);
  }

  /**
   * Validate JDM content
   */
  async validateJDM(jdmContent: string | Record<string, unknown>): Promise<{
    valid: boolean;
    errors: string[];
  }> {
    try {
      const parsed = typeof jdmContent === 'string' ? JSON.parse(jdmContent) : jdmContent;

      // A decision table is a complete rule on its own — it is what the rule
      // table editor writes. Demanding a node graph of it is what stopped the
      // editor being able to save anything at all.
      if (
        Array.isArray(parsed?.inputs) &&
        Array.isArray(parsed?.outputs) &&
        Array.isArray(parsed?.rules)
      ) {
        const errors: string[] = [];
        if (parsed.inputs.length === 0) errors.push('Add at least one input column to test against.');
        if (parsed.outputs.length === 0) {
          errors.push('Add at least one outcome column — a table that decides nothing does nothing.');
        }
        if (parsed.rules.length === 0) errors.push('Add at least one row.');
        for (const column of [...parsed.inputs, ...parsed.outputs]) {
          if (!String(column?.field ?? '').trim()) {
            errors.push(`Column "${column?.name ?? column?.id}" does not say which field it reads.`);
          }
        }
        return { valid: errors.length === 0, errors };
      }

      if (!parsed.nodes || !Array.isArray(parsed.nodes)) {
        return { valid: false, errors: ['JDM must have a nodes array'] };
      }

      if (!parsed.edges || !Array.isArray(parsed.edges)) {
        return { valid: false, errors: ['JDM must have an edges array'] };
      }

      const columnErrors = this.findIncompleteDecisionRows(parsed);
      if (columnErrors.length > 0) {
        return { valid: false, errors: columnErrors };
      }

      const engine = this.rulesEngine.getEngine();
      const decision = engine.createDecision(Buffer.from(this.serializeJdm(jdmContent)));
      await decision.evaluate({});

      return { valid: true, errors: [] };
    } catch (error) {
      return {
        valid: false,
        errors: [error instanceof Error ? error.message : String(error)],
      };
    }
  }

  /**
   * Catch the one JDM mistake that fails silently.
   *
   * zen-engine drops any decision-table row that does not carry a value for
   * every output column the table declares. It does not throw — `evaluate()`
   * just returns `[]`, which is indistinguishable from "no rules matched" and
   * from "no rules configured". Add an output column to an existing table
   * without backfilling the rows and every rule in it stops firing, with
   * nothing anywhere to say why.
   *
   * Rather than leave that as a comment nobody reads at 2am, refuse to save the
   * rule and name the rows and columns involved.
   */
  private findIncompleteDecisionRows(parsed: any): string[] {
    const errors: string[] = [];

    for (const node of parsed.nodes ?? []) {
      if (node?.type !== 'decisionTableNode') continue;

      const outputs = (node.content?.outputs ?? []) as Array<{ id?: string; field?: string }>;
      const rows = (node.content?.rules ?? []) as Array<Record<string, unknown>>;
      if (outputs.length === 0 || rows.length === 0) continue;

      rows.forEach((row, index) => {
        const missing = outputs
          .filter((output) => output.id && row[output.id] === undefined)
          .map((output) => `${output.id}${output.field ? ` (${output.field})` : ''}`);

        if (missing.length > 0) {
          const rowId = (row._id as string) || `row ${index + 1}`;
          errors.push(
            `Decision table "${node.name ?? node.id}" row "${rowId}" is missing output ` +
              `${missing.join(', ')}. zen-engine silently discards rows that do not set ` +
              `every declared output column, so the whole table would stop matching. ` +
              `Set the column to '' if the row has no value for it.`,
          );
        }
      });
    }

    return errors;
  }

  /**
   * Dry run - evaluate rule with sample context
   */
  async dryRun(jdmContent: string | Record<string, unknown>, context: Record<string, unknown>): Promise<{
    success: boolean;
    result?: unknown;
    errors?: string[];
  }> {
    try {
      const engine = this.rulesEngine.getEngine();
      // The editor holds its table as an object and posts it as one. Buffer.from
      // needs the serialised form, so an object goes through the same helper
      // that writes it to the column rather than reaching the engine as
      // "[object Object]".
      const decision = engine.createDecision(Buffer.from(this.serializeJdm(jdmContent)));
      const result = await decision.evaluate(context);

      return { success: true, result };
    } catch (error) {
      return {
        success: false,
        errors: [error instanceof Error ? error.message : String(error)],
      };
    }
  }

  /**
   * Migrate rules from JDM files to database
   */
  async migrateFromFileSystem(): Promise<{ migrated: number; errors: string[] }> {
    const errors: string[] = [];
    let migrated = 0;

    const entityOperations = [
      { file: 'bus_patient.jdm.json', entityName: 'bus_patient', operation: 'ALL' },
      { file: 'bus_practitioner.jdm.json', entityName: 'bus_practitioner', operation: 'ALL' },
      { file: 'bus_appointment.jdm.json', entityName: 'bus_appointment', operation: 'ALL' },
      { file: 'bus_encounter.jdm.json', entityName: 'bus_encounter', operation: 'ALL' },
      { file: 'bus_claim.jdm.json', entityName: 'bus_claim', operation: 'ALL' },
    ];

    for (const { file, entityName, operation } of entityOperations) {
      try {
        const jdmPath = join(__dirname, 'jdm', file);
        const jdmContent = readFileSync(jdmPath, 'utf-8');

        const parsed = JSON.parse(jdmContent);
        const ruleName = parsed.name || `${entityName}_${operation.toLowerCase()}_rule`;

        const existing = await this.db
          .selectFrom('sys_rule_definitions')
          .selectAll()
          .where('entity_name', '=', entityName)
          .where('operation', '=', operation)
          .where('rule_name', '=', ruleName)
          .executeTakeFirst();

        if (existing) {
          this.logger.log(`Rule ${ruleName} already exists, skipping migration`);
          continue;
        }

        await this.create(
          {
            entityName,
            ruleName,
            operation: operation as CreateRuleDto['operation'],
            jdmContent,
          },
          'system-migration'
        );

        migrated++;
        this.logger.log(`Migrated rule ${ruleName} from ${file}`);
      } catch (error) {
        const errorMsg = `Failed to migrate ${file}: ${error instanceof Error ? error.message : String(error)}`;
        this.logger.error(errorMsg);
        errors.push(errorMsg);
      }
    }

    return { migrated, errors };
  }

  /**
   * Validate data against business rules
   */
  async validate(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete' = 'create',
  ): Promise<{ valid: boolean; errors: string[]; warnings: string[] }> {
    const results = await this.evaluate(entityType, data, action);

    const errors: string[] = [];
    const warnings: string[] = [];

    for (const result of results) {
      if (result.errors?.length) {
        warnings.push(`Rules engine error: ${result.errors.join('; ')}`);
      }
      if (!result.matched) continue;

      for (const ruleAction of result.actions) {
        if (ruleAction.type === 'prevent') {
          const message = ruleAction.config.message as string | undefined;
          errors.push(message || `Rule violation: ${result.ruleName}`);
        } else if (ruleAction.type === 'validate') {
          const message = ruleAction.config.message as string | undefined;
          warnings.push(message || `Validation warning: ${result.ruleName}`);
        } else if (ruleAction.type === 'notify') {
          warnings.push(`Notification: ${result.ruleName}`);
        }
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
    };
  }

  /**
   * Execute rules and return results.
   *
   * `db` must be supplied when the caller already holds a transaction. Reading
   * the rule definitions off the pool instead would acquire a *second*
   * connection while the first is still held, and under concurrent writes that
   * exhausts the pool and deadlocks every in-flight request — each one holding
   * a connection while waiting for one that can never be released.
   */
  async evaluate(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete' = 'create',
    db: Kysely<any> = this.db,
  ): Promise<RuleEvaluationResult[]> {
    // Rules scoped to the specific operation plus rules that apply to ALL operations
    const rules = await db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('entity_name', '=', entityType)
      .where('operation', 'in', [action.toUpperCase(), 'ALL'])
      .where('is_active', '=', true)
      .execute();

    const results: RuleEvaluationResult[] = [];
    for (const rule of rules) {
      results.push(
        ...(await this.rulesEngine.evaluateRulesWithJDM(
          entityType,
          rule.jdm_content,
          data,
          action,
          rule.rule_name as string,
        ))
      );
    }
    return results;
  }

  /**
   * Report the side-effecting actions that would run for this record, without running them.
   * The promotion pipeline uses this to tell "nothing is associated with this entity" apart
   * from "something is associated and it succeeded" — the two lead to different doc_status paths.
   */
  async collectActionableActions(
    entityName: string,
    data: Record<string, unknown>,
    operation: 'create' | 'update' | 'delete',
  ): Promise<MatchedAction[]> {
    const results = await this.evaluate(entityName, data, operation);
    const actions: MatchedAction[] = [];

    for (const result of results) {
      if (!result.matched) continue;
      for (const action of result.actions) {
        if ((SIDE_EFFECTING_ACTIONS as readonly string[]).includes(action.type)) {
          actions.push({ ruleName: result.ruleName, type: action.type, config: action.config });
        }
      }
    }
    return actions;
  }

  /**
   * Execute the side-effecting rule actions (cascade, transform, trigger-workflow) for a record.
   *
   * Two modes:
   *   - default: log failures and carry on (the historical fire-and-forget behaviour)
   *   - options.throwOnError: rethrow the first failure so an enclosing transaction rolls back
   *
   * Pass options.db to run every write on a transaction.
   */
  async executeMatchedActions(
    entityName: string,
    entityId: string,
    data: Record<string, unknown>,
    operation: 'create' | 'update' | 'delete',
    options: RuleActionOptions = {},
  ): Promise<void> {
    const db = options.db ?? this.db;

    let results: RuleEvaluationResult[];
    try {
      // Pass `db` so a caller-supplied transaction is reused rather than a
      // second pool connection being taken while the first is still held.
      results = await this.evaluate(entityName, data, operation, db);
    } catch (err: any) {
      if (options.throwOnError) {
        throw new Error(`Could not evaluate business rules for ${entityName}: ${err?.message ?? err}`);
      }
      this.logger.warn(`executeMatchedActions: evaluate failed for ${entityName}: ${err?.message}`);
      return;
    }

    for (const result of results) {
      if (!result.matched) continue;
      for (const action of result.actions) {
        try {
          if (action.type === 'trigger-workflow') {
            const wfName = action.config.workflowName as string | undefined;
            if (!wfName) {
              this.logger.warn(`trigger-workflow action in rule "${result.ruleName}" has no workflowName — skipping`);
              continue;
            }
            this.logger.log(`Rule "${result.ruleName}" triggering workflow "${wfName}" for ${entityName}:${entityId}`);
            // Only hand our connection over when the caller opened a transaction —
            // otherwise the workflow service uses its own, as it always has.
            await this.workflowService.triggerByWorkflowName(wfName, entityName, entityId, operation, data, {
              db: options.db,
              throwOnError: options.throwOnError,
            });
          } else if (action.type === 'cascade-update') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const linkField = action.config.linkField as string | undefined;
            const updateData = action.config.updateData as Record<string, unknown> | undefined;
            if (targetEntity && linkField && updateData) {
              await db
                .updateTable(targetEntity as any)
                .set(updateData as any)
                .where(linkField as any, '=', entityId)
                .execute();
              this.logger.log(`Cascade-update: updated ${targetEntity} where ${linkField}=${entityId}`);
            }
          } else if (action.type === 'cascade-delete') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const linkField = action.config.linkField as string | undefined;
            if (targetEntity && linkField) {
              await db
                .deleteFrom(targetEntity as any)
                .where(linkField as any, '=', entityId)
                .execute();
              this.logger.log(`Cascade-delete: deleted from ${targetEntity} where ${linkField}=${entityId}`);
            } else {
              this.logger.warn(
                `cascade-delete in rule "${result.ruleName}" needs targetEntity and linkField — skipping`,
              );
            }
          } else if (action.type === 'cascade-create') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const createData = action.config.createData as Record<string, unknown> | undefined;
            const linkField = action.config.linkField as string | undefined;
            if (targetEntity && createData) {
              const now = new Date();
              await db
                .insertInto(targetEntity as any)
                .values({
                  ...createData,
                  // Link the new row back at the record that triggered the rule.
                  ...(linkField ? { [linkField]: entityId } : {}),
                  created_at: now,
                  updated_at: now,
                } as any)
                .execute();
              this.logger.log(`Cascade-create: inserted into ${targetEntity} for ${entityName}:${entityId}`);
            } else {
              this.logger.warn(
                `cascade-create in rule "${result.ruleName}" needs targetEntity and createData — skipping`,
              );
            }
          } else if (action.type === 'transform') {
            const transformData = action.config.transformData as Record<string, unknown> | undefined;
            if (transformData && Object.keys(transformData).length > 0) {
              await db
                .updateTable(entityName as any)
                .set({ ...transformData, updated_at: new Date() } as any)
                .where('id' as any, '=', entityId)
                .execute();
              this.logger.log(
                `Transform: applied ${Object.keys(transformData).join(', ')} to ${entityName}:${entityId}`,
              );
            } else {
              this.logger.warn(`transform in rule "${result.ruleName}" has no transformData — skipping`);
            }
          }
        } catch (err: any) {
          if (options.throwOnError) {
            throw new Error(
              `Rule "${result.ruleName}" action "${action.type}" failed: ${err?.message ?? err}`,
            );
          }
          this.logger.error(`executeMatchedActions: action "${action.type}" failed for rule "${result.ruleName}": ${err?.message}`);
        }
      }
    }
  }

    private mapDbRuleToRule(record: Record<string, unknown>): Rule {
    return {
      id: record.id as string,
      entityName: record.entity_name as string,
      ruleName: record.rule_name as string,
      operation: record.operation as string,
      jdmContent: record.jdm_content as string,
      version: record.version as number,
      isActive: record.is_active as boolean,
      createdBy: record.created_by as string,
      updatedBy: record.updated_by as string | undefined,
      createdAt: record.created_at as Date,
      updatedAt: record.updated_at as Date,
    };
  }
}

/**
 * Business Rules Engine Service — GoRules (zen-engine)
 *
 * Evaluates business rules using the GoRules zen-engine and
 * JSON Decision Model (JDM) files stored in ./jdm/.
 *
 * Each entity type maps to a dedicated JDM file:
 {{#each entities}}
 *   {{tableName}}  → jdm/{{tableName}}.jdm.json
 {{/each}}
 *
 * Decision tables use hitPolicy "collect" so all matching rows are
 * returned, enabling multiple validation errors in a single call.
 *
 * NOTE: zen-engine silently drops any rule row that does not set a value for
 * every output column the table declares. When adding an output column to a
 * decision table, give every existing row an explicit "''" for it, or the whole
 * table stops matching.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import { ZenEngine } from '@gorules/zen-engine';
import { readFileSync } from 'fs';
import { join } from 'path';

export interface RuleAction {
  type: 'validate' | 'notify' | 'prevent' | 'transform' | 'cascade-update' | 'cascade-delete' | 'cascade-create' | 'trigger-workflow';
  config: Record<string, unknown>;
}

export interface RuleEvaluationResult {
  ruleId: string;
  ruleName: string;
  matched: boolean;
  actions: RuleAction[];
  errors?: string[];
}

/**
 * Shape of each output row returned by a GoRules decision table.
 *
 * Everything past `ruleId` is action configuration: `workflowName` for
 * trigger-workflow, and `targetEntity` / `linkField` / `updateData` for the
 * cascade actions. Decision tables only need to emit the columns the action
 * they select actually uses.
 */
interface JdmViolation {
  action: string;
  message: string;
  ruleId: string;
  rule_id?: string;
  workflowName?: string;
  /** cascade-update | cascade-delete | cascade-create: table to act on */
  targetEntity?: string;
  /** cascade-update | cascade-delete: column on targetEntity holding this row's id */
  linkField?: string;
  /** cascade-update: column/value pairs to set (JSON object, or a JSON string) */
  updateData?: Record<string, unknown> | string;
  /** cascade-create: column/value pairs to insert (JSON object, or a JSON string) */
  createData?: Record<string, unknown> | string;
  /** transform: column/value pairs to apply to the row being written */
  transformData?: Record<string, unknown> | string;
}

@Injectable()
export class RulesEngine implements OnModuleDestroy {
  private readonly logger = new Logger(RulesEngine.name);

  /** Single ZenEngine instance — thread-safe, reused across requests */
  private readonly engine: ZenEngine;

  /** Maps entity type names to their JDM file names */
  private readonly jdmFiles: Record<string, string> = {
    {{#each entities}}
    {{tableName}}: '{{tableName}}.jdm.json',
    {{/each}}
  };

  constructor() {
    this.engine = new ZenEngine();
  }

  /** Release native resources when the NestJS module shuts down */
  onModuleDestroy(): void {
    this.engine.dispose();
  }

  /** Get the ZenEngine instance for external use */
  getEngine(): ZenEngine {
    return this.engine;
  }

  /**
   * Evaluate rules with provided JDM content (from database)
   */
  async evaluateRulesWithJDM(
    entityType: string,
    jdmContent: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete',
    dbRuleName?: string,
  ): Promise<RuleEvaluationResult[]> {
    this.logger.log(`Evaluating rules for ${entityType}:${action}`);

    try {
      const decision = this.engine.createDecision(Buffer.from(jdmContent));
      // `_operation` carries the CRUD verb. It is deliberately not called
      // `action`: that name belongs to the record. A model with an `action`
      // column could never fire its own rules against it, because the engine
      // had already replaced the value with "create"/"update" — and a required
      // -field rule on such a column could never fire at all, since the
      // injected value made the field look present even when it was omitted.
      // Rules read the operation from `_operation`; the payload is passed
      // through untouched.
      const result = await decision.evaluate({ ...data, _operation: action });

      let violations: JdmViolation[] = [];

      if (Array.isArray(result.result)) {
        violations = result.result as JdmViolation[];
      } else if (result.result && typeof result.result === 'object') {
        violations = [result.result as JdmViolation];
      }

      return violations.map((v) => ({
        ruleId: dbRuleName || v.ruleId || v.rule_id || 'unknown',
        ruleName: dbRuleName || v.ruleId || v.rule_id || 'unknown',
        matched: true,
        actions: [{ type: v.action as RuleAction['type'], config: this.toActionConfig(v) }],
      }));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`Error evaluating rules for ${entityType}: ${message}`);
      return [
        {
          ruleId: 'engine-error',
          ruleName: 'Rules Engine Error',
          matched: false,
          actions: [],
          errors: [message],
        },
      ];
    }
  }

  /**
   * Evaluate all rules for a given entity type and action.
   *
   * @param entityType  The bus_ table name (e.g. 'bus_patient')
   * @param data        The entity data to validate
   * @param action      The CRUD operation being performed
   * @returns           Array of matched rule results (empty if no violations)
   */
  async evaluateRules(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete',
  ): Promise<RuleEvaluationResult[]> {
    this.logger.log(`Evaluating rules for ${entityType}:${action}`);

    const jdmFile = this.jdmFiles[entityType];
    if (!jdmFile) {
      this.logger.debug(`No JDM rules configured for entity: ${entityType}`);
      return [];
    }

    const jdmPath = join(__dirname, 'jdm', jdmFile);
    let content: Buffer;
    try {
      content = readFileSync(jdmPath);
    } catch {
      this.logger.warn(`JDM file not found for ${entityType}: ${jdmPath}`);
      return [];
    }

    let violations: JdmViolation[] = [];
    try {
      const decision = this.engine.createDecision(content);
      // `_operation` carries the CRUD verb. It is deliberately not called
      // `action`: that name belongs to the record. A model with an `action`
      // column could never fire its own rules against it, because the engine
      // had already replaced the value with "create"/"update" — and a required
      // -field rule on such a column could never fire at all, since the
      // injected value made the field look present even when it was omitted.
      // Rules read the operation from `_operation`; the payload is passed
      // through untouched.
      const result = await decision.evaluate({ ...data, _operation: action });

      // hitPolicy "collect" returns an array; single-match returns an object or null
      if (Array.isArray(result.result)) {
        violations = result.result as JdmViolation[];
      } else if (result.result && typeof result.result === 'object') {
        violations = [result.result as JdmViolation];
      }
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`Error evaluating rules for ${entityType}: ${message}`);
      return [
        {
          ruleId: 'engine-error',
          ruleName: 'Rules Engine Error',
          matched: false,
          actions: [],
          errors: [message],
        },
      ];
    }

    return violations.map((v) => ({
      ruleId: v.ruleId,
      ruleName: v.ruleId,
      matched: true,
      actions: [{ type: v.action as RuleAction['type'], config: this.toActionConfig(v) }],
    }));
  }

  /**
   * Carry the whole decision-table output row into the action config.
   *
   * Only `message` and `workflowName` used to survive this step, which left the
   * cascade actions permanently unconfigurable — they read `targetEntity`,
   * `linkField` and `updateData`, and those were always undefined no matter what
   * the decision table emitted.
   */
  private toActionConfig(v: JdmViolation): Record<string, unknown> {
    return {
      message: v.message,
      workflowName: v.workflowName,
      targetEntity: v.targetEntity,
      linkField: v.linkField,
      updateData: this.asObject(v.updateData),
      createData: this.asObject(v.createData),
      transformData: this.asObject(v.transformData),
    };
  }

  /** Decision tables can emit an object or a JSON string; accept either. */
  private asObject(value: Record<string, unknown> | string | undefined): Record<string, unknown> | undefined {
    if (!value) return undefined;
    if (typeof value !== 'string') return value;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : undefined;
    } catch {
      this.logger.warn(`Rule action data is not valid JSON: ${value}`);
      return undefined;
    }
  }
}

