/**
 * Trigger-Workflow Integration Tests
 * Generated: {{generatedAt}}
 * Project: {{project.name}}
 *
 * Verifies the full chain: a business rule with action type "trigger-workflow"
 * causes the RulesService to invoke WorkflowService.triggerByWorkflowName,
 * which executes BPMN service tasks (UpdateEntity) and records the run.
 *
 * Tests are layered:
 *   1. RulesEngine   — evaluateRulesWithJDM returns trigger-workflow actions
 *   2. RulesService  — executeMatchedActions dispatches to WorkflowService
 *   3. WorkflowService — triggerByWorkflowName executes BPMN and updates entities
 */

import { describe, it, expect, beforeAll, afterAll } from 'bun:test';
import { RulesEngine } from '../src/modules/rules/rules-engine.service';
import { RulesService } from '../src/modules/rules/rules.service';
import { WorkflowService } from '../src/modules/workflow/workflow.service';

// ── JDM fixtures ─────────────────────────────────────────────────────────────

// A JDM decision table that emits a trigger-workflow action when appointment
// current_state transitions to 'completed'.
const TRIGGER_WORKFLOW_JDM = JSON.stringify({
  nodes: [
    { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
    {
      id: 'appointment-trigger-rule',
      type: 'decisionTableNode',
      name: 'Appointment Workflow Trigger',
      position: { x: 300, y: 0 },
      content: {
        hitPolicy: 'collect',
        inputs: [
          { id: 'i1', name: 'Current State', field: 'current_state' },
        ],
        outputs: [
          { id: 'o1', name: 'Action',        field: 'action' },
          { id: 'o2', name: 'Message',       field: 'message' },
          { id: 'o3', name: 'Rule ID',       field: 'ruleId' },
          { id: 'o4', name: 'Workflow Name', field: 'workflowName' },
        ],
        rules: [
          {
            _id: 'appointment-completed-trigger',
            i1:  '"completed"',
            o1:  "'trigger-workflow'",
            o2:  "'Appointment completed — trigger billing workflow'",
            o3:  "'appointment-completed-trigger'",
            o4:  "'GenerateClaimWorkflow'",
          },
        ],
      },
    },
    { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
  ],
  edges: [
    { id: 'e1', sourceId: 'input', targetId: 'appointment-trigger-rule' },
    { id: 'e2', sourceId: 'appointment-trigger-rule', targetId: 'output' },
  ],
});

// A JDM that is intentionally silent (no matching rows) for non-triggering states.
const SILENT_JDM = JSON.stringify({
  nodes: [
    { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
    {
      id: 'silent-rule',
      type: 'decisionTableNode',
      name: 'Silent Rule',
      position: { x: 300, y: 0 },
      content: {
        hitPolicy: 'collect',
        inputs: [{ id: 'i1', name: 'Current State', field: 'current_state' }],
        outputs: [
          { id: 'o1', name: 'Action',  field: 'action' },
          { id: 'o2', name: 'Message', field: 'message' },
          { id: 'o3', name: 'Rule ID', field: 'ruleId' },
        ],
        rules: [
          {
            _id: 'never-matches',
            i1: '"__never__"',
            o1: "'prevent'",
            o2: "'Should never fire'",
            o3: "'never-matches'",
          },
        ],
      },
    },
    { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
  ],
  edges: [
    { id: 'e1', sourceId: 'input', targetId: 'silent-rule' },
    { id: 'e2', sourceId: 'silent-rule', targetId: 'output' },
  ],
});

// BPMN XML with UpdateEntity service tasks for workflow execution testing.
const UPDATE_ENTITY_BPMN = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:erdwithai="http://erdwithai.com/extensions">
  <bpmn:process id="GenerateClaimWorkflow" isExecutable="true">
    <bpmn:startEvent id="start"/>
    <bpmn:serviceTask id="updateDocStatus" name="Update doc_status">
      <bpmn:extensionElements>
        <erdwithai:property name="nodeType" value="UpdateEntity"/>
        <erdwithai:property name="entity"   value="bus_appointment"/>
        <erdwithai:property name="field"    value="doc_status"/>
        <erdwithai:property name="value"    value="processing"/>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:serviceTask id="updateWorkflowStatus" name="Update workflow_status">
      <bpmn:extensionElements>
        <erdwithai:property name="nodeType" value="UpdateEntity"/>
        <erdwithai:property name="entity"   value="bus_appointment"/>
        <erdwithai:property name="field"    value="workflow_status"/>
        <erdwithai:property name="value"    value="triggered"/>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:sequenceFlow id="f1" sourceRef="start"            targetRef="updateDocStatus"/>
    <bpmn:sequenceFlow id="f2" sourceRef="updateDocStatus"  targetRef="updateWorkflowStatus"/>
  </bpmn:process>
</bpmn:definitions>`;

// ── Mock helpers ──────────────────────────────────────────────────────────────

/**
 * Builds a Kysely-compatible fluent chain mock.  Each selectFrom / insertInto /
 * updateTable call records the table name; execute() / executeTakeFirst() look
 * up the registered response for the most-recently-set context.
 */
function createMockDb(responses: {
  select?: Record<string, any[]>;
  selectOne?: Record<string, any>;
  insert?: Record<string, any>;
  update?: Record<string, void>;
}) {
  const updates: Array<{ table: string; fields: Record<string, unknown>; whereId: string | null }> = [];
  const inserts: Array<{ table: string; values: Record<string, unknown> }> = [];

  let currentOp   = 'select';
  let currentTable = '';
  let pendingSet: Record<string, unknown> = {};
  let pendingValues: Record<string, unknown> = {};

  const chain: any = {};

  chain.selectFrom = (table: string) => { currentOp = 'select'; currentTable = table; return chain; };
  chain.insertInto = (table: string) => { currentOp = 'insert'; currentTable = table; return chain; };
  chain.updateTable = (table: string) => { currentOp = 'update'; currentTable = table; return chain; };
  chain.deleteFrom  = (table: string) => { currentOp = 'delete'; currentTable = table; return chain; };

  // fluent no-op methods
  for (const m of ['selectAll', 'where', 'orderBy', 'limit', 'select', 'returningAll']) {
    chain[m] = (..._args: any[]) => chain;
  }

  chain.set = (data: Record<string, unknown>) => { pendingSet = data; return chain; };
  chain.values = (data: Record<string, unknown>) => { pendingValues = data; return chain; };

  chain.execute = () => {
    if (currentOp === 'update') {
      updates.push({ table: currentTable, fields: pendingSet, whereId: null });
      pendingSet = {};
    }
    if (currentOp === 'insert') {
      inserts.push({ table: currentTable, values: pendingValues });
      pendingValues = {};
    }
    const result = responses.select?.[currentTable] ?? [];
    return Promise.resolve(result);
  };

  chain.executeTakeFirst = () => {
    if (currentOp === 'insert') {
      const row = responses.insert?.[currentTable];
      inserts.push({ table: currentTable, values: pendingValues });
      pendingValues = {};
      return Promise.resolve(row);
    }
    const result = responses.selectOne?.[currentTable] ?? responses.select?.[currentTable]?.[0];
    return Promise.resolve(result ?? undefined);
  };

  return { chain, updates, inserts };
}

// ── Layer 1: RulesEngine ─────────────────────────────────────────────────────

describe('RulesEngine — trigger-workflow action', () => {
  let engine: RulesEngine;

  beforeAll(() => { engine = new RulesEngine(); });
  afterAll(() => { engine.onModuleDestroy(); });

  it('returns a trigger-workflow action when the appointment is completed', async () => {
    const data = { current_state: 'completed' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(1);
    const [result] = results;
    expect(result.matched).toBe(true);
    expect(result.actions[0].type).toBe('trigger-workflow');
    expect(result.actions[0].config.workflowName).toBe('GenerateClaimWorkflow');
    expect(result.actions[0].config.message).toContain('billing workflow');
  });

  it('returns no results when appointment state does not match the trigger condition', async () => {
    const data = { current_state: 'scheduled' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('returns no results for a null current_state (non-triggering)', async () => {
    const data = { current_state: null };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('does NOT fire trigger-workflow for an unrelated silent JDM', async () => {
    const data = { current_state: 'completed' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', SILENT_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('carries workflowName in the action config — accessible downstream', async () => {
    const data = { current_state: 'completed' };
    const [result] = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    const wfAction = result.actions.find((a) => a.type === 'trigger-workflow');
    expect(wfAction).toBeDefined();
    expect(typeof wfAction!.config.workflowName).toBe('string');
    expect((wfAction!.config.workflowName as string).length).toBeGreaterThan(0);
  });
});

// ── Layer 2: RulesService.executeMatchedActions ───────────────────────────────

describe('RulesService — executeMatchedActions dispatches trigger-workflow', () => {
  let engine: RulesEngine;

  const RULE_ROW = {
    id: 'rule-1',
    entity_name: 'bus_appointment',
    rule_name: 'appointment_completed_rule',
    operation: 'ALL',
    jdm_content: TRIGGER_WORKFLOW_JDM,
    is_active: true,
    version: 1,
    created_by: 'test',
    created_at: new Date(),
    updated_at: new Date(),
  };

  beforeAll(() => { engine = new RulesEngine(); });
