/**
 * Users and roles.
 *
 * Covers the seeded role hierarchy, faker-generated user registration at
 * volume, and the access-control surface that role membership drives.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  buildUser,
  config,
  faker,
  harness,
  HttpClient,
  login,
  permissions,
  register,
  reseed,
} from "../harness/index.ts";

interface SysRole {
  sys_role_id: string;
  name: string;
  is_master_role?: boolean;
  [key: string]: unknown;
}

interface SysUser {
  sys_user_id: string;
  email: string;
  name?: string;
  [key: string]: unknown;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("users and roles", () => {
  const createdUsers: Array<{ email: string; password: string }> = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 2);
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("seeds the system roles", async () => {
    const response = await harness.client.get("/sys/roles", { allowFailure: true });
    if (!response.ok) return; // route naming differs across generator versions

    const roles = rows<SysRole>(response.data);
    expect(roles.length).toBeGreaterThan(0);

    const names = roles.map((role) => String(role.name).toLowerCase());
    expect(names).toContain("administrator");
  });

  it("seeds the administrator user", async () => {
    const response = await harness.client.get("/sys/users", { allowFailure: true });
    if (!response.ok) return;

    const users = rows<SysUser>(response.data);
    const emails = users.map((user) => String(user.email).toLowerCase());

    expect(emails).toContain(config.admin.email.toLowerCase());
  });

  it("grants the administrator master access", async () => {
    const perms = await permissions(harness.client);

    expect(perms.role).toBeTruthy();
    expect(Array.isArray(perms.windows)).toBe(true);
  });

  it(
    `registers ${config.usersToCreate} faker-generated users`,
    async () => {
      let succeeded = 0;

      for (let i = 0; i < config.usersToCreate; i++) {
        const candidate = buildUser(i);
        // The administrator's client, not a fresh one: accounts are created
        // through the admin-only endpoint, so an anonymous caller is refused.
        const result = await register(
          harness.client,
          candidate.email,
          candidate.password,
          candidate.name
        );

        if (result.ok) {
          succeeded += 1;
          createdUsers.push({ email: candidate.email, password: candidate.password });
        }
      }

      console.log(`    registered ${succeeded}/${config.usersToCreate} users`);
      expect(succeeded).toBeGreaterThan(0);
    },
    Math.max(60_000, config.usersToCreate * 3000)
  );

  it("signs in as a registered user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = faker.helpers.arrayElement(createdUsers);
    const client = new HttpClient();
    const user = await login(client, candidate.email, candidate.password);

    expect(String(user.email).toLowerCase()).toBe(candidate.email.toLowerCase());
  });

  it("gives a fresh user narrower permissions than the administrator", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const theirs = await permissions(client);
    const admin = await permissions(harness.client);

    expect(theirs.isMaster).toBe(false);
    expect(theirs.windows.length).toBeLessThanOrEqual(admin.windows.length);
  });

  it("rejects duplicate registration", async () => {
    if (createdUsers.length === 0) return;

    const existing = createdUsers[0]!;
    const result = await register(
      harness.client,
      existing.email,
      existing.password,
      "Duplicate"
    );

    expect(result.ok).toBe(false);
  });

  it("refuses to create an account for an anonymous caller", async () => {
    // The reason there is no sign-up page: an account is something an
    // administrator grants, so the endpoint has to refuse everyone else.
    const candidate = buildUser(9_000);
    const anonymous = new HttpClient();
    const result = await register(
      anonymous,
      candidate.email,
      candidate.password,
      candidate.name
    );

    expect(result.ok).toBe(false);
    expect([401, 403]).toContain(result.status);
  });

  it("refuses to create an account for a signed-in non-administrator", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const fresh = buildUser(9_001);
    const result = await register(client, fresh.email, fresh.password, fresh.name);

    expect(result.ok).toBe(false);
    expect([401, 403]).toContain(result.status);
  });

  it("refuses rule creation for a non-admin user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const response = await client.post(
      "/rules",
      {
        entityName: "bus_probe",
        ruleName: "should-not-exist",
        operation: "ALL",
        jdmContent: "{}",
      },
      { allowFailure: true }
    );

    // Admin-only route: a non-admin must not get a 2xx.
    expect(response.ok).toBe(false);
    expect([400, 401, 403]).toContain(response.status);
  });
});

tanstack-start-nestjs/tests/suites/07-wo:
/**
 * Randomised workflow chaos.
 *
 * Registers cascade rules that reach across relationships, then performs
 * `E2E_RANDOM_WORKFLOW_OPS` random creates and updates against random
 * entities. The point is to exercise rule → workflow → cross-entity write
 * paths in combinations no hand-written test would enumerate, and to prove the
 * app stays consistent afterwards.
 *
 * The faker seed is fixed, so a failing run replays exactly.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it, sleep } from "../harness/testing.ts";
import {
  buildRecord,
  buildWorkflowTriggerJdm,
  config,
  createRule,
  entities,
  type EntityMeta,
  faker,
  firstTextField,
  harness,
  isTerminal,
  listRuns,
  relationships,
  reseed,
  runsForEntity,
  type RuleRecord,
} from "../harness/index.ts";

const suiteId = `e2e-chaos-${Date.now().toString(36)}`;

/** How long to let in-flight workflow dispatch settle before judging it. */
const SETTLE_MS = Math.min(config.workflowTimeoutMs, 5000);

interface Operation {
  kind: "create" | "update";
  entity: EntityMeta;
  id?: string;
  ok: boolean;
  status: number;
}

/** Relationships we can cascade along: source holds an FK to target. */
function cascadePairs(): Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> {
  const pairs: Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> = [];

  for (const rel of relationships) {
    const source = entities.find((e) => e.name === rel.sourceEntity);
    const target = entities.find((e) => e.name === rel.targetEntity);
    if (!source || !target) continue;

    const linkField =
      rel.foreignKey ??
      source.fields.find((f) => f.name === `${target.route.replace(/^bus_/, "")}_id`)?.name;
    if (!linkField) continue;

    pairs.push({ from: source, to: target, linkField });
  }

  return pairs;
}

describe("randomised workflow chaos", () => {
  const operations: Operation[] = [];
  const rules: RuleRecord[] = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 1);

    // A workflow trigger on every entity…
    for (const entity of entities) {
      const rule = await createRule(harness.client, {
        entityName: entity.tableName,
        ruleName: `${suiteId}-${entity.tableName}-any`,
        operation: "ALL",
        jdmContent: buildWorkflowTriggerJdm(entity, `${entity.tableName}-chaos-workflow`),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }

    // …plus cascade rules that write into a related entity.
    for (const pair of cascadePairs().slice(0, 5)) {
      const textField = firstTextField(pair.from);
      if (!textField) continue;

      const rule = await createRule(harness.client, {
        entityName: pair.to.tableName,
        ruleName: `${suiteId}-${pair.to.tableName}-cascade-${pair.from.tableName}`,
        operation: "UPDATE",
        jdmContent: buildWorkflowTriggerJdm(
          pair.to,
          `${pair.to.tableName}-cascade-workflow`,
          {
            targetEntity: pair.from.tableName,
            linkField: pair.linkField,
            updateData: `{ ${textField.name}: 'cascaded-${suiteId}' }`,
          }
        ),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("registers chaos rules across the model", () => {
    expect(rules.length).toBeGreaterThanOrEqual(entities.length);
  });

  it(
    `performs ${config.randomWorkflowOps} random writes across random entities`,
    async () => {
      const ordered = harness.orderedEntities();

      for (let i = 0; i < config.randomWorkflowOps; i++) {
        const entity = faker.helpers.arrayElement(ordered);
        const doUpdate = faker.datatype.boolean() && operations.some((op) => op.ok && op.id);

        if (doUpdate) {
          const candidates = operations.filter(
            (op) => op.ok && op.id && op.entity.route === entity.route
          );
          const previous = candidates.length > 0 ? faker.helpers.arrayElement(candidates) : null;

          if (previous?.id) {
            const textField = firstTextField(entity);
            const payload = textField
              ? { [textField.name]: `chaos-${faker.string.alphanumeric(8)}` }
              : buildRecord(entity);

            const response = await harness.client.patch(
              `/bus/${entity.route}/${previous.id}`,
              payload,
              { allowFailure: true }
            );

            operations.push({
              kind: "update",
              entity,
              id: previous.id,
              ok: response.ok,
              status: response.status,
            });
            continue;
          }
        }

        const created = await harness.createWithParents(entity);
        operations.push({
          kind: "create",
          entity,
          id: created?.id ? String(created.id) : undefined,
          ok: created !== null,
          status: created ? 201 : 0,
        });
      }

      expect(operations).toHaveLength(config.randomWorkflowOps);
    },
    Math.max(120_000, config.randomWorkflowOps * 3000)
  );

  it("never responds with a server error", () => {
    const serverErrors = operations.filter((op) => op.status >= 500);

    expect(
      serverErrors.map((op) => `${op.kind} ${op.entity.route} → ${op.status}`)
    ).toEqual([]);
  });

  it("succeeds on the majority of random operations", () => {
    const succeeded = operations.filter((op) => op.ok).length;

    // Some rejections are legitimate — a rule preventing a write is the system
    // working. A collapse to near-zero is not.
    expect(succeeded).toBeGreaterThan(operations.length * 0.5);
  });

  it("records workflow activity for the records it touched", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(0, 10);

    for (const op of touched) {
      const runs = await runsForEntity(harness.client, op.entity.tableName, op.id!);
      expect(Array.isArray(runs)).toBe(true);
    }
  });

  // The settle time below is 5s, which is exactly the default per-test
  // timeout — so without an explicit one this test could only pass if every
  // other line took no time at all, and it failed on timing alone.
  it("leaves every observed workflow run in a terminal state", async () => {
    // Give any in-flight dispatch a moment to settle before judging it.
    await sleep(SETTLE_MS);

    const runs = await listRuns(harness.client, { limit: 100 });
    const pending = runs.filter((run) => !isTerminal(run.status));

    // Recently-created runs are allowed to still be working.
    const stuck = pending.filter(
      (run) =>
        run.created_at !== undefined &&
        Date.now() - new Date(String(run.created_at)).getTime() > 30_000
    );

    expect(stuck.map((run) => `${run.workflow_name}:${run.status}`)).toEqual([]);
  }, SETTLE_MS * 4);

  it("keeps every touched record readable afterwards", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(-20);

    for (const op of touched) {
      const response = await harness.client.get(`/bus/${op.entity.route}/${op.id}`, {
        allowFailure: true,
      });

      // 404 is acceptable only if a cascade-delete rule removed it.
      expect([200, 404]).toContain(response.status);
    }
  });
});

tanstack-start-nestjs/tests/harness/work:
/**
 * Workflow helpers.
 *
 * A rule action of type `trigger-workflow` enqueues a run. Runs are async, so
 * everything here polls to a terminal state rather than assuming completion.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { config } from "./config.ts";
import type { HttpClient } from "./http.ts";
import { sleep } from "./testing.ts";

export interface WorkflowRun {
  id?: string;
  run_id?: string;
  workflow_name?: string;
  entity_name?: string;
  entity_id?: string;
  status?: string;
  error_details?: unknown;
  created_at?: string;
  [key: string]: unknown;
}

const TERMINAL = new Set(["completed", "success", "succeeded", "failed", "error", "cancelled"]);
const FAILED = new Set(["failed", "error", "cancelled"]);

export function isTerminal(status?: string): boolean {
  return !!status && TERMINAL.has(status.toLowerCase());
}

export function isFailure(status?: string): boolean {
  return !!status && FAILED.has(status.toLowerCase());
}

function unwrap(body: unknown): WorkflowRun[] {
  if (Array.isArray(body)) return body as WorkflowRun[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as WorkflowRun[];
    if (Array.isArray(record.runs)) return record.runs as WorkflowRun[];
  }
  return [];
}

export async function listRuns(
  client: HttpClient,
  filters: { status?: string; limit?: number } = {}
): Promise<WorkflowRun[]> {
  const params = new URLSearchParams();
  if (filters.status) params.set("status", filters.status);
  if (filters.limit) params.set("limit", String(filters.limit));
  const query = params.toString();
  const response = await client.get(`/workflows/runs${query ? `?${query}` : ""}`, {
    allowFailure: true,
  });
  return response.ok ? unwrap(response.data) : [];
}

export async function getRun(client: HttpClient, runId: string): Promise<WorkflowRun | null> {
  const response = await client.get<WorkflowRun>(`/workflows/runs/${runId}`, {
    allowFailure: true,
  });
  return response.ok ? response.data : null;
}

/** Workflow runs recorded against one entity record. */
export async function runsForEntity(
  client: HttpClient,
  entityName: string,
  entityId: string
): Promise<WorkflowRun[]> {
  const response = await client.get(`/workflows/entity/${entityName}/${entityId}`, {
    allowFailure: true,
  });
  return response.ok ? unwrap(response.data) : [];
}

export async function retryRun(client: HttpClient, runId: string): Promise<boolean> {
  const response = await client.post(`/workflows/runs/${runId}/retry`, {}, { allowFailure: true });
  return response.ok;
}

/**
 * Wait until at least one workflow run exists for a record and has reached a
 * terminal state. Resolves with whatever runs exist when the deadline passes —
 * callers decide whether an empty result is a failure, because workflow
 * dispatch is fire-and-forget in some configurations.
 */
export async function waitForEntityRuns(
  client: HttpClient,
  entityName: string,
  entityId: string,
  options: { timeoutMs?: number; requireTerminal?: boolean } = {}
): Promise<WorkflowRun[]> {
  const timeoutMs = options.timeoutMs ?? config.workflowTimeoutMs;
  const deadline = Date.now() + timeoutMs;
  let runs: WorkflowRun[] = [];

  while (Date.now() < deadline) {
    runs = await runsForEntity(client, entityName, entityId);
    if (runs.length > 0) {
      if (!options.requireTerminal) return runs;
      if (runs.every((run) => isTerminal(run.status))) return runs;
    }
    await sleep(400);
  }

  return runs;
}

/** Poll one run until terminal. Returns the final run, or null if it vanished. */
export async function waitForRun(
  client: HttpClient,
  runId: string,
  timeoutMs: number = config.workflowTimeoutMs
): Promise<WorkflowRun | null> {
  const deadline = Date.now() + timeoutMs;
  let run: WorkflowRun | null = null;

  while (Date.now() < deadline) {
    run = await getRun(client, runId);
    if (run && isTerminal(run.status)) return run;
    await sleep(400);
  }
  return run;
}

// ── Multi-step workflow authoring ───────────────────────────────────────────

/**
 * One step of a workflow, as the BPMN executor reads it.
 *
 * `props` are the `erdwithai:property` entries the executor looks for. The
 * builder below does not validate them — a suite asserting on a mis-typed
 * property should see the executor skip that node, which is the behaviour worth
 * testing.
 */
export interface WorkflowStep {
  id: string;
  name: string;
  props: Record<string, string>;
}

function escapeXmlAttr(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/**
 * Build executable BPMN from an ordered list of steps.
 *
 * Steps are wired start → s1 → s2 → … → end, because the executor walks the
 * sequence flows: a multi-step workflow only means anything if the steps run in
 * the order they were written.
 */
export function buildWorkflowBpmn(processId: string, steps: WorkflowStep[]): string {
  const tasks = steps
    .map((step) => {
      const props = Object.entries(step.props)
        .map(([k, v]) => `          <erdwithai:property name="${k}" value="${escapeXmlAttr(v)}" />`)
        .join("\n");
      return `    <bpmn:serviceTask id="${step.id}" name="${escapeXmlAttr(step.name)}">
      <bpmn:extensionElements>
        <erdwithai:properties xmlns:erdwithai="http://erdwithai.dev/bpmn">
${props}
        </erdwithai:properties>
      </bpmn:extensionElements>
    </bpmn:serviceTask>`;
    })
    .join("\n");

  const ids = ["start", ...steps.map((s) => s.id), "end"];
  const flows = ids
    .slice(0, -1)
    .map((from, i) => `    <bpmn:sequenceFlow id="flow_${i}" sourceRef="${from}" targetRef="${ids[i + 1]}" />`)
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" id="defs_${processId}" targetNamespace="http://erdwithai.dev/bpmn">
  <bpmn:process id="${processId}" isExecutable="true">
    <bpmn:startEvent id="start" name="Start" />
${tasks}
${flows}
    <bpmn:endEvent id="end" name="Done" />
  </bpmn:process>
</bpmn:definitions>
`;
}

export interface WorkflowDefinitionRecord {
  id: string;
  name: string;
  entity_name?: string;
  entityName?: string;
  trigger_type?: string;
}

/** Register a workflow definition through the admin API. */
export async function createWorkflowDefinition(
  client: HttpClient,
  input: {
    name: string;
