/**
 * Business Rules Seed
 * Loads the generated GoRules JDM decision models into sys_rule_definitions
 * so business rules are enforced on entity create/update/delete out of the box.
 *
 * Generated: {{now}}
 */

import * as fs from 'fs';
import * as path from 'path';
import { Kysely } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

const JDM_DIR = path.join(__dirname, '..', 'src', 'modules', 'rules', 'jdm');

const RULES = [
  {{#each entities}}
  { file: '{{tableName}}.jdm.json', entityName: '{{tableName}}', ruleName: '{{tableName}}_validation', operation: 'ALL' },
  {{/each}}
];

// Business rules authored in the model's `%%rule` sections, compiled from their
// decision flowcharts to GoRules JDM. These are the rules a designer drew; they
// are seeded alongside the generated validation rules and are editable in the
// admin rules editor afterwards.
const AUTHORED_RULES = [
  {{#each compiledRules}}
  {
    entityName: '{{tableName}}',
    ruleName: '{{name}}',
    operation: '{{operation}}',
    priority: {{priority}},
    jdmContent: '{{{jdmContentEscaped}}}',
  },
  {{/each}}
];

// Workflows are not triggered by seeded rules.
//
// The generator seeds a workflow definition per entity per operation (see
// 05_workflow_definitions.ts), and the promotion pipeline runs the matching
// definition automatically on every write. A seeded `trigger-workflow` rule
// naming the same definition ran it a second time, so one create produced
// duplicate workflow runs and duplicate side effects.
//
// `trigger-workflow` remains available as a rule action for rules you author
// yourself, where choosing a workflow by name is the point.

export async function seed(db: Kysely<any>): Promise<void> {
  const now = new Date();

  for (const rule of RULES) {
    const jdmPath = path.join(JDM_DIR, rule.file);
    if (!fs.existsSync(jdmPath)) {
      console.warn(`  ⚠ JDM file not found, skipping rule seed: ${jdmPath}`);
      continue;
    }

    const jdmContent = fs.readFileSync(jdmPath, 'utf-8');
    // Fail fast on malformed JDM rather than seeding a broken rule
    JSON.parse(jdmContent);

    const existing = await db
      .selectFrom('sys_rule_definitions')
      .select('id')
      .where('entity_name', '=', rule.entityName)
      .where('operation', '=', rule.operation)
      .where('rule_name', '=', rule.ruleName)
      .executeTakeFirst();

    if (existing) {
      await db
        .updateTable('sys_rule_definitions')
        .set({ jdm_content: jdmContent, is_active: true, updated_by: 'seed', updated_at: now })
        .where('id', '=', (existing as any).id)
        .execute();
      console.log(`  ↻ Updated business rule: ${rule.entityName} (${rule.operation})`);
    } else {
      await db
        .insertInto('sys_rule_definitions')
        .values({
          id: uuidv4(),
          entity_name: rule.entityName,
          rule_name: rule.ruleName,
          operation: rule.operation,
          jdm_content: jdmContent,
          version: 1,
          is_active: true,
          created_by: 'seed',
          created_at: now,
          updated_at: now,
        } as any)
        .execute();
      console.log(`  ✓ Seeded business rule: ${rule.entityName} (${rule.operation})`);
    }
  }
  await seedAuthoredRules(db);
}

export async function seedAuthoredRules(db: Kysely<any>): Promise<void> {
  const now = new Date();

  for (const rule of AUTHORED_RULES) {
    const existing = await db
      .selectFrom('sys_rule_definitions')
      .select('id')
      .where('entity_name', '=', rule.entityName)
      .where('rule_name', '=', rule.ruleName)
      .executeTakeFirst();

    if (existing) {
      await db
        .updateTable('sys_rule_definitions')
        .set({ jdm_content: rule.jdmContent, operation: rule.operation as any, is_active: true, updated_by: 'seed', updated_at: now })
        .where('id', '=', (existing as any).id)
        .execute();
      console.log(`  \u21bb Updated authored rule: ${rule.ruleName} (${rule.entityName} ${rule.operation})`);
    } else {
      await db
        .insertInto('sys_rule_definitions')
        .values({
          id: uuidv4(),
          entity_name: rule.entityName,
          rule_name: rule.ruleName,
          operation: rule.operation as any,
          jdm_content: rule.jdmContent,
          version: 1,
          is_active: true,
          created_by: 'seed',
          created_at: now,
          updated_at: now,
        } as any)
        .execute();
      console.log(`  \u2713 Seeded authored rule: ${rule.ruleName} (${rule.entityName} ${rule.operation})`);
    }
  }
}

common/seeds/entity-categories.ts.hbs:
/**
 * Entity Categories Seed
 *
 * Creates the Application Dictionary categories declared in the model and
 * assigns each business entity to its category. The dashboard renders one
 * block per category, ordered by name.
 *
 * Idempotent: re-running updates existing categories in place (matched on
 * `code`) rather than duplicating them, and only re-assigns entities that are
 * still uncategorised or whose category no longer exists.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import type { Kysely } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

interface CategorySeed {
  name: string;
  code: string;
  description: string | null;
  icon: string | null;
  color: string | null;
  seqNo: number;
  isDefault: boolean;
  /** Physical table names (bus_*) that belong to this category. */
  tables: string[];
}

const CATEGORIES: CategorySeed[] = [
{{#each categories}}
  {
    name: '{{name}}',
    code: '{{code}}',
    description: {{#if description}}'{{description}}'{{else}}null{{/if}},
    icon: {{#if icon}}'{{icon}}'{{else}}null{{/if}},
    color: {{#if color}}'{{color}}'{{else}}null{{/if}},
    seqNo: {{seqNo}},
    isDefault: {{#if isDefault}}true{{else}}false{{/if}},
    tables: [{{#each tables}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

export async function seed(db: Kysely<any>): Promise<void> {
  if (CATEGORIES.length === 0) {
    console.log('  ⚠ No entity categories declared — skipping');
    return;
  }

  // A single default is enforced by a partial unique index; clear the flag
  // first so re-seeding a changed default never trips it.
  await db.updateTable('sys_category').set({ is_default: false } as any).execute();

  const codeToId = new Map<string, string>();

  for (const category of CATEGORIES) {
    const existing = await db
      .selectFrom('sys_category')
      .select('sys_category_id')
      .where('code', '=', category.code)
      .executeTakeFirst();

    const values = {
      name: category.name,
      code: category.code,
      description: category.description,
      icon: category.icon,
      color: category.color,
      seq_no: category.seqNo,
      is_default: category.isDefault,
      is_active: true,
      updated_at: new Date(),
      updated_by: 'system',
    };

    if (existing) {
      await db
        .updateTable('sys_category')
        .set(values as any)
        .where('sys_category_id', '=', existing.sys_category_id)
        .execute();
      codeToId.set(category.code, existing.sys_category_id);
      console.log(`  ✓ Updated category: ${category.name}`);
    } else {
      const id = uuidv4();
      await db
        .insertInto('sys_category')
        .values({
          sys_category_id: id,
          ...values,
          created_at: new Date(),
          created_by: 'system',
        } as any)
        .execute();
      codeToId.set(category.code, id);
      console.log(`  ✓ Created category: ${category.name}`);
    }
  }

  // Assign entities. sys_table rows are matched on table_name, which the
  // dictionary seed has already created.
  let assigned = 0;

  for (const category of CATEGORIES) {
    const categoryId = codeToId.get(category.code);
    if (!categoryId || category.tables.length === 0) continue;

    const result = await db
      .updateTable('sys_table')
      .set({ sys_category_id: categoryId } as any)
      .where('table_name', 'in', category.tables)
      .executeTakeFirst();

    assigned += Number(result?.numUpdatedRows ?? 0);
  }

  // Anything still uncategorised goes to the default, so the dashboard never
  // has to render an orphan group.
  const fallback = CATEGORIES.find((category) => category.isDefault);
  if (fallback) {
    const fallbackId = codeToId.get(fallback.code);
    if (fallbackId) {
      await db
        .updateTable('sys_table')
        .set({ sys_category_id: fallbackId } as any)
        .where('sys_category_id', 'is', null)
        .where('table_name', 'like', 'bus_%')
        .execute();
    }
  }

  console.log(`  ✓ Assigned ${assigned} entities to ${CATEGORIES.length} categories`);
}

common/seeds/users-and-roles.ts.hbs:
/**
 * Users and Roles Seed
 * Creates system roles and initial users with Better-Auth integration
 * Sign-in credentials are created through Better Auth's own API, so the rows
 * always match the installed version's schema and hasher.
 * Default password for all users: "admin123" — long enough for the configured
 * minPasswordLength; change it before this runs anywhere real.
 *
 * Generated: {{now}}
 */

import { Kysely } from 'kysely';
import { v4 as uuidv4 } from 'uuid';


interface RoleDefinition {
  name: string;
  description: string;
  level: 'S' | 'C';
  canExport: boolean;
  canReport: boolean;
}

interface UserDefinition {
  email: string;
  name: string;
  roleName: string;
  description: string;
}

/**
 * The roles this application has, and they come from the model.
 *
 * They used to be four fixed placeholders — Administrator, Manager, Analyst,
 * User — which meant an application generated from a model declaring
 * `role:support_agent` seeded no account that held it. Every restriction the
 * model wrote was therefore invisible: the administrator bypasses all of them,
 * and nobody else held anything.
 *
 * Now every role named by a `%%rbac` directive is seeded, one account holds
 * each, and `Administrator` and `User` remain as the two ends to compare
 * against — the account that bypasses everything, and the account that holds
 * nothing.
 */
const ROLES: RoleDefinition[] = [
{{#each access.roles}}
  {
    name: '{{this.name}}',
    description: '{{this.description}}',
    level: '{{#if this.isAdmin}}S{{else}}C{{/if}}',
    canExport: {{#if this.isAdmin}}true{{else}}true{{/if}},
    canReport: true,
  },
{{/each}}
];

/** Seeded for every demo account; change it before anything real runs here. */
const DEFAULT_PASSWORD = 'admin123';

/**
 * One account per role.
 *
 * Signing in as `support.agent@…` is the only way to see what the model's
 * access rules actually did — the administrator bypasses them, so an
 * application with a single account cannot demonstrate its own authorization.
 */
const USERS: UserDefinition[] = [
{{#each access.users}}
  {
    email: '{{this.email}}',
    name: '{{this.name}}',
    roleName: '{{this.roleName}}',
    description: '{{this.description}}',
  },
{{/each}}
];

/**
 * Which entities each role may look at, from the model's `read` restrictions.
 *
 * Empty unless the model restricted reading. That is deliberate and is
 * explained at length in `packages/generator/src/rbac/roles.ts`: a model
 * protecting *deletion* of an entity is not asking for that entity to disappear
 * from everyone's navigation, and only a `read` rule says who an entity belongs
 * to.
 */
export const ENTITY_VISIBILITY: Record<string, string[]> = {
{{#each access.entityVisibility}}
  '{{@key}}': [{{#each this}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}],
{{/each}}
};

export async function seed(db: Kysely<any>): Promise<void> {
  const now = new Date();
  const createdBy = 'system';

  const { initAuth } = await import('../src/lib/better-auth');
  const auth = await initAuth();

  console.log('🔐 Creating users and roles...');

  // ============================================================================
  // Create Roles
  // ============================================================================
  const roleMap = new Map<string, string>();

  for (const roleDef of ROLES) {
    const existing = await db
      .selectFrom('sys_role')
      .select('sys_role_id')
      .where('name', '=', roleDef.name)
      .executeTakeFirst();

    let roleId: string;
    if (existing) {
      roleId = existing.sys_role_id;
      console.log(`  ✓ Role "${roleDef.name}" already exists`);
    } else {
      roleId = uuidv4();
      await db
        .insertInto('sys_role')
        .values({
          sys_role_id: roleId,
          name: roleDef.name,
          description: roleDef.description,
          user_level: roleDef.level,
          is_master_role: roleDef.level === 'S',
          is_can_export: roleDef.canExport,
          is_can_report: roleDef.canReport,
          is_personal_lock: false,
          is_personal_access: false,
          max_query_records: 0,
          is_show_accounting: roleDef.level === 'S',
          entity_type: 'D',
          is_active: true,
          created_by: createdBy,
          updated_by: createdBy,
          created_at: now,
          updated_at: now,
        })
        .execute();
      console.log(`  ✓ Created role "${roleDef.name}"`);
    }
    roleMap.set(roleDef.name, roleId);
  }

  // ============================================================================
  // Create Users with Better-Auth Integration
  // ============================================================================
  for (const userDef of USERS) {
    const roleId = roleMap.get(userDef.roleName);
    if (!roleId) {
      console.error(`  ✗ Role "${userDef.roleName}" not found for user ${userDef.email}`);
      continue;
    }

    // Create or retrieve sys_user
    const existingSysUser = await db
      .selectFrom('sys_user')
      .select('sys_user_id')
      .where('email', '=', userDef.email)
      .executeTakeFirst();

    let sysUserId: string;
    if (existingSysUser) {
      sysUserId = existingSysUser.sys_user_id;
      console.log(`  ✓ User ${userDef.email} already exists`);
    } else {
      sysUserId = uuidv4();
      await db
        .insertInto('sys_user')
        .values({
          sys_user_id: sysUserId,
          name: userDef.name,
          email: userDef.email,
          password_hash: 'managed-by-better-auth',
          description: userDef.description,
          is_system_user: userDef.roleName === 'Administrator',
          is_sales_rep: false,
          login_failure_count: 0,
          is_locked: false,
          is_account_verified: true,
          default_sys_role_id: roleId,
          entity_type: 'D',
          is_active: true,
          created_by: createdBy,
          updated_by: createdBy,
          created_at: now,
          updated_at: now,
        })
        .execute();
      console.log(`  ✓ Created sys_user: ${userDef.email}`);
    }

    // Assign role
    await db
      .insertInto('sys_user_roles')
      .values({
        sys_user_roles_id: uuidv4(),
        sys_user_id: sysUserId,
        sys_role_id: roleId,
        entity_type: 'D',
        is_active: true,
        created_by: createdBy,
        updated_by: createdBy,
        created_at: now,
        updated_at: now,
      })
      .onConflict((oc) => oc.doNothing())
      .execute();

    // Create the sign-in credentials through Better Auth itself.
    //
    // These rows used to be written here by hand — a `user` row, an `account`
    // row, and a password hash copied from some earlier release. Every one of
    // those is the library's private business, and each drifted: the hash no
    // longer matched the verifier, and `account` grew a NOT NULL column the
    // insert knew nothing about. Asking Better Auth to create the account means
    // the rows are whatever the installed version says they should be, and this
    // seed cannot fall out of step with it again.
    const existingBaUser = await db
      .selectFrom('user')
      .select('id')
      .where('email', '=', userDef.email)
      .executeTakeFirst();

    if (!existingBaUser) {
      await auth.api.signUpEmail({
        body: { email: userDef.email, password: DEFAULT_PASSWORD, name: userDef.name },
      });

      // Better Auth owns the identity; the application's own columns — which
      // role this user holds, and which sys_user they map to — are ours to set.
      await db
        .updateTable('user')
        .set({
          role: userDef.roleName === 'Administrator' ? 'admin' : 'user',
          sysUserId: sysUserId,
        })
        .where('email', '=', userDef.email)
        .execute();

      console.log(`  ✓ Created better-auth user: ${userDef.email} (password: "${DEFAULT_PASSWORD}")`);
    }
  }

  console.log('✓ Users and roles seeded successfully');
  console.log('\n📋 Default Credentials:');
  console.log(`   All users can log in with password: "${DEFAULT_PASSWORD}"`);
  console.log('\n👥 Users Created:');
  for (const user of USERS) {
    console.log(`   - ${user.email} (${user.roleName})`);
  }

  // What each role will actually see. Printed because "the roles were seeded"
  // and "the roles see different applications" are different claims, and this
  // is the one worth checking after a migration.
  const owned = new Map<string, string[]>();
  for (const [entity, roles] of Object.entries(ENTITY_VISIBILITY)) {
    for (const role of roles) {
      owned.set(role, [...(owned.get(role) ?? []), entity]);
    }
  }
  if (owned.size > 0) {
    console.log('\n🔐 Entities per functional role:');
    for (const [role, entities] of [...owned].sort()) {
      console.log(`   - ${role}: ${entities.length} (${entities.join(', ')})`);
    }
    console.log('   - Administrator: every entity, and bypasses every restriction');
  }
}

